/** Strip markdown code blocks and inline code from text before scanning. */
function stripCode(text) {
  return text
    .replace(/```[\s\S]*?```/g, '')
    .replace(/`[^`]*`/g, '')
    .replace(/https?:\/\/\S+/g, '');
}

/** Extract all issue numbers from a string using a pattern. */
function extractNums(text, re) {
  const nums = new Set();
  let m;
  re.lastIndex = 0;
  while ((m = re.exec(text)) !== null) nums.add(parseInt(m[1], 10));
  return nums;
}

/** Extract bare #N refs (not preceded by alphanumeric). */
function extractBareRefs(text) {
  const cleaned = stripCode(text);
  const re = /(?<![a-zA-Z0-9_])#(\d+)/g;
  return extractNums(cleaned, re);
}

// ── Fetch recent merged PRs (up to 100) ───────────────────────────
const { data: mergedPRs } = await github.rest.pulls.list({
  owner: context.repo.owner,
  repo: context.repo.repo,
  state: 'closed',
  sort: 'updated',
  direction: 'desc',
  per_page: 100,
});

const merged = mergedPRs.filter(pr => pr.merged_at);
console.log(`Found ${merged.length} recently merged PRs to check.`);

const findings = [];

for (const pr of merged) {
  const body  = pr.body  || '';
  const title = pr.title || '';
  const combined = `${title}\n${body}`;

  const closedByKeyword = extractNums(combined, CLOSE_KEYWORDS);

const allReferenced = extractBareRefs(combined);
const unlinked = [...allReferenced].filter(n => !closedByKeyword.has(n));

if (unlinked.length === 0) continue;

for (const issueNumber of unlinked) {
  let issue;
  try {
    issue = (await github.rest.issues.get({
      owner: context.repo.owner,
      repo: context.repo.repo,
      issue_number: issueNumber,
    })).data;
  } catch (_) {
    continue;
  }

  if (issue.state !== 'open') continue;
  if (issue.pull_request) continue;

  const labels = issue.labels.map(l => l.name);
  const hasBounty = labels.some(l => /^bounty:\s*[\d.]+\s*ETH$/i.test(l));
  if (!hasBounty) continue;

  findings.push({ issue, pr, labels });

  if (dryRun) {
    console.log(`[DRY RUN] Issue #${issueNumber} ("${issue.title}") is still open and referenced (but not closed) by merged PR #${pr.number} — would post alert.`);
    continue;
  }

  const { data: existingComments } = await github.rest.issues.listComments({
    owner: context.repo.owner,
    repo: context.repo.repo,
    issue_number: issueNumber,
    per_page: 100,
  });
  const alreadyAlerted = existingComments.some(
    c => c.body && c.body.includes('<!-- bounty-audit-alert -->')
  );
  if (alreadyAlerted) {
    console.log(`Issue #${issueNumber} already has an audit alert comment. Skipping.`);

  continue;
}

try {
  await github.rest.issues.getLabel({
    owner: context.repo.owner,
    repo: context.repo.repo,
    name: AUDIT_LABEL,
  });
} catch (_) {
  await github.rest.issues.createLabel({
    owner: context.repo.owner,
    repo: context.repo.repo,
    name: AUDIT_LABEL,
    color: 'e11d48',
    description: 'Issue was referenced but not closed by a merged PR — needs manual close & bounty queue',
  });
}
try {
  await github.rest.issues.addLabels({
    owner: context.repo.owner,
    repo: context.repo.repo,
    issue_number: issueNumber,
    labels: [AUDIT_LABEL],
  });
} catch (e) {
  console.warn(`Could not add label to issue #${issueNumber}: ${e.message}`);
}

const bountyLabel = labels.find(l => /^bounty:\s*[\d.]+\s*ETH$/i.test(l));
const commentBody = [
  '<!-- bounty-audit-alert -->',
  '## ⚠️ Bounty Audit Alert',
  '',
  `This issue has a **${bountyLabel}** and appears to have been implemented by merged PR #${pr.number} ("${pr.title}"), but it was **not automatically closed** because the PR did not include a \`Closes #${issueNumber}\` keyword.`,
  '',
  '**Action required for @TheJollyLaMa:**',
  `1. Confirm that PR #${pr.number} fully implements this issue.`,

      `2. Close this issue manually if confirmed.`,
      `3. Use the [**Manual Bounty Queue**](../../actions/workflows/bounty-payout.yml) workflow to retroactively queue the payout:`,
      `   - Set \`issue_number\` = \`${issueNumber}\``,
      `   - Set \`pr_number\` = \`${pr.number}\``,
      '',
      '> 💡 To prevent this in future PRs, contributors should use `Closes #N` in the PR description.',
    ].join('\n');

    await github.rest.issues.createComment({
      owner: context.repo.owner,
      repo: context.repo.repo,
      issue_number: issueNumber,
      body: commentBody,
    });

    console.log(`Posted audit alert on issue #${issueNumber} (referenced by PR #${pr.number}).`);
  }
}

if (findings.length === 0) {
  console.log('✅ No open bounty issues with unlinked merged PRs found.');
} else {
  console.log(`\n📋 Audit summary: ${findings.length} finding(s):`);
  for (const { issue, pr } of findings) {
    console.log(`  - Issue #${issue.number} ("${issue.title}") ← PR #${pr.number} ("${pr.title}")`);
  }
}

    repo:  context.repo.repo,
    name:  labelName,
  });
  console.log(`Label "${labelName}" already exists.`);
} catch (e) {
  if (e.status === 404) {
    await github.rest.issues.createLabel({
      owner:       context.repo.owner,
      repo:        context.repo.repo,
      name:        labelName,
      color:       labelColor,
      description: labelDesc,
    });
    console.log(`Created label "${labelName}".`);
  } else {
    throw e;
  }
}

// ── 2. Apply the label to the issue ────────────────────────────
await github.rest.issues.addLabels({
  owner:        context.repo.owner,
  repo:         context.repo.repo,
  issue_number: issueNumber,
  labels:       [labelName],
});
console.log(`Applied label "${labelName}" to issue #${issueNumber}.`);

// ── 3. Post a bounty announcement comment ──────────────────────
const body = [
  `🏷️ This issue now carries an **ETH bounty** of **${amount} ETH**!`,
  '',
  `| | |`,
  `|---|---|`,
  `| 💰 Bounty | **${amount} ETH** |`,
  `| 🏷️ Label | \`${labelName}\` |`,
  `| 📌 Issue | #${issueNumber} |`,
  `| 🌐 Network | Optimism Mainnet |`,
  '',
  '**How to claim:**',
  '1. Comment on this issue expressing your interest.',

  '2. Get assigned by a maintainer (`@TheJollyLaMa`).',
  '3. Open a Pull Request that closes this issue (include `Closes #' + issueNumber + '` in the PR body).',
  '4. Once your PR is merged, the maintainer will queue your ETH payout.',
  '',
  '> ⚠️ **Whitelist registration required:** Payouts are only sent to wallets registered in the',
  '> contributor whitelist by `@TheJollyLaMa`. If you are not yet registered, reach out to',
  '> `@TheJollyLaMa` directly (via video call or DM) to complete onboarding before your payout',
  '> can be processed.',
  `> See [CONTRIBUTING.md](https://github.com/${context.repo.owner}/${context.repo.repo}/blob/main/CONTRIBUTING.md) for onboarding instructions.`,
].join('\n');

await github.rest.issues.createComment({
  owner:        context.repo.owner,
  repo:         context.repo.repo,
  issue_number: issueNumber,
  body,
});
console.log(`Bounty announcement posted on issue #${issueNumber}.`);

const originatorLogin = '${{ github.event.inputs.idea_credit_username }}';
const isMajor         = '${{ github.event.inputs.major_feature }}' === 'true';
const approver        = context.actor;

// ── 1. Ensure "idea-adopted" label exists ────────────────────────
const adoptedLabel = 'idea-adopted';
try {
  await github.rest.issues.getLabel({
    owner: context.repo.owner,
    repo:  context.repo.repo,
    name:  adoptedLabel,
  });
  console.log(`Label "${adoptedLabel}" already exists.`);
} catch (e) {
  if (e.status === 404) {
    await github.rest.issues.createLabel({
      owner:       context.repo.owner,
      repo:        context.repo.repo,
      name:        adoptedLabel,
      color:       '7c3aed',
      description: 'Community idea adopted for implementation',
    });
    console.log(`Created label "${adoptedLabel}".`);
  } else {
    throw e;
  }
}

// ── 2. Ensure "idea-credit: @<username>" label exists ────────────
const creditLabel = `idea-credit: @${originatorLogin}`;
try {
  await github.rest.issues.getLabel({
    owner: context.repo.owner,
    repo:  context.repo.repo,
    name:  creditLabel,
  });
  console.log(`Label "${creditLabel}" already exists.`);
} catch (e) {
  if (e.status === 404) {

    await github.rest.issues.createLabel({
      owner:       context.repo.owner,
      repo:        context.repo.repo,
      name:        creditLabel,
      color:       '0891b2',
      description: `Idea credit for @${originatorLogin}`,
    });
    console.log(`Created label "${creditLabel}".`);
  } else {
    throw e;
  }
}

// ── 3. Apply both labels to the issue ────────────────────────────
await github.rest.issues.addLabels({
  owner:        context.repo.owner,
  repo:         context.repo.repo,
  issue_number: issueNumber,
  labels:       [adoptedLabel, creditLabel],
});
console.log(`Applied labels "${adoptedLabel}" and "${creditLabel}" to issue #${issueNumber}.`);

// ── 4. Post adoption announcement comment ────────────────────────
const dnftLine = isMajor
  ? `| 🎖️ DNFT Eligible | **Yes** — Feature Originator DNFT will be minted on merge |`
  : null;

const body = [
  `✅ **Idea Adopted!** This community idea has been marked for implementation by @${approver}.`,
  '',
  `| | |`,
  `|---|---|`,
  `| 💡 Idea Originator | @${originatorLogin} |`,
  `| 🏷️ Status | \`idea-adopted\` |`,
  `| 💰 Credit Split | **20% ETH** to idea originator · **80% ETH** to implementer |`,
  dnftLine,
  '',
  `**What happens next:**`,

  `1. A contributor will be assigned to implement this idea.`,
  `2. When their PR is merged, the payout is **automatically split**: 20% goes to @${originatorLogin} (you!) and 80% goes to the implementer.`,
  isMajor ? `3. As a major feature, a **Feature Originator DNFT** will be minted and sent to your wallet via the admin Payroll panel after merge.` : null,
  '',
  `> 💡 @${originatorLogin} — if you are not yet registered in the contributor whitelist, contact \`@TheJollyLaMa\` to complete onboarding and register your Optimism Mainnet wallet address so your ETH payout can be processed.`,
].filter(l => l !== null).join('\n');

await github.rest.issues.createComment({
  owner:        context.repo.owner,
  repo:         context.repo.repo,
  issue_number: issueNumber,
  body,
});
console.log(`Idea adoption comment posted on issue #${issueNumber} — crediting @${originatorLogin}${isMajor ? ' (major feature — DNFT eligible)' : ''}.`);

