  #mobile-discord-link {
    position: fixed;
    bottom: 8px;
    left: 50%;
    z-index: 55;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.4rem;
    min-height: 36px;
    padding: 0.35rem 0.85rem;
    color: var(--text-primary);
    background: rgba(5, 3, 18, .92);
    border: 1px solid var(--panel-border);
    border-radius: 22px;
    box-shadow: 0 3px 12px rgba(0,0,0,.35);
