  #center-stage,
  #timeline-nav {
    left: 50%;
    transform: translateX(-50%);
  }
}

/* ── Main Stage ──────────────────────────────────────────────────────────── */
#stage {
  position: relative;
  z-index: 10;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  flex: 1;
  padding: 2rem 1rem 3rem;
  min-height: calc(100vh - 120px);
}

/* Now-playing banner */
#busker-info {
  position: fixed;
  top: auto;
  bottom: 225px;
  left: calc(50% - 115px);
  transform: translateX(-50%);
  z-index: 20;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.25rem;
  text-align: center;
  pointer-events: none;
}

#now-playing-label {
  font-size: 0.75rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--gold-dim);
}

#now-playing-title {
  font-family: var(--font-display);
  font-size: 1.4rem;
  color: var(--gold);
  text-shadow: 0 0 18px rgba(240, 192, 64, 0.6);
  min-height: 1.6rem;
}

#now-playing-artist {
  font-size: 0.875rem;
  color: var(--text-dim);
}

/* Now Playing — play button (shown when autoplay is blocked) */
#now-playing-play-btn {
  pointer-events: auto;
  background: linear-gradient(135deg, var(--teal), var(--purple));
  color: #fff;
  border: none;
  border-radius: 20px;
  padding: 0.35rem 1rem;
  font-size: 0.8rem;
  font-family: var(--font-display);
  cursor: pointer;
  margin-top: 0.25rem;
  transition: opacity var(--transition), transform var(--transition);
  animation: pulse-glow 1.8s ease-in-out infinite;
}

#now-playing-play-btn:hover {
  opacity: 0.88;
  transform: scale(1.05);
}

.now-playing-actions {
  display: flex;
  gap: 0.5rem;
  justify-content: center;
}

#now-playing-radio-btn {
  pointer-events: auto;
  background: rgba(5, 3, 18, 0.75);
  color: var(--gold);
  border: 1px solid var(--gold-dim);
  border-radius: 20px;
  padding: 0.35rem 1rem;
  font-size: 0.8rem;
  font-family: var(--font-display);
  cursor: pointer;
  margin-top: 0.25rem;
  transition: background var(--transition), transform var(--transition);
}

#now-playing-radio-btn:hover {
  background: rgba(240, 192, 64, 0.15);
  transform: scale(1.05);
}

#radio-activity {
  max-width: min(88vw, 420px);
  font-size: 0.75rem;
  line-height: 1.35;
  color: var(--teal);
  min-height: 1rem;
}

#radio-activity.radio-activity-flash {
  animation: radio-activity-in 0.6s ease-out;
}

@keyframes radio-activity-in {
  from { opacity: 0; transform: translateY(4px); }
  to   { opacity: 1; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  #radio-activity.radio-activity-flash { animation: none; }
}

@keyframes pulse-glow {
  0%, 100% { box-shadow: 0 0 8px rgba(0, 212, 170, 0.4); }
  50%       { box-shadow: 0 0 20px rgba(0, 212, 170, 0.85); }
}

/* Center stage — hat & guitar case */
#center-stage {
  position: fixed;
  top: auto;

  bottom: 138px;
  left: calc(50% - 115px);
  transform: translateX(-50%);
  z-index: 20;
  display: flex;
  gap: 4rem;
  align-items: flex-end;
  justify-content: center;
  perspective: 600px;
}

/* Hat & Guitar Case buttons */
#hat-btn,
#guitar-case-btn {
  background: none;
  border: none;
  cursor: pointer;
  font-size: 5rem;
  line-height: 1;
  filter: drop-shadow(0 0 14px rgba(240, 192, 64, 0.4));
  transition: transform var(--transition), filter var(--transition);
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

#hat-btn:hover,
#guitar-case-btn:hover {
  transform: scale(1.12) translateY(-4px);
  filter: drop-shadow(0 0 26px rgba(240, 192, 64, 0.75));
}

#hat-btn:active,
#guitar-case-btn:active {
  transform: scale(0.96) translateY(0);
}

/* ── Audio Player ────────────────────────────────────────────────────────── */
#audio-player {
  display: none;
}

/* ── NFT Detail Panel ────────────────────────────────────────────────────── */
#nft-panel {
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  z-index: 200;
  background: var(--panel-bg);
  border: 1px solid var(--panel-border);
  border-radius: var(--stage-radius);
  padding: 2rem;
  min-width: 320px;
