#nft-panel-content {
  margin-bottom: 1.25rem;
}

#nft-panel-content h3 {
  font-family: var(--font-display);
  color: var(--gold);
  margin-bottom: 0.75rem;
  font-size: 1.2rem;
}

#nft-panel-content .nft-meta {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 0.4rem 1rem;
  font-size: 0.875rem;
  margin-bottom: 1rem;
}

#nft-panel-content .nft-meta dt {
  color: var(--text-dim);
}

#nft-panel-content .nft-meta dd {
  color: var(--text-primary);
