}

#nft-panel-content audio {
  width: 100%;
  margin-bottom: 0.75rem;
  accent-color: var(--teal);
}

.nft-buy-btn {
  display: block;
  width: 100%;
  padding: 0.75rem;
  background: linear-gradient(135deg, var(--teal), var(--purple));
  color: #fff;
  font-family: var(--font-display);
  font-size: 1rem;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: opacity var(--transition), transform var(--transition);
}

.nft-buy-btn:hover {
  opacity: 0.88;
  transform: translateY(-1px);
}

.nft-buy-btn:disabled {
  opacity: 0.55;
  cursor: wait;
  transform: none;
}

.nft-play-row {
  display: flex;
  gap: 0.5rem;
}

.nft-play-row .nft-mute-btn {
  width: auto;
  min-width: 3rem;
  flex: 0 0 auto;
}

.nft-listen-status {
  min-height: 1.1em;
  margin: 0.4rem 0;
  font-size: 0.8rem;
  color: var(--text-dim);
}

.nft-card-actions {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
  margin-top: 0.45rem;
}

.nft-card-actions .nft-buy-btn {
  width: auto;
  min-width: 7rem;
}

.nft-watchlist-btn {
  padding-inline: 0.75rem;
}

.nft-share-status {
  min-height: 1.1em;
  margin: 0.4rem 0 0.75rem;
  font-size: 0.8rem;
  color: var(--text-dim);
}

.nft-share-link {
  width: 100%;
  margin-top: 0.35rem;
  padding: 0.45rem 0.5rem;
  border: 1px solid var(--panel-border);
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.04);
  color: var(--text-primary);

  font: inherit;
}

.nft-watchlist-status {
  min-height: 1.1em;
  margin: 0.4rem 0 0;
  font-size: 0.75rem;
  color: var(--text-dim);
}
/* ── NFT Parent / Remix section ──────────────────────────────────────────── */
.nft-parent-section {
  margin-bottom: 0.75rem;
}

.nft-parent-card {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  background: rgba(124, 58, 237, 0.1);
  border: 1px solid rgba(124, 58, 237, 0.3);
  border-radius: 8px;
  padding: 0.65rem 0.85rem;
  font-size: 0.82rem;
}

.nft-parent-card.nft-parent-loading {
  color: var(--text-dim);
  font-style: italic;
}

.nft-parent-badge {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--purple);
  font-weight: bold;
}

.nft-parent-artist {
  color: var(--text-dim);
  font-size: 0.78rem;
}

.nft-royalty-badge {
  display: inline-block;
  background: rgba(240, 192, 64, 0.15);
  border: 1px solid rgba(240, 192, 64, 0.3);
  border-radius: 12px;
  padding: 0.15rem 0.6rem;
  font-size: 0.72rem;
  color: var(--gold);
  margin-top: 0.15rem;
  width: fit-content;
}

.nft-parent-audio {

  width: 100%;
  margin-top: 0.4rem;
  accent-color: var(--purple);
}

#nft-panel-close {
  position: absolute;
  top: 0.75rem;
  right: 0.75rem;
  background: none;
  border: none;
  color: var(--text-dim);
  font-size: 1.1rem;
  cursor: pointer;
  transition: color var(--transition);
}

#nft-panel-close:hover {
  color: var(--text-primary);
}

/* ── Mint Modal ──────────────────────────────────────────────────────────── */

/* ── DNFT Archive Drawer ─────────────────────────────────────────────────── */
#dnft-archive-toggle {
  position: fixed;
  top: 120px;
  right: 14px;
  z-index: 90;
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  min-height: 38px;
  padding: 0.45rem 0.8rem;
  color: var(--gold);
  background: rgba(5, 3, 18, 0.92);
  border: 1px solid var(--panel-border);
  border-radius: 22px;
  box-shadow: 0 4px 16px rgba(0,0,0,.32);
