  cursor: pointer;
}

#dnft-archive-toggle:hover { background: rgba(20, 14, 32, .98); }
#dnft-archive-toggle > span:first-child { color: var(--teal); font-size: 1.1rem; }
#dnft-list-count-badge {
  min-width: 1.25rem;
