#top-ten-tab:focus-visible, #top-ten-panel button:focus-visible { outline: 2px solid var(--teal); outline-offset: 2px; }
body.top-ten-open #top-ten-tab, body.top-ten-open #djuke-tab, body.top-ten-open #devert-tab { left: var(--top-ten-drawer-width); }
body.djuke-open #top-ten-tab, body.djuke-open #devert-tab { left: var(--djuke-width); }
body.devert-open #top-ten-tab, body.devert-open #djuke-tab, body.devert-open #devert-tab { left: var(--devert-width); }
#top-ten-panel {
  position: fixed;
  top: var(--left-tab-top);
  bottom: max(120px, calc(var(--radio-footer-height, 96px) + 20px));
