}
#top-ten-panel.is-open { transform: translateX(0); visibility: visible; pointer-events: auto; }
#top-ten-panel.is-open { animation: top-ten-charge 14s ease-in-out infinite; }
#top-ten-panel::before { content: ''; position: absolute; inset: 0; z-index: 0; pointer-events: none; background: linear-gradient(0deg, transparent 20%, rgba(111, 235, 190, .03) 38%, rgba(231, 223, 152, .13) 49%, rgba(196, 235, 246, .06) 58%, transparent 76%); transform: translateY(100%); animation: top-ten-charge-rise 12s linear infinite; animation-play-state: paused; }
#top-ten-panel.is-open::before { animation-play-state: running; }
#top-ten-panel > :not(.top-ten-flight-layer) { position: relative; z-index: 1; }
.top-ten-flight-layer { position: absolute; inset: 0; z-index: 2; pointer-events: none; overflow: hidden; }
.top-ten-visitor { position: absolute; top: 0; left: 0; visibility: hidden; pointer-events: none; font-size: 16px; line-height: 1; opacity: .7; filter: drop-shadow(0 0 5px #ddd99a55); }
.top-ten-visitor-0 { font-size: 18px; opacity: .75; }
.radio-schedule-row.is-cancelled { position: relative; padding-right: 110px; opacity: .85; }
.radio-schedule-cancelled-stamp { position: absolute; right: 12px; top: 12px; padding: 4px 8px; border: 3px double #ef6262; border-radius: 4px; color: #ff7979; font-weight: 900; text-transform: uppercase; letter-spacing: .08em; transform: rotate(-12deg); box-shadow: inset 0 0 0 1px #ef626255; }
.radio-schedule-cancel-reason { color: #f3aaaa; font-size: .8rem; }

.top-ten-chart-hole { display: none; position: absolute; transform: translate(-50%, -50%); font-size: 30px; line-height: 1; filter: drop-shadow(0 0 7px #91e2ce66); }
.is-hype-festival .top-ten-chart-hole { display: block; }
.top-ten-spy-peek { position: absolute; bottom: 12px; left: 50%; width: 30px; height: 32px; overflow: hidden; transform: translateX(-50%); }
.top-ten-spy { display: block; font-size: 27px; transform: translateY(110%); animation: top-ten-spy-peek 23s ease-in-out infinite; }
.hype-rabbit-hole .top-ten-spy { animation-duration: 29s; animation-delay: -9s; }
@keyframes top-ten-spy-peek {
  0%, 72%, 94%, 100% { transform: translateY(110%); }
  78%, 82% { transform: translateY(5%) rotate(-10deg); }
