}
@media (prefers-reduced-motion: reduce) {
  .top-ten-spy-peek { display: none; }
}
body:not(.top-ten-open) .top-ten-spy { animation-play-state: paused; }
.is-hype-festival #top-ten-content { padding-bottom: 34px; box-sizing: border-box; }
@keyframes top-ten-charge { 0%, 100% { background-color: rgba(8, 10, 16, .96); } 50% { background-color: rgba(8, 18, 19, .81); } }
@keyframes top-ten-charge-rise { from { transform: translateY(100%); } to { transform: translateY(-100%); } }
@media (prefers-reduced-motion: reduce) {
  #top-ten-panel.is-open, #top-ten-panel::before { animation: none; }
  #top-ten-panel::before, .top-ten-flight-layer { display: none; }
}
.hype-festival { position: relative; flex-shrink: 0; padding: 16px 12px 10px; overflow: hidden; border: 1px solid #d9af6359; border-radius: 12px; background: radial-gradient(ellipse at 50% 55%, #66326880, transparent 70%), linear-gradient(155deg, #251c38, #102c32 70%, #191b30); text-align: center; }

