.hype-info-button { position: absolute; top: 9px; left: 9px; z-index: 2; width: 22px; height: 22px; padding: 0; border: 1px solid #ffe1a299; border-radius: 50%; background: #2b2140; color: #ffe1a2; font: italic 700 .8rem/1 Georgia, serif; cursor: pointer; }
.hype-info-button:hover, .hype-info-button[aria-expanded="true"] { background: #4b3567; }
.hype-info-popover { position: absolute; top: 37px; left: 9px; z-index: 3; max-width: min(330px, calc(100% - 18px)); margin: 0; padding: 10px 12px; border: 1px solid #ffe1a266; border-radius: 9px; background: #1b1628f5; box-shadow: 0 8px 22px #0009; color: #f0e4f2; font-size: .7rem; line-height: 1.5; text-align: left; }
.hype-info-popover[hidden] { display: none; }
.hype-subtitle { margin: 0; color: #e6cde7; font-size: .65rem; }
.hype-stage { position: relative; height: 156px; margin: 6px -4px 0; overflow: hidden; background: conic-gradient(from 170deg at 50% 0%, transparent, #eabfff0a 12deg, transparent 24deg, #9fffe811 36deg, transparent 48deg, #eabfff0a 60deg, transparent 72deg); }
.hype-stage > span { position: absolute; display: block; filter: drop-shadow(0 3px 7px #0006); }

.hype-band { position: absolute; left: 14%; right: 8%; top: 40px; height: 70px; display: flex; justify-content: space-around; align-items: center; border-bottom: 2px solid #dbab7444; border-radius: 50%; background: radial-gradient(ellipse at bottom, #c57bd133, transparent 70%); }
.hype-bandmate { position: relative; display: inline-block; font-size: 38px; animation: hype-rock 950ms ease-in-out infinite alternate; animation-delay: calc(var(--member) * -290ms); transform-origin: bottom center; }
.hype-instrument { position: absolute; right: -13px; bottom: -7px; font-size: 28px; }
.hype-planet { left: 3%; top: 8px; font-size: 36px; animation: hype-orbit 6s ease-in-out infinite alternate; }
.hype-celestial { top: 5px; font-size: 26px; color: #f1c8ff; text-shadow: 0 0 15px #f2b7ff88; animation: hype-orbit 4s ease-in-out infinite alternate; }
.hype-celestial-lilith { left: 27%; }
.hype-celestial-venus { left: 50%; animation-delay: -2s; }
.hype-celestial-mercury { left: 72%; animation-delay: -1s; }
.hype-trophy { right: 1%; top: 7px; font-size: 28px; animation: hype-rock 2s ease-in-out infinite alternate; }
.hype-stage .hype-rabbit-hole { left: 3%; bottom: 42px; font-size: 30px; opacity: .8; }
.hype-stage .hype-runaway { left: 3%; bottom: 48px; z-index: 1; width: 38px; height: 44px; overflow: hidden; animation: hype-bunny-run 14s linear infinite; }
