}
#payroll-open-btn:hover {
  background: rgba(0, 212, 170, 0.25);
  box-shadow: 0 0 12px rgba(0, 212, 170, 0.4);
}

/* Overlay backdrop */
#payroll-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.72);

  z-index: 1100;
  backdrop-filter: blur(4px);
}

/* Modal container */
#payroll-modal {
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  z-index: 1200;
  width: min(92vw, 760px);
  max-height: 90vh;
  overflow-y: auto;
