}

#payroll-modal-inner {
  background: var(--panel-bg);
  border: 1px solid var(--teal);
  border-radius: var(--stage-radius);
  box-shadow: 0 0 40px rgba(0, 212, 170, 0.25), 0 0 80px rgba(124, 58, 237, 0.15);
  padding: 1.8rem 2rem;
  display: flex;
  flex-direction: column;
  gap: 1.2rem;
}

/* Header row */
#payroll-modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid rgba(0, 212, 170, 0.2);
  padding-bottom: 0.8rem;
}
#payroll-modal-header h2 {
  font-family: var(--font-display);
  color: var(--teal);
  font-size: 1.4rem;
  letter-spacing: 0.03em;
}
#payroll-close-btn {
  background: none;
  border: none;
  color: var(--text-dim);
  font-size: 1.4rem;
  cursor: pointer;
  transition: var(--transition);
}
#payroll-close-btn:hover { color: var(--text-primary); }

/* Description */
.payroll-description {

  color: var(--text-dim);
  font-size: 0.9rem;
  line-height: 1.5;
}

/* Connect section */
#payroll-connect-row {
  display: flex;
  align-items: center;
  gap: 1rem;
  flex-wrap: wrap;
}
.payroll-addr {
  font-family: 'Courier New', monospace;
  font-size: 0.8rem;
  color: var(--text-dim);
  background: rgba(255,255,255,0.04);
  padding: 0.25rem 0.6rem;
  border-radius: 6px;
}

/* Owner warning */
.payroll-warning {
  background: rgba(255, 107, 107, 0.12);
  border: 1px solid rgba(255, 107, 107, 0.4);
  border-radius: 8px;
  padding: 0.6rem 1rem;
  color: #ff9999;
  font-size: 0.88rem;
}

/* Status text */
.payroll-status {
  font-size: 0.88rem;
  min-height: 1.2em;
  color: var(--teal);
}
.payroll-status a { color: var(--teal); }

/* Queue header */
#payroll-queue-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
#payroll-queue-header h3 {
  font-family: var(--font-display);
  color: var(--gold);
  font-size: 1rem;
  letter-spacing: 0.02em;
}

/* Empty message */
.payroll-empty {
  color: var(--teal);
  text-align: center;

  padding: 1rem;
  font-size: 0.95rem;
}

/* Table */
.payroll-table-wrap {
  min-width: 0;
  max-width: 100%;
  overflow-x: auto;
  border-radius: 8px;
  border: 1px solid var(--panel-border);
}

.payroll-section { padding: 16px 0; border-top: 1px solid var(--panel-border); }
.payroll-section h3 { margin: 0 0 10px; font-size: 1rem; }
.payroll-allocation { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 8px 16px; margin: 0; font-size: .85rem; }
.payroll-allocation dt { color: var(--text-dim); }
.payroll-allocation dd { margin: 0; }
.radio-payroll-controls { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 12px; margin: 12px 0; }
.radio-payroll-controls label { display: grid; gap: 6px; font-size: .8rem; color: var(--text-dim); }
.payroll-fund-guide { margin: 10px 0; padding: 10px 12px; color: var(--text-dim); background: rgba(0,212,170,.06); border-left: 2px solid var(--teal); font-size: .78rem; line-height: 1.5; }
.payroll-field-hint { color: var(--text-dim); font-size: .7rem; line-height: 1.4; }
.radio-payroll-controls input, .radio-payroll-controls select, .radio-payroll-controls textarea { min-width: 0; width: 100%; min-height: 38px; padding: 8px; font: inherit; color: var(--text-primary); background: #10121a; border: 1px solid var(--panel-border); border-radius: 4px; }
.radio-payroll-controls textarea { resize: vertical; }
.radio-payroll-actions { display: flex; flex-wrap: wrap; gap: 8px; }
.payroll-funding-band { padding: 12px 0; border-bottom: 1px solid var(--panel-border); }
