.payroll-funding-band p { margin: 6px 0 0; font-size: .8rem; line-height: 1.45; overflow-wrap: anywhere; }
.payroll-funding-warning { color: var(--gold); }
.radio-payroll-controls input[readonly] { opacity: .85; }
.settlement-router-section summary { cursor: pointer; font-weight: 700; margin-bottom: 16px; }
.settlement-router-section .payroll-allocation dd { min-width: 0; overflow-wrap: anywhere; max-width: 100%; }
.settlement-router-section .payroll-allocation { grid-template-columns: auto minmax(0, 1fr); }
.router-metadata-label { grid-column: 1 / -1; }
#router-custom-fund-label[hidden] { display: none; }
#router-custom-fund-form[hidden] { display: none; }
#router-save-metadata { display: inline-flex; align-items: center; gap: 8px; }
