.radio-payroll-artist { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 8px; padding: 10px 0; border-bottom: 1px solid var(--panel-border); font-size: .8rem; overflow-wrap: anywhere; }
@media (max-width: 600px) { .radio-payroll-artist { grid-template-columns: minmax(0, 1fr); } }
.payroll-secondary-flow { margin: 12px 0; border-block: 1px solid var(--panel-border); }
.payroll-secondary-flow > summary { padding: 10px 0; cursor: pointer; font-weight: 600; }
.payroll-work-reference { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 6px 10px; align-items: center; padding: 8px 0 12px; }

.payroll-work-reference > span { color: var(--text-dim); font-size: .75rem; }
.payroll-work-reference > input { grid-column: 1; width: 100%; min-width: 0; font-size: .72rem; font-family: monospace; }
.payroll-copy-reference { grid-column: 2; grid-row: 1 / span 2; }
.payroll-legacy-warning { color: var(--gold); font-size: .85rem; }
.payroll-legacy-review { display: grid; min-width: 220px; gap: 8px; margin-top: 8px; }
.payroll-legacy-review input[type="text"], .payroll-tx-hash { min-width: 0; width: 100%; padding: 8px; border: 1px solid var(--panel-border); border-radius: 4px; background: #10121a; color: var(--text-primary); font: inherit; }
.payroll-legacy-review label { font-size: .75rem; white-space: normal; }
.payroll-verify-btn { padding: 6px 8px; border: 1px solid var(--panel-border); border-radius: 4px; color: var(--text-primary); background: #10121a; cursor: pointer; }
#payroll-connect-section, #payroll-queue-section { min-width: 0; max-width: 100%; }
#payroll-modal .payroll-addr { max-width: 100%; white-space: normal; overflow-wrap: anywhere; }
#payroll-settle-hint { min-width: 0; overflow-wrap: anywhere; }
#payroll-settle-hint code { word-break: break-all; }
@media (max-width: 600px) {
  #payroll-table thead { display: none; }
  #payroll-table, #payroll-table tbody { display: block; width: 100%; }
  #payroll-table .payroll-row { display: grid; grid-template-columns: minmax(0, 1fr) auto; border-bottom: 1px solid var(--panel-border); }
  #payroll-table .payroll-td { display: block; min-width: 0; border: 0; }
  #payroll-table .payroll-td:nth-child(2), #payroll-table .payroll-td:nth-child(4), #payroll-table .payroll-td:nth-child(5) { grid-column: 1 / -1; }
  #payroll-table .payroll-td:nth-child(3) { grid-column: 2; grid-row: 1; }

  #payroll-table .payroll-legacy-review { min-width: 0; }
}
.payroll-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.87rem;
}
.payroll-table thead th {
  background: rgba(0, 212, 170, 0.08);
  color: var(--teal);
  padding: 0.55rem 0.8rem;
  text-align: left;
  font-weight: 600;
  white-space: nowrap;
}
.payroll-table tbody tr {
