}
.payroll-amount { font-family: 'Courier New', monospace; color: var(--gold); }
.payroll-no-wallet { color: #ff9999; font-size: 0.82rem; }

/* Pay buttons */
.payroll-pay-btn {
  background: rgba(0, 212, 170, 0.12);
  border: 1px solid var(--teal);
  color: var(--teal);
