/* Settle All row */
#payroll-settle-all-row {
  display: flex;
  justify-content: flex-end;
  padding-top: 0.5rem;
}

/* Hint block */
.payroll-hint {
  background: rgba(0, 212, 170, 0.07);
  border: 1px solid rgba(0, 212, 170, 0.2);
  border-radius: 8px;
  padding: 0.6rem 1rem;
  font-size: 0.85rem;
