/* Artwork editor dialog */
#nft-artwork-editor.artwork-editor { width: min(460px, calc(100vw - 32px)); max-height: calc(100dvh - 32px); overflow: auto; box-sizing: border-box; padding: 20px; color: var(--text); background: radial-gradient(circle at 50% 0%, rgba(233, 215, 160, .1), transparent 60%), var(--bg, #111); border: 1px solid rgba(233, 215, 160, .55); border-radius: 22px; box-shadow: 0 24px 70px rgba(0, 0, 0, .65); }

