#nft-artwork-editor::backdrop { background: rgba(0, 0, 0, .65); backdrop-filter: blur(3px); }
@keyframes artwork-editor-in { from { opacity: 0; transform: translateY(16px) scale(.96); } to { opacity: 1; transform: none; } }
