.artwork-editor-close:hover, .artwork-editor-close:focus-visible { background: rgba(233, 215, 160, .2); border-color: #e9d7a0; transform: rotate(90deg); outline: none; }
.artwork-editor-close svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2.4; stroke-linecap: round; }
