.artwork-editor-frame { position: relative; display: grid; place-items: center; margin: 0; aspect-ratio: 1; border: 2px solid rgba(233, 215, 160, .3); border-radius: 18px; background: #0d1210; overflow: hidden; transition: border-color .25s ease, box-shadow .25s ease; }
