.artwork-editor-frame figcaption { position: absolute; left: 8px; bottom: 8px; padding: 2px 9px; border-radius: 999px; background: rgba(0, 0, 0, .65); color: #e9d7a0; font-size: .66rem; font-weight: 700; letter-spacing: .04em; text-transform: uppercase; }
