  return ordered().filter(entry => entry.status === 'pending' &&
    !isExpired(entry) &&
    entry.approvals.length === entry.owners.length &&
    entry.owners.every(owner => entry.approvals.some(approval =>
      approval.address.toLowerCase() === owner.toLowerCase()))).map(copy);
},
