import { Client, Events, GatewayIntentBits, MessageFlags } from 'discord.js';
import { AudioPlayerStatus, createAudioPlayer, createAudioResource, entersState,
  joinVoiceChannel, NoSubscriberBehavior, StreamType, VoiceConnectionStatus } from '@discordjs/voice';
import { buildSiteVotingLink, resolveStreamableIpfsUrl } from './jukeloop.js';
import { createVoiceConnectionSupervisor } from './voice-connection.js';
import { DISCORD_REST_OPTIONS, loginDiscordClient, watchDiscordSession } from './discord-login.js';
import { DEVERT_MAX_AD_SECONDS } from '../js/devert-scheduler.mjs';

const MIN_AUDIBLE_MS = 30_000;
const RETRY_MS = 30_000;
const BETWEEN_ADS_MS = 1_500;
const FFMPEG_BIN = process.env.FFMPEG_PATH || 'ffmpeg';

function createStream(url) {
  const child = spawn(FFMPEG_BIN, ['-reconnect', '1', '-reconnect_streamed', '1', '-reconnect_delay_max', '5',
    '-i', url, '-t', String(DEVERT_MAX_AD_SECONDS), '-analyzeduration', '0', '-loglevel', '0', '-vn',
    '-af', 'afade=t=in:st=0:d=0.6:curve=qsin', '-f', 's16le', '-ar', '48000', '-ac', '2', 'pipe:1'],
  { stdio: ['ignore', 'pipe', 'ignore'] });
  child.on('error', error => console.error('[devert-loop] FFmpeg:', error.message));
  return child;
}

export function createDevertLoopController({ player, playback, voiceChannel, textChannel,
  resolveAdUrl = cid => resolveStreamableIpfsUrl(process.env.IPFS_GATEWAY || 'https://dweb.link', cid),
  createStream: streamFactory = createStream, createResource = createAudioResource,
  now = () => Date.now(), setTimer = setTimeout, clearTimer = clearTimeout,
  minimumAudibleMs = MIN_AUDIBLE_MS, retryMs = RETRY_MS, betweenAdsMs = BETWEEN_ADS_MS,
  recordImpressions = true, log = console }) {
  let current = null;
  let child = null;

let stopped = false;
let retryTimer = null;
let errorIdlePending = false;
let announcement = null;
const failedCampaigns = new Map();

const stopChild = () => {
  if (child) { try { child.kill(); } catch {} child = null; }
};
const scheduleNext = delay => {
  clearTimer(retryTimer);
  if (!stopped) {
    retryTimer = setTimer(() => runNext().catch(error => log.error('[devert-loop]', error.message)), delay);
    retryTimer?.unref?.();
  }
};

player.on('stateChange', (oldState, newState) => {
  if (newState.status === AudioPlayerStatus.Playing && oldState.status === AudioPlayerStatus.Buffering && current) {
    current.startedAt = now();
    current.audible = true;
  }
});
player.on(AudioPlayerStatus.Idle, async () => {
  if (errorIdlePending) { errorIdlePending = false; return; }
  stopChild();
  const completed = current;
  current = null;
  if (completed?.audible && recordImpressions) {
    const audibleMs = now() - completed.startedAt;
    if (audibleMs >= minimumAudibleMs) {
      try {
        await playback.recordCampaignImpression({ campaignId: completed.campaignId,
          radioPlayId: completed.radioPlayId, mainRadio: false, audibleMs });
      } catch (error) {
        failedCampaigns.set(completed.campaignId, now() + 5 * 60_000);
        log.warn('[devert-loop] Durable impression pending:', error.message);
      }
    } else failedCampaigns.set(completed.campaignId, now() + 5 * 60_000);
  }
  scheduleNext(betweenAdsMs);
});
player.on('error', error => {
  if (current) failedCampaigns.set(current.campaignId, now() + 5 * 60_000);
  errorIdlePending = true;
  stopChild();
  current = null;
  log.warn('[devert-loop] Audio playback failed:', error.message);

  scheduleNext(retryMs);
});

async function runNext() {
  if (stopped || current) return;
  errorIdlePending = false;
  const timestamp = now();
  for (const [campaignId, retryAt] of failedCampaigns) if (retryAt <= timestamp) failedCampaigns.delete(campaignId);
  let ad;
  try { ad = await playback.nextDevertLoopAd({ excludeCampaignIds: [...failedCampaigns.keys()] }); }
  catch (error) { log.warn('[devert-loop] Campaign read failed:', error.message); scheduleNext(retryMs); return; }
  if (stopped) return;
  if (!ad) { scheduleNext(retryMs); return; }
  const url = await resolveAdUrl(ad.track.ipfsCid);
  if (stopped) return;
  if (!url) {
    failedCampaigns.set(ad.campaignId, timestamp + 5 * 60_000);
    log.warn(`[devert-loop] No gateway can stream campaign ${ad.campaignId}`);
    scheduleNext(1_000);
    return;
  }
  if (playback.isCampaignRemoved?.(ad.campaignId)) { scheduleNext(1_000); return; }
  if (playback.canPlayCampaign) {
    try {
      if (!await playback.canPlayCampaign(ad.campaignId)) { scheduleNext(1_000); return; }
    } catch (error) {
      log.warn('[devert-loop] Campaign availability check failed:', error.message);
      scheduleNext(retryMs);
      return;
    }
  }
  if (stopped) return;
  const radioPlayId = `devert-loop:${ad.campaignId}:${timestamp}`;
  announcement = null;
  child = streamFactory(url);
  const mediaType = ad.track.mediaType || (ad.track.videoUrl ? 'video/mp4' : '');
  current = { campaignId: ad.campaignId, radioPlayId, title: ad.track.title,
    ipfsCid: ad.track.ipfsCid, mediaType,
    videoUrl: ad.track.videoUrl || (mediaType === 'video/mp4' ? `ipfs://${ad.track.ipfsCid}` : ''),
    startedAt: timestamp, audible: false };

    try { player.play(createResource(child.stdout, { inputType: StreamType.Raw })); }
    catch (error) {
      failedCampaigns.set(ad.campaignId, timestamp + 5 * 60_000);
      stopChild();
      current = null;
      log.warn('[devert-loop] Audio playback failed:', error.message);
      scheduleNext(retryMs);
      return;
    }
    announcement = await textChannel?.send({ content: `📢 **AdLoop:** ${ad.track.title}\n${buildSiteVotingLink()}`, flags: MessageFlags.SuppressNotifications,
      allowedMentions: { parse: [] } }).catch(() => null);
    log.log(`[devert-loop] Playing campaign ${ad.campaignId} in ${voiceChannel.name}.`);
  }

  return {
    start: runNext,
    removeCampaign(campaignId) {
      if (String(current?.campaignId) !== String(campaignId)) return;
      current = null;
      stopChild();
      player.stop(true);
      scheduleNext(betweenAdsMs);
    },
    async submitVote({ playId, voterId, vote, messageId }) {
      if (!current?.audible || playId && playId !== current.radioPlayId ||
          messageId && messageId !== announcement?.id) throw new Error('Vote only on the current audible VertLoop ad');
      return playback.recordMainRadioAdVote({ campaignId: current.campaignId,
        radioPlayId: current.radioPlayId, voterId, vote });
    },
    stop() { stopped = true; clearTimer(retryTimer); stopChild(); current = null; player.stop?.(true); },
    getState() {
      return { ready: !stopped, nowPlaying: current ? { ...current, positionMs: current.audible ? Math.max(0, now() - current.startedAt) : 0 } : null };
    },
  };
}

export async function startDevertWebsiteLoopWorker({ playback, log = console }) {
  const player = createAudioPlayer({ behaviors: { noSubscriber: NoSubscriberBehavior.Play } });

  const controller = createDevertLoopController({
    player, playback, voiceChannel: { name: 'website only (Discord paused)' },
    recordImpressions: false, log,
  });
  await controller.start();
  log.log('[devert-loop] Website-only playback enabled; Discord login, voice, and announcements paused.');
  return {
    ...controller,
    getState: () => ({ ...controller.getState(), delivery: 'website',
      discord: { enabled: false, voiceConnected: false } }),
  };
}

export async function startDevertLoopWorker({ token, voiceChannelId, textChannelId, playback, onAdMessage, log = console,
  diagnostics, signal }) {
  if (!token || !voiceChannelId || !playback) throw new Error('AdLoop requires a separate Discord token, voice channel, and DeVert scheduler');
  const client = new Client({ rest: DISCORD_REST_OPTIONS, intents: [GatewayIntentBits.Guilds, GatewayIntentBits.GuildVoiceStates,
    GatewayIntentBits.GuildMessages, GatewayIntentBits.GuildMessageReactions,
    ...(onAdMessage ? [GatewayIntentBits.MessageContent] : [])] });
  const detachDiagnostics = diagnostics?.attach(client);
  const sessionWatch = watchDiscordSession(client);
  let controller = null;
  let voice = null;
  let controllerStarted = false;
  let readyError;
  let resolveReady;
  let rejectReady;
  const ready = new Promise((resolve, reject) => { resolveReady = resolve; rejectReady = reject; });
  const abort = () => rejectReady(signal.reason || new Error('Discord startup aborted'));
  signal?.addEventListener('abort', abort, { once: true });
  if (signal?.aborted) abort();
  client.once(Events.ClientReady, async readyClient => {
    try {
      const voiceChannel = await readyClient.channels.fetch(voiceChannelId);

    const textChannel = textChannelId ? await readyClient.channels.fetch(textChannelId).catch(() => null) : null;
    signal?.throwIfAborted();
    if (!voiceChannel?.isVoiceBased()) throw new Error('VERTLOOP_VOICE_CHANNEL_ID must refer to a voice channel');
    const player = createAudioPlayer();
    voice = createVoiceConnectionSupervisor({
      name: 'devert-loop',
      voiceChannel,
      player,
      joinVoiceChannel,
      entersState,
      VoiceConnectionStatus,
      joinOptions: () => ({ channelId: voiceChannel.id, guildId: voiceChannel.guild.id,
        adapterCreator: voiceChannel.guild.voiceAdapterCreator, group: `devert:${readyClient.user.id}` }),
      subscribe: connection => connection.subscribe(player),
      onReady: async () => {
        if (controller && !controllerStarted) {
          controllerStarted = true;
          await controller.start();
        }
      },
      log,
    });
    controller = createDevertLoopController({ player, playback, voiceChannel, textChannel, log });
    player.on('error', error => log.warn('[devert-loop] Discord audio player:', error.message));
    await voice.connect();
    log.log(`[devert-loop] Logged in as ${readyClient.user.tag}; joined ${voiceChannel.name}.`);
    resolveReady();
  } catch (error) {
    readyError = error;
    rejectReady(error);
  }
});
client.on(Events.Error, error => log.error('[devert-loop] Discord client:', error.message));
client.on(Events.MessageCreate, message => {
  if (!message.author.bot && onAdMessage) Promise.resolve(onAdMessage(message))
    .catch(error => log.warn('[devert-loop] Ad intake failed:', error.message));
});
client.on(Events.MessageReactionAdd, (reaction, user) => {

    const vote = reaction.emoji.name === '👍' ? 1 : reaction.emoji.name === '👎' ? -1 : 0;
    if (!vote || user.bot || !controller || reaction.message.channelId !== textChannelId) return;
    controller.submitVote({ messageId: reaction.message.id, voterId: `discord:${user.id}`.replace(':', '_'), vote })
      .catch(error => log.warn('[devert-loop] Vote rejected:', error.message));
  });
  try { await Promise.all([loginDiscordClient(client, token, { log, signal, notBefore: null }), ready]); }
  catch (error) {
    controller?.stop(); voice?.stop(); await client.destroy(); sessionWatch.dispose(); detachDiagnostics?.(); throw readyError || error;
  } finally {
    signal?.removeEventListener('abort', abort);
  }
  return {
    closed: sessionWatch.closed,
    getState: () => {
      const base = controller?.getState() || { ready: false, nowPlaying: null };
      return { ...base, ...(voice?.getState() || {}) };
    },
    submitVote: payload => controller ? controller.submitVote(payload) : Promise.reject(new Error('VertLoop is not ready')),
    removeCampaign: campaignId => controller?.removeCampaign(campaignId),
    stop() { controller?.stop(); voice?.stop(); client.destroy(); sessionWatch.dispose(); detachDiagnostics?.(); },
  };
}

import { id, isAddress } from 'ethers';
import { planDevertQueues } from '../js/devert-scheduler.mjs';
import { DEFAULT_WORKER_MIN_BALANCE_WEI, readWorkerGasState } from '../js/worker-gas.mjs';

const SCHEMA_VERSION = 1;
const MUSIC_PLAYS_PER_MAIN_AD = 10;
const MUSIC_BATCH_SIZE = 10;
const MAX_SAVED_IDS = 2000;
const MIN_AUDIBLE_MS = 30_000;
const INITIAL_RESTORE_RETRY_MS = 5_000;
const MAX_RESTORE_RETRY_MS = 5 * 60_000;
const VERTLOOP_IMPRESSION_MIN_INTERVAL_MS = 60 * 60_000;
const WORKER_GAS_CHECK_MS = 60_000;
const WORKER_GAS_DAILY_BURN_WEI = 86_000_000_000_000n;

function isInsufficientFundsError(error) {
  return /insufficient funds/i.test(error?.shortMessage || error?.message || '') || error?.code === 'INSUFFICIENT_FUNDS';
}

export async function initializeDevertPlaybackWithRetry({ initialize, wait = delay => new Promise(resolve => setTimeout(resolve, delay)), log = console }) {
  let attempt = 0;
  while (true) {
    try {
      return await initialize();
    } catch (error) {
      attempt++;
      const delay = Math.min(MAX_RESTORE_RETRY_MS, INITIAL_RESTORE_RETRY_MS * 2 ** Math.min(attempt - 1, 16));
      log.warn(`[devert] Durable scheduler restore attempt ${attempt} failed; retrying in ${Math.ceil(delay / 1000)}s: ${error.message}`);
      await wait(delay);
    }
  }
}

function emptyJournal() {
  return { schemaVersion: SCHEMA_VERSION, musicWeekId: null, pendingMusicPlayIds: [], seenMusicPlayIds: [], impressions: [], adVotes: [] };
}

function validateJournal(value) {
  if (!value || value.schemaVersion !== SCHEMA_VERSION ||
    value.musicWeekId !== null && (!Number.isSafeInteger(value.musicWeekId) || value.musicWeekId < 0) ||
    !Array.isArray(value.pendingMusicPlayIds) || !Array.isArray(value.seenMusicPlayIds) || !Array.isArray(value.impressions) ||

    value.adVotes !== undefined && !Array.isArray(value.adVotes)) {
    throw new Error('Invalid DeVert playback journal');
  }
  const impressionIds = new Set();
  for (const entry of value.impressions) {
    if (!entry || typeof entry.impressionId !== 'string' || !/^0x[0-9a-f]{64}$/i.test(entry.impressionId) ||
      !['pending', 'recorded'].includes(entry.state) || !Number.isSafeInteger(Number(entry.campaignId)) ||
      typeof entry.mainRadio !== 'boolean' || entry.nextRetryAt !== undefined && (!Number.isSafeInteger(entry.nextRetryAt) || entry.nextRetryAt < 0) ||
      entry.submittedAt !== undefined && !Number.isFinite(Date.parse(entry.submittedAt))) throw new Error('Invalid DeVert impression journal entry');
    if (impressionIds.has(entry.impressionId)) throw new Error('Duplicate DeVert impression journal entry');
    impressionIds.add(entry.impressionId);
  }
  if (value.pendingMusicPlayIds.some(playId => typeof playId !== 'string' || !/^0x[0-9a-f]{64}$/i.test(playId)) ||
    value.seenMusicPlayIds.some(playId => typeof playId !== 'string' || !/^0x[0-9a-f]{64}$/i.test(playId))) {
    throw new Error('Invalid DeVert music-play journal entry');
  }
  const adVotes = value.adVotes || [];
  const voteKeys = new Set();
  for (const entry of adVotes) {
    if (!entry || !/^\d+$/.test(String(entry.campaignId)) || typeof entry.radioPlayId !== 'string' || !entry.radioPlayId ||
      typeof entry.voterId !== 'string' || !/^[a-zA-Z0-9_-]{16,128}$/.test(entry.voterId) ||
      entry.vote !== 1 && entry.vote !== -1) throw new Error('Invalid DeVert radio ad vote');
    const key = `${entry.radioPlayId}:${entry.voterId}`;
    if (voteKeys.has(key)) throw new Error('Duplicate DeVert radio ad vote');
    voteKeys.add(key);
  }
  return structuredClone({ ...value, adVotes });
}

export function createDevertPlaybackRuntime({ contract, provider = contract?.runner?.provider, restore, save,
  readCampaigns, resolveCampaignMedia = () => null, isCampaignRemoved = () => false, now = () => Date.now(), minimumAudibleMs = MIN_AUDIBLE_MS, log = console,
  workerAddress, workerMinBalanceWei = DEFAULT_WORKER_MIN_BALANCE_WEI, workerDailyBurnWei = WORKER_GAS_DAILY_BURN_WEI, workerGasReader = readWorkerGasState,
  workerGasCheckMs = WORKER_GAS_CHECK_MS }) {
  if (!contract || typeof restore !== 'function' || typeof save !== 'function' || typeof readCampaigns !== 'function') {
    throw new Error('DeVert playback requires a contract and durable journal store');
  }
  if (!provider || !isAddress(contract.target)) throw new Error('DeVert playback needs a Base provider and contract');
  let journal = emptyJournal();
  let initialized = false;
  let queue = Promise.resolve();
  let retryTimer = null;
  let workerGasState = null;
  let workerGasCheckedAt = 0;
  let workerGasWarningAt = 0;
  let insufficientFundsBalanceWei = null;
  const workerWallet = workerAddress && isAddress(workerAddress) ? workerAddress : null;
  const vertLoopNextRetryAtByCampaign = new Map();

  const run = operation => {
    const result = queue.then(operation);
    queue = result.catch(() => {});
    return result;
  };
  const commit = async next => {
    const validated = validateJournal(next);
    const uri = await save(structuredClone(validated));
    if (typeof uri !== 'string' || !uri.startsWith('ipfs://')) throw new Error('DeVert playback journal was not durably checkpointed');
    journal = validated;
  };
  const requireReady = () => { if (!initialized) throw new Error('DeVert playback journal is not initialized'); };

  const warnWorkerGas = state => {

  if (!state || state.checkedAt <= workerGasWarningAt) return;
  workerGasWarningAt = state.checkedAt;
  if (state.unavailable) {
    log.warn(`[devert] Worker gas check unavailable${workerWallet ? ` for ${workerWallet}` : ''}: ${state.reason}`);
    return;
  }
  if (state.lowBalance) {
    const thresholdWei = state.thresholdWei ?? workerMinBalanceWei;
    log.warn(`[devert] Worker gas low${workerWallet ? ` for ${workerWallet}` : ''}: ${state.balanceWei} wei (threshold ${thresholdWei} wei; runway ~${state.runwayDays ?? 'unknown'} day${state.runwayDays === 1 ? '' : 's'})`);
  }
};

const hydrateVertLoopRetryState = () => {
  vertLoopNextRetryAtByCampaign.clear();
  const campaignRetryAt = new Map();
  for (const entry of journal.impressions) {
    if (entry.mainRadio || entry.state !== 'recorded') continue;
    const submittedAt = Number.isFinite(Date.parse(entry.submittedAt || entry.recordedAt || ''))
      ? Date.parse(entry.submittedAt || entry.recordedAt) : 0;
    const nextEligibleAt = submittedAt > 0 ? submittedAt + VERTLOOP_IMPRESSION_MIN_INTERVAL_MS : 0;
    if (nextEligibleAt > 0) campaignRetryAt.set(entry.campaignId, Math.max(campaignRetryAt.get(entry.campaignId) || 0, nextEligibleAt));
  }
  for (const [campaignId, retryAt] of campaignRetryAt) vertLoopNextRetryAtByCampaign.set(campaignId, retryAt);
  journal = {
    ...journal,
    impressions: journal.impressions.map(entry => {
      if (entry.mainRadio) return entry;
      if (entry.state === 'recorded') {
        return entry;
      }
      const submittedAt = Number.isFinite(Date.parse(entry.submittedAt || entry.recordedAt || ''))
        ? Date.parse(entry.submittedAt || entry.recordedAt) : 0;

      const retryFloor = vertLoopNextRetryAtByCampaign.get(entry.campaignId) || 0;
      const nextRetryAt = Number.isSafeInteger(entry.nextRetryAt) && entry.nextRetryAt > 0
        ? Math.max(entry.nextRetryAt, retryFloor) : Math.max(retryFloor, submittedAt || now());
      return nextRetryAt === entry.nextRetryAt ? entry : { ...entry, nextRetryAt };
    }),
  };
  // Collapse any legacy VertLoop backlog to the oldest pending entry per campaign.
  const keptVertLoopPending = new Set();
  journal = {
    ...journal,
    impressions: journal.impressions.filter(entry => {
      if (entry.mainRadio || entry.state !== 'pending') return true;
      if (keptVertLoopPending.has(entry.campaignId)) return false;
      keptVertLoopPending.add(entry.campaignId);
      return true;
    }),
  };
};

const refreshWorkerGasState = async ({ force = false } = {}) => {
  if (!workerWallet || typeof workerGasReader !== 'function') {
    workerGasState = { checkedAt: now(), unavailable: true, lowBalance: false, reason: 'worker wallet unavailable', workerAddress: workerWallet };
    return workerGasState;
  }
  if (!force && workerGasState && now() - workerGasCheckedAt < workerGasCheckMs) return workerGasState;
  try {
    const state = await workerGasReader({ provider, workerAddress: workerWallet, minBalanceWei: workerMinBalanceWei, estimatedDailyBurnWei: workerDailyBurnWei });
    workerGasCheckedAt = now();
    // A node-reported shortfall stays latched until the balance actually rises, even if it clears the threshold.
    let lowBalance = Boolean(state.lowBalance);
    if (insufficientFundsBalanceWei !== null) {

      if (typeof state.balanceWei === 'bigint' && state.balanceWei > insufficientFundsBalanceWei) insufficientFundsBalanceWei = null;
      else lowBalance = true;
    }
    workerGasState = { ...state, lowBalance, checkedAt: workerGasCheckedAt };
  } catch (error) {
    workerGasCheckedAt = now();
    workerGasState = {
      checkedAt: workerGasCheckedAt,
      unavailable: true,
      lowBalance: false,
      reason: error?.shortMessage || error?.message || 'worker gas check failed',
      workerAddress: workerWallet,
    };
  }
  warnWorkerGas(workerGasState);
  return workerGasState;
};

const canSpendWorkerGas = async () => {
  const state = await refreshWorkerGasState();
  return state && !state.unavailable && !state.lowBalance;
};

const markInsufficientFunds = async error => {
  let balanceWei = null;
  try { if (workerWallet) balanceWei = await provider.getBalance(workerWallet); } catch {}
  if (typeof balanceWei !== 'bigint') balanceWei = typeof workerGasState?.balanceWei === 'bigint' ? workerGasState.balanceWei : 0n;
  insufficientFundsBalanceWei = balanceWei;
  workerGasState = {
    checkedAt: now(),
    unavailable: false,
    lowBalance: true,
    reason: error?.shortMessage || error?.message || 'worker gas low',
    workerAddress: workerWallet,
    balanceWei,
    thresholdWei: workerMinBalanceWei,
    runwayDays: 0,
  };
  workerGasCheckedAt = workerGasState.checkedAt;
  warnWorkerGas(workerGasState);
};

async function flushMusicBatch() {
  if (journal.pendingMusicPlayIds.length < MUSIC_BATCH_SIZE) return false;
  if (!await canSpendWorkerGas()) return false;
  const block = await provider.getBlock('latest');

  const chainWeek = Number(await contract.campaignWeek(block.timestamp));
  if (chainWeek !== journal.musicWeekId) {
    await commit({ ...journal, musicWeekId: chainWeek, pendingMusicPlayIds: [] });
    return false;
  }
  const batch = journal.pendingMusicPlayIds.slice(0, MUSIC_BATCH_SIZE);
  try {
    await contract.reportCompletedMusicPlays.staticCall(batch);
    const transaction = await contract.reportCompletedMusicPlays(batch);
    if ((await transaction.wait(2))?.status !== 1) throw new Error(`DeVert music-play report failed: ${transaction.hash}`);
  } catch (error) {
    if (!isInsufficientFundsError(error)) throw error;
    await markInsufficientFunds(error);
    return false;
  }
  await commit({ ...journal, pendingMusicPlayIds: journal.pendingMusicPlayIds.slice(batch.length) });
  return true;
}

async function submitImpression(entry) {
  if (entry.state === 'recorded') return entry;
  if (Number.isSafeInteger(entry.nextRetryAt) && entry.nextRetryAt > now()) return false;
  if (!await canSpendWorkerGas()) return false;
  if (await contract.usedImpressionIds(entry.impressionId)) {
    const submittedAt = new Date(now()).toISOString();
    const nextEligibleAt = !entry.mainRadio ? Date.parse(submittedAt) + VERTLOOP_IMPRESSION_MIN_INTERVAL_MS : 0;
    const next = { ...journal, impressions: journal.impressions.map(item => {
      if (item.impressionId === entry.impressionId) return { ...item, state: 'recorded', submittedAt };
      if (!entry.mainRadio && !item.mainRadio && item.state === 'pending' && item.campaignId === entry.campaignId) {
        return { ...item, nextRetryAt: Math.max(Number.isSafeInteger(item.nextRetryAt) ? item.nextRetryAt : 0, nextEligibleAt) };
      }
      return item;

  }) };
  await commit(next);
  if (!entry.mainRadio) {
    vertLoopNextRetryAtByCampaign.set(entry.campaignId, Math.max(vertLoopNextRetryAtByCampaign.get(entry.campaignId) || 0, nextEligibleAt));
  }
  return next.impressions.find(item => item.impressionId === entry.impressionId);
}
try {
  await contract.recordCampaignPlay.staticCall(BigInt(entry.campaignId), entry.mainRadio, entry.impressionId);
  const transaction = await contract.recordCampaignPlay(BigInt(entry.campaignId), entry.mainRadio, entry.impressionId);
  if ((await transaction.wait(2))?.status !== 1) throw new Error(`DeVert impression failed: ${transaction.hash}`);
  const submittedAt = new Date(now()).toISOString();
  const nextEligibleAt = !entry.mainRadio ? Date.parse(submittedAt) + VERTLOOP_IMPRESSION_MIN_INTERVAL_MS : 0;
  const next = { ...journal, impressions: journal.impressions.map(item => {
    if (item.impressionId === entry.impressionId) {
      return { ...item, state: 'recorded', submittedAt, transactionHash: transaction.hash };
    }
    if (!entry.mainRadio && !item.mainRadio && item.state === 'pending' && item.campaignId === entry.campaignId) {
      return { ...item, nextRetryAt: Math.max(Number.isSafeInteger(item.nextRetryAt) ? item.nextRetryAt : 0, nextEligibleAt) };
    }
    return item;
  }) };
  await commit(next);
  if (!entry.mainRadio) {
    vertLoopNextRetryAtByCampaign.set(entry.campaignId, Math.max(vertLoopNextRetryAtByCampaign.get(entry.campaignId) || 0, nextEligibleAt));
  }
  return next.impressions.find(item => item.impressionId === entry.impressionId);
} catch (error) {

    if (entry.mainRadio && error.code === 'CALL_EXCEPTION' && error.reason === 'No seated main-radio slot') {
      await commit({ ...journal, impressions: journal.impressions.map(item =>
        item.impressionId === entry.impressionId ? { ...item, nextRetryAt: now() + workerGasCheckMs } : item) });
      log.warn(`[devert] Main-radio impression ${entry.impressionId} for campaign ${entry.campaignId} remains pending: ${error.reason}; retrying after the slot cooldown.`);
      return false;
    }
    if (!isInsufficientFundsError(error)) throw error;
    await markInsufficientFunds(error);
    return false;
  }
}

async function retryPendingImpressions({ force = false } = {}) {
  if (!journal.impressions.some(item => item.state === 'pending')) return false;
  const state = await refreshWorkerGasState({ force });
  if (!state || state.unavailable || state.lowBalance) return false;
  if ((await readCampaigns()).paused) return false;
  let progressed = false;
  for (const impressionId of journal.impressions.filter(item => item.state === 'pending').map(item => item.impressionId)) {
    const entry = journal.impressions.find(item => item.impressionId === impressionId && item.state === 'pending');
    if (!entry) continue;
    const submitted = await submitImpression(entry);
    if (submitted && submitted.state === 'recorded') progressed = true;
  }
  return progressed;
}

const retryDeferredWork = async () => {
  if (!initialized) return false;
  const force = Boolean(workerGasState?.lowBalance || workerGasState?.unavailable);
  const state = await refreshWorkerGasState({ force });
  if (!state || state.unavailable || state.lowBalance) return false;
  if ((await readCampaigns()).paused) return false;

  let progressed = false;
  while (journal.pendingMusicPlayIds.length >= MUSIC_BATCH_SIZE) {
    const flushed = await flushMusicBatch();
    if (!flushed) break;
    progressed = true;
  }
  if (await retryPendingImpressions({ force })) progressed = true;
  return progressed;
};

const startRetryTimer = () => {
  if (retryTimer) return;
  retryTimer = setInterval(() => {
    run(() => retryDeferredWork().catch(error => log.warn(`[devert] Deferred worker retry failed: ${error.message}`)));
  }, workerGasCheckMs);
  retryTimer.unref?.();
};

function campaignTrack(campaign, kind) {
  const ipfsCid = campaign.audioURI.slice('ipfs://'.length);
  const media = resolveCampaignMedia(campaign, ipfsCid);
  const mediaType = media?.mediaType || (media?.videoUrl ? 'video/mp4' : '');
  return { campaignId: campaign.campaignId, advertiser: campaign.advertiser, source: 'devert', kind, trackId: `devert:${campaign.campaignId}`,
    title: campaign.title, uploader: 'DeVert advertiser',
    filename: media?.filename || `devert-${campaign.campaignId}.${mediaType === 'video/mp4' ? 'mp4' : 'mp3'}`,
    mediaType, videoUrl: media?.videoUrl || (mediaType === 'video/mp4' ? `ipfs://${ipfsCid}` : ''),
    ipfsCid, pinStatus: 'untracked' };
}

return {
  isCampaignRemoved,
  async canPlayCampaign(campaignId) {
    requireReady();
    if (isCampaignRemoved(campaignId)) return false;
    const snapshot = await readCampaigns();
    return snapshot.chainId === 8453 && !snapshot.paused && snapshot.campaigns.some(campaign =>
      campaign.campaignId === String(campaignId) && !campaign.removed &&
      Date.parse(campaign.startedAt) <= now() && now() < Date.parse(campaign.expiresAt));
  },
  initialize: () => run(async () => {

  const restored = await restore();
  journal = restored ? validateJournal(restored) : emptyJournal();
  hydrateVertLoopRetryState();
  initialized = true;
  startRetryTimer();
  await retryDeferredWork();
  return structuredClone(journal);
}),
recordCompletedMusicPlay: ({ playId, audibleMs }) => run(async () => {
  requireReady();
  if (typeof playId !== 'string' || !playId || playId.length > 256) throw new Error('Invalid completed music play ID');
  if (!Number.isSafeInteger(audibleMs) || audibleMs < minimumAudibleMs) return false;
  const musicPlayId = id(playId);
  const block = await provider.getBlock('latest');
  const weekId = Number(await contract.campaignWeek(block.timestamp));
  const pendingMusicPlayIds = journal.musicWeekId === weekId ? [...journal.pendingMusicPlayIds] : [];
  const seen = new Set(journal.seenMusicPlayIds);
  if (seen.has(musicPlayId)) return false;
  pendingMusicPlayIds.push(musicPlayId);
  const nextSeen = [...journal.seenMusicPlayIds, musicPlayId].slice(-MAX_SAVED_IDS);
  await commit({ ...journal, musicWeekId: weekId, pendingMusicPlayIds, seenMusicPlayIds: nextSeen });
  await retryDeferredWork();
  return true;
}),
async nextMainRadioAd({ excludeCampaignIds = [], count = 1 } = {}) {
  requireReady();
  await retryPendingImpressions({ force: Boolean(workerGasState?.lowBalance || workerGasState?.unavailable) });
  const snapshot = await readCampaigns();
  if (snapshot.chainId !== 8453 || snapshot.paused || !Array.isArray(snapshot.campaigns) ||
    snapshot.market.mainRadioImpressions >= snapshot.market.slots) return null;
  const at = Date.parse(snapshot.snapshotAt);

  const plan = planDevertQueues({ campaigns: snapshot.campaigns,
    completedSongPlays: snapshot.market.slots * MUSIC_PLAYS_PER_MAIN_AD, now: at });
  const excluded = new Set(excludeCampaignIds.map(String));
  const voteScores = new Map();
  for (const entry of journal.adVotes) {
    voteScores.set(entry.campaignId, (voteScores.get(entry.campaignId) || 0) + entry.vote);
  }
  const limit = Number.isSafeInteger(count) && count > 0 ? count : 1;
  const campaigns = plan.mainRadio.filter(item => !item.removed && !excluded.has(item.campaignId))
    .sort((first, second) => Number(second.djukeBoosts || 0) - Number(first.djukeBoosts || 0) ||
      Number((second.mainRadioPlays || 0) === 0) - Number((first.mainRadioPlays || 0) === 0) ||
      (voteScores.get(second.campaignId) || 0) - (voteScores.get(first.campaignId) || 0))
    .slice(0, limit);
  if (limit === 1) {
    const [campaign] = campaigns;
    return campaign ? { campaignId: campaign.campaignId, mainRadio: true, track: campaignTrack(campaign, 'main-radio') } : null;
  }
  return campaigns.map(campaign => ({ campaignId: campaign.campaignId, mainRadio: true, track: campaignTrack(campaign, 'main-radio') }));
},
getMainRadioAdVoteSummary: radioPlayId => {
  requireReady();
  const votes = journal.adVotes.filter(entry => entry.radioPlayId === radioPlayId);
  const up = votes.filter(entry => entry.vote === 1).length;
  const down = votes.filter(entry => entry.vote === -1).length;
  return { up, down, net: up - down };
},
recordMainRadioAdVote: ({ campaignId, radioPlayId, voterId, vote }) => run(async () => {
  requireReady();

  if (!/^\d+$/.test(String(campaignId)) || typeof radioPlayId !== 'string' || !radioPlayId ||
      typeof voterId !== 'string' || !/^[a-zA-Z0-9_-]{16,128}$/.test(voterId) || (vote !== 1 && vote !== -1)) {
    throw new Error('Invalid DeVert radio ad vote');
  }
  const existing = journal.adVotes.find(entry => entry.radioPlayId === radioPlayId && entry.voterId === voterId);
  if (existing) return { campaignId: existing.campaignId, radioPlayId, vote: existing.vote, duplicate: true };
  const entry = { campaignId: String(campaignId), radioPlayId, voterId, vote, recordedAt: new Date(now()).toISOString() };
  await commit({ ...journal, adVotes: [...journal.adVotes, entry].slice(-MAX_SAVED_IDS) });
  return { campaignId: entry.campaignId, radioPlayId, vote, duplicate: false };
}),
async nextDevertLoopAd({ excludeCampaignIds = [] } = {}) {
  requireReady();
  await retryPendingImpressions({ force: Boolean(workerGasState?.lowBalance || workerGasState?.unavailable) });
  const snapshot = await readCampaigns();
  if (snapshot.chainId !== 8453 || snapshot.paused || !Array.isArray(snapshot.campaigns)) return null;
  const nowMs = Date.parse(snapshot.snapshotAt);
  const excluded = new Set(excludeCampaignIds.map(String));
  const campaign = snapshot.campaigns.filter(item => {
    const start = Date.parse(item.startedAt);
    const end = Date.parse(item.expiresAt);
    return start <= nowMs && nowMs < end && !item.removed && !excluded.has(String(item.campaignId));
  }).sort((first, second) => Number(second.djukeBoosts || 0) - Number(first.djukeBoosts || 0) ||
    Number(first.devertPlays || 0) - Number(second.devertPlays || 0) ||

    (BigInt(second.offerUnits) > BigInt(first.offerUnits) ? 1 : BigInt(second.offerUnits) < BigInt(first.offerUnits) ? -1 :
      String(first.campaignId).localeCompare(String(second.campaignId))));
  return campaign[0] ? { campaignId: String(campaign[0].campaignId), mainRadio: false,
    track: campaignTrack(campaign[0], 'devert-loop') } : null;
},
recordCampaignImpression: ({ campaignId, radioPlayId, mainRadio, audibleMs }) => run(async () => {
  requireReady();
  if (!Number.isSafeInteger(audibleMs) || audibleMs < minimumAudibleMs) return false;
  if (!/^\d+$/.test(String(campaignId)) || typeof radioPlayId !== 'string' || !radioPlayId) throw new Error('Invalid DeVert impression identity');
  const impressionId = id(`devert-impression:${campaignId}:${radioPlayId}:${mainRadio ? 'main' : 'broadcast'}`);
  let entry = journal.impressions.find(item => item.impressionId === impressionId);
  if (entry?.state === 'recorded') return true;
  if (!entry) {
    // VertLoop coalesces: at most one pending or recently recorded impression per campaign per window.
    if (mainRadio !== true) {
      const key = String(campaignId);
      const hasPending = journal.impressions.some(item => !item.mainRadio && item.state === 'pending' && item.campaignId === key);
      if (hasPending || (vertLoopNextRetryAtByCampaign.get(key) || 0) > now()) return false;
    }
    entry = { impressionId, campaignId: String(campaignId), mainRadio: mainRadio === true, radioPlayId,
      recordedAt: new Date(now()).toISOString(), state: 'pending', nextRetryAt: mainRadio === true ? 0
        : Math.max(vertLoopNextRetryAtByCampaign.get(String(campaignId)) || 0, now()) };

        await commit({ ...journal, impressions: [...journal.impressions, entry].slice(-MAX_SAVED_IDS) });
      }
      await submitImpression(entry);
      return true;
    }),
    getState: () => { requireReady(); return structuredClone(journal); },
    getWorkerGasState: async () => structuredClone(await refreshWorkerGasState()),
  };
}

import { Contract, id, isAddress } from 'ethers';
import { devertQueueAbi, DEVERT_QUEUE_USDC, quoteDevertRequest } from '../js/devert-queue.mjs';
import { createDjukePlaybackJournal, createDjukeRuntime } from './djuke.js';

export function createDevertQueueCatalogSync({ contract, removals, readCampaigns, resolveApprovedMedia, beforeRemove = async () => {} }) {
  const confirmedRemovals = new Set();
  const confirmedApprovals = new Set();
  let task;
  const reconcile = async () => {
    for (const { campaignId } of removals.list()) {
      if (confirmedRemovals.has(campaignId)) continue;
      await beforeRemove(campaignId);
      if (!await contract.removedCampaigns(BigInt(campaignId))) {
        const tx = await contract.removeCampaign(BigInt(campaignId));
        if ((await tx.wait(2))?.status !== 1) throw new Error(`Paid advert removal failed: ${tx.hash}`);
      }
      confirmedRemovals.add(campaignId);
    }
    const catalog = await readCampaigns();
    for (const campaign of catalog.campaigns) {
      if (campaign.removed || confirmedRemovals.has(campaign.campaignId) || confirmedApprovals.has(campaign.campaignId)) continue;
      const cid = campaign.audioURI?.startsWith('ipfs://') ? campaign.audioURI.slice(7) : '';
      if (!cid || !resolveApprovedMedia(campaign, cid)) continue;
      if (await contract.removedCampaigns(BigInt(campaign.campaignId))) {
        confirmedRemovals.add(campaign.campaignId);
        continue;
      }
      if (!await contract.approvedCampaigns(BigInt(campaign.campaignId))) {
        const tx = await contract.approveCampaign(BigInt(campaign.campaignId));
        if ((await tx.wait(2))?.status !== 1) throw new Error(`Paid advert approval failed: ${tx.hash}`);
      }
      confirmedApprovals.add(campaign.campaignId);
    }

    return [...confirmedApprovals].filter(campaignId => !confirmedRemovals.has(campaignId));
  };
  return () => { task ||= reconcile().finally(() => { task = null; }); return task; };
}

export function paidAdvertTrack(request, resolveCampaignMedia = () => null) {
  const cid = request.audioURI?.startsWith('ipfs://') ? request.audioURI.slice(7) : '';
  if (!cid || /[?#\s]/.test(cid)) throw new Error('Paid advert has an invalid IPFS recording');
  const media = resolveCampaignMedia(request, cid);
  const mediaType = media?.mediaType || '';
  return { trackId: `devert-paid:${request.chainRequestId}`, campaignId: request.campaignId,
    title: request.title, ipfsCid: cid, uploader: 'DeVert advertiser', advertiser: request.advertiser,
    filename: media?.filename || 'paid-ad.mp3', mediaType,
    videoUrl: media?.videoUrl || (mediaType === 'video/mp4' ? request.audioURI : ''), isDevertAd: true,
    paidTier: request.tier ?? 1 };
}

export function createDevertQueueReader({ provider, contractAddress, contract, paymentsEnabled = false,
  getApprovedCampaignIds = () => [], getPlaybackStatus = () => ({ ready: true, reason: null }), cacheMs = 0, version = 1 }) {
  if (!isAddress(contractAddress) || /^0x0{40}$/i.test(contractAddress)) throw new Error('Invalid paid advert queue address');
  const abi = devertQueueAbi(version);
  const queue = contract || new Contract(contractAddress, abi, provider);
  let task;
  let cached;
  let cachedAt = 0;
  const read = async () => {
    if (Number((await provider.getNetwork()).chainId) !== 8453) throw new Error('Paid advert queue is Base-only');
    const blockNumber = await provider.getBlockNumber() - 1;
    const before = await provider.getBlock(blockNumber);

if (blockNumber < 0 || !before?.hash) throw new Error('Paid advert confirmation block unavailable');
const options = { blockTag: blockNumber };
if (version === 2 && Number(await queue.queueVersion(options)) !== 2) throw new Error('Paid advert queue version mismatch');
const [headValue, nextValue, countValue, price, paused, token] = await Promise.all([
  queue.headRequestId(options), queue.nextRequestId(options), queue.pendingCount(options),
  queue.quote(options), queue.paused(options), queue.paymentToken(options),
]);
const head = Number(headValue), next = Number(nextValue), pendingCount = Number(countValue);
if (![head, next, pendingCount].every(n => Number.isSafeInteger(n) && n >= 0) ||
    next < head || next - head > 128 || pendingCount > next - head ||
    BigInt(price) !== quoteDevertRequest(pendingCount) || token.toLowerCase() !== DEVERT_QUEUE_USDC.toLowerCase()) {
  throw new Error('Invalid paid advert queue snapshot');
}
const requests = [], recentRefunds = [];
const rows = [];
for (let start = Math.max(0, head - 128); start < next; start += 8) {
  const ids = Array.from({ length: Math.min(8, next - start) }, (_, i) => start + i);
  rows.push(...await Promise.all(ids.map(async n => ({ n, raw: await queue.getRequest(n, options) }))));
}
const removed = new Map();
const campaignIds = [...new Set(rows.map(({ raw }) => raw.campaignId.toString()))];
for (let start = 0; start < campaignIds.length; start += 8) {
  await Promise.all(campaignIds.slice(start, start + 8).map(async campaignId => {
    removed.set(campaignId, await queue.removedCampaigns(campaignId, options));
  }));
}
for (const { n, raw } of rows) {

  const campaignId = raw.campaignId.toString();
  const tier = version === 1 ? 1 : Number(raw.tier);
  if (!isAddress(raw.payer) || !isAddress(raw.advertiser) || BigInt(raw.amount) <= 0n ||
      !raw.title || !raw.audioURI?.startsWith('ipfs://') || ![0, 1, 2].includes(Number(raw.status)) ||
      ![0, 1].includes(tier)) throw new Error('Invalid paid advert request');
  const request = { requestId: `8453:${contractAddress.toLowerCase()}:${n}`, chainRequestId: String(n),
    campaignId, payer: raw.payer, amountUnits: raw.amount.toString(), title: raw.title,
    audioURI: raw.audioURI, advertiser: raw.advertiser, songId: id(`devert-paid:${n}`),
    revision: '0', trackId: `devert-paid:${n}`, playable: true, tier };
  if (Number(raw.status) === 0) {
    if (removed.get(campaignId)) recentRefunds.push(request);
    else if (n >= head) requests.push(request);
    else throw new Error('Paid advert FIFO head is inconsistent');
  }
}
const approvedCampaignIds = [];
const candidates = [...new Set(getApprovedCampaignIds())];
for (let start = 0; start < candidates.length; start += 8) {
  const approved = await Promise.all(candidates.slice(start, start + 8).map(async campaignId =>
    await queue.approvedCampaigns(campaignId, options) && !await queue.removedCampaigns(campaignId, options) ? campaignId : null));
  approvedCampaignIds.push(...approved.filter(campaignId => campaignId !== null));
}
if (requests.length !== pendingCount || (await provider.getBlock(blockNumber))?.hash !== before.hash) throw new Error('Paid advert queue changed during verification');
if (version === 2) {
  for (const tier of [0, 1]) {
    const [tierHead, tierPrice] = await Promise.all([

          queue.headRequestIdForTier(tier, options), queue.quoteForTier(tier, options),
        ]);
        const expectedHead = requests.find(request => request.tier === tier)?.chainRequestId ?? String(next);
        if (String(tierHead) !== expectedHead || BigInt(tierPrice) !== quoteDevertRequest(pendingCount, tier)) {
          throw new Error('Paid advert tier head or quote mismatch');
        }
      }
      if ((await provider.getBlock(blockNumber))?.hash !== before.hash) throw new Error('Paid advert queue changed during verification');
    }
    return { chainId: 8453, contractAddress, version, blockNumber, blockHash: before.hash, requests, recentRefunds, approvedCampaignIds,
      pendingCount, priceUnits: price.toString(), immediatePriceUnits: version === 2 ? (BigInt(price) * 2n).toString() : null,
      paused, paymentsEnabled: version === 2 && paymentsEnabled && !paused && next - head < 128 };
  };
  return async () => {
    let state;
    if (cached && Date.now() - cachedAt < cacheMs) state = structuredClone(cached);
    else {
      task ||= read().then(state => { cached = state; cachedAt = Date.now(); return state; }).finally(() => { task = null; });
      state = await task;
    }
    const playback = getPlaybackStatus();
    return { ...state, playbackReady: playback.ready, playbackReason: playback.reason,
      paymentsEnabled: state.paymentsEnabled && playback.ready };
  };
}

export function createDevertQueueRuntime({ readState, store, contract, isCampaignRemoved = () => false, resolveCampaignMedia, log = console }) {
  let tracks = new Map();
  const removingCampaigns = new Set();
  const readPlayable = async () => {
    const state = await readState();

  tracks = new Map(state.requests.map(request => [request.trackId, paidAdvertTrack(request, resolveCampaignMedia)]));
  return state;
};
const journal = createDjukePlaybackJournal(store);
const runtime = createDjukeRuntime({ readState: readPlayable, journal,
  getTrack: trackId => tracks.get(trackId), minAudibleMs: 1000, log,
  preserveMissingRequest: async (record, state) => {
    if (!['playing', 'played'].includes(record.state)) return false;
    if (state.recentRefunds?.some(request => request.requestId === record.requestId)) return true;
    if (!/^\d+$/.test(record.chainRequestId || '')) return false;
    const request = await contract.getRequest(BigInt(record.chainRequestId));
    return Number(request.status) === 0 && await contract.removedCampaigns(request.campaignId);
  },
  canPlayRequest: (request, state) => !state.paused && !removingCampaigns.has(String(request.campaignId)) &&
    !isCampaignRemoved(request.campaignId),
  selectRequest: (state, pending, { allowBump = false } = {}) => {
    const eligible = state.requests.filter(request => !removingCampaigns.has(String(request.campaignId)) &&
      !isCampaignRemoved(request.campaignId) && pending.some(record => record.requestId === request.requestId));
    const request = eligible.find(request => (request.tier ?? 1) === 1) ||
      (allowBump ? eligible.find(request => request.tier === 0) : null);
    return request ? pending.find(record => record.requestId === request.requestId) : null;
  },
  fulfill: async ({ chainRequestId, playId }) => {
    const tx = await contract.fulfill(BigInt(chainRequestId), id(playId));
    if ((await tx.wait(2))?.status !== 1) throw new Error(`Paid advert settlement did not confirm: ${tx.hash}`);
    return tx.hash;

  } });
let claimSerial = Promise.resolve();
return {
  nextPaid(options) {
    const run = claimSerial.then(async () => {
      try {
        const selection = await runtime.nextPaid(options);
        if (selection) {
          selection.record.kind = 'devert';
          selection.record.tier = selection.track.paidTier;
        }
        return selection;
      } catch (error) {
        if (error.code === 'DEVERT_QUEUE_PAUSED') return null;
        throw error;
      }
    });
    claimSerial = run.catch(() => {});
    return run;
  },
  complete(record, play) {
    if (play?.finished !== true) return runtime.fail(record, new Error('Advert did not finish naturally; payment remains queued'));
    return runtime.complete(record, play);
  },
  fail: runtime.fail,
  release: runtime.release,
  async prepareCampaignRemoval(campaignId) {
    const id = String(campaignId);
    removingCampaigns.add(id);
    await claimSerial;
    const state = await runtime.reconcile();
    const refunds = new Map((state.recentRefunds || []).map(request => [request.requestId, request.campaignId]));
    const active = runtime.getJournalState().find(record =>
      (String(record.campaignId) === id || refunds.get(record.requestId) === id) &&
      (record.state === 'playing' || record.state === 'played'));
    if (active) throw new Error(`Campaign removal deferred until paid request ${active.requestId} finishes or settles`);
  },
  async canPlay(record) {
    const request = await contract.getRequest(BigInt(record.chainRequestId));
    if (record.tier === 0 && await contract.headRequestIdForTier(1) < await contract.nextRequestId()) return false;

      return Number(request.status) === 0 && !removingCampaigns.has(request.campaignId.toString()) &&
        !isCampaignRemoved(request.campaignId.toString()) &&
        !await contract.paused() && !await contract.removedCampaigns(request.campaignId);
    },
  };
}

export function combinePaidQueues({ songs, adverts, log = console, timeoutMs = 10000 }) {
  const selecting = new Set();
  const prepared = new Map();
  const select = async (runtime, options, label) => {
    if (!runtime) return null;
    if (prepared.has(runtime)) {
      const selection = prepared.get(runtime);
      prepared.delete(runtime);
      return selection;
    }
    if (selecting.has(runtime)) return null;
    selecting.add(runtime);
    const started = Date.now();
    let timedOut = false;
    let timer;
    const pending = Promise.resolve().then(() => runtime.nextPaid(options));
    pending.then(async selection => {
      if (timedOut && selection) {
        prepared.set(runtime, selection);
        log.info?.(`[${label}] Late queue selection retained; selectionMs=${Date.now() - started}`);
      }
    }).catch(error => {
      if (timedOut) log.warn(`[${label}] Deferred queue selection: ${error.message}`);
    }).finally(() => selecting.delete(runtime));
    try {
      return await Promise.race([pending, new Promise((_, reject) => {
        timer = setTimeout(() => {
          timedOut = true;
          reject(new Error(`Queue selection timed out after ${Date.now() - started}ms; ${songs?.hasPendingPlaylist?.()
            ? 'paid playlist holds rotation while its durable selection completes' : 'selection remains pending; playback policy decides the next item'}`));
        }, timeoutMs);
      })]);
    } catch (error) {

      log.warn(`[${label}] Paid selection deferred: ${error.message}`);
      return null;
    } finally {
      clearTimeout(timer);
    }
  };
  return {
    async nextPaid({ allowBump = false, includeSongs = true } = {}) {
      if (adverts) {
        const ad = await select(adverts, { allowBump }, 'devert-queue');
        if (ad) return ad;
      }
      return includeSongs ? select(songs, undefined, 'djuke') : null;
    },
    complete(record, play) { return (record.kind === 'devert' ? adverts : songs).complete(record, play); },
    fail(record, error) { return (record.kind === 'devert' ? adverts : songs).fail(record, error); },
    release(record, error) { return (record.kind === 'devert' ? adverts : songs).release(record, error); },
    retryMedia(record, error) { return songs.retryMedia(record, error); },
    hasPendingPlaylist() { return songs?.hasPendingPlaylist?.() === true; },
    hasPlaybackEvidence(record) { return record?.kind !== 'devert' && songs?.hasPlaybackEvidence?.(record) === true; },
    canPlay(record) { return (record.kind === 'devert' ? adverts : songs).canPlay(record); },
  };
}

export function createDevertRemovals({ restore, save, now = () => Date.now() }) {
  let removals;
  let task = Promise.resolve();
  const ready = () => { if (!removals) throw new Error('Campaign removal state is unavailable'); };
  return {
    async initialize() {
      const state = await restore();
      if (state && (state.schemaVersion !== 1 || !Array.isArray(state.removals) ||
        state.removals.some(item => !/^\d+$/.test(item.campaignId) || !/^0x[0-9a-f]{40}$/i.test(item.removedBy) ||
          !Number.isFinite(Date.parse(item.removedAt))))) throw new Error('Invalid campaign removal checkpoint');
      removals = state?.removals || [];
    },
    isRemoved(campaignId) { ready(); return removals.some(item => item.campaignId === String(campaignId)); },
    list() { ready(); return structuredClone(removals); },
    remove({ campaignId, address }) {
      const operation = task.then(async () => {
        ready();
        const existing = removals.find(item => item.campaignId === String(campaignId));
        if (existing) return structuredClone(existing);
        const entry = { campaignId: String(campaignId), removedBy: address, removedAt: new Date(now()).toISOString() };
        const next = [...removals, entry];
        const uri = await save({ schemaVersion: 1, removals: next });
        if (!uri?.startsWith('ipfs://')) throw new Error('Campaign removal could not be durably saved');
        removals = next;
        return structuredClone(entry);
      });
      task = operation.catch(() => {});
      return operation;
    },
  };
}

import { Contract, JsonRpcProvider, isAddress } from 'ethers';
import { readWorkerGasState, SPONSORED_WORKER_MIN_BALANCE_WEI } from '../js/worker-gas.mjs';

const SECONDS_PER_WEEK = 7 * 24 * 60 * 60;
const MAX_WEEKLY_CAMPAIGNS = 1000;
const READ_CONCURRENCY = 20;
const ZERO_ADDRESS = /^0x0{40}$/i;

export const DEVERT_ABI = [
  'function CONTRACT_VERSION() view returns(string)',
  'function schedulerWallet() view returns(address)',
  'function campaignWeek(uint256 timestamp) pure returns (uint64)',
  'function paused() view returns (bool)',
  'function getWeekCampaignIds(uint64 weekId) view returns (uint256[])',
  'function getCampaign(uint256 campaignId) view returns ((address advertiser,string title,string audioURI,uint64 startedAt,uint64 expiresAt,uint64 weekId,uint128 offerUnits,uint128 paidUnits,uint32 djukeBoosts,uint32 mainRadioPlays,uint32 devertPlays))',
  'function mainRadioMarket(uint64 weekId) view returns (uint32 slots,uint32 seated,uint128 lowestSeatedOfferUnits,uint32 mainRadioImpressions)',
  'function recordCampaignPlay(uint256 campaignId,bool mainRadio,bytes32 impressionId)',
  'function usedImpressionIds(bytes32 impressionId) view returns(bool)',
  'function reportCompletedMusicPlays(bytes32[] playIds)',
  'function applyDJukeBoost(uint256 campaignId,uint256 djukeRequestId)',
  'function usedDjukeRequests(uint256 djukeRequestId) view returns(bool)',
  'function createCampaign(string title,string audioURI,uint128 offerUnits,uint128 maxPaymentUnits) returns(uint256)',
  'function quoteCampaign(uint64 weekId) view returns(uint128 minimumOfferUnits,uint256 bumpedCampaignId)',
];

export function resolveDevertSchedulerPrivateKey(env = process.env) {
  return env.DEVERT_SCHEDULER_PRIVATE_KEY || env.DJUKE_FULFILLER_PRIVATE_KEY || null;
}

export async function applyDevertDjukeBoosts({ contract, readCampaigns, readDjukeState, djukeState,
  inFlightRequests = new Set(), now = () => Date.now(), log = console }) {
  if (!contract || typeof readCampaigns !== 'function' || (typeof readDjukeState !== 'function' && !djukeState)) {
    throw new Error('DeVert DJuke boosts require campaign and paid-request readers');
  }
  const [snapshot, djuke] = await Promise.all([readCampaigns(), djukeState || readDjukeState()]);
  if (snapshot.chainId !== 8453 || snapshot.paused || !Array.isArray(snapshot.campaigns) || !Array.isArray(djuke.requests)) return 0;
  const time = now();
  let applied = 0;
  for (const request of djuke.requests) {
    if (!isAddress(request.payer) || BigInt(request.amountUnits || 0) <= 0n || !/^\d+$/.test(String(request.chainRequestId))) continue;
    const campaigns = snapshot.campaigns.filter(campaign => campaign.advertiser.toLowerCase() === request.payer.toLowerCase() &&
      !campaign.removed && Date.parse(campaign.startedAt) <= time && time < Date.parse(campaign.expiresAt));
    if (campaigns.length !== 1) {
      if (campaigns.length > 1) log.warn(`[devert] DJuke request ${request.chainRequestId} has multiple active campaigns for its payer; choose a campaign before boosting.`);
      continue;
    }
    const campaignId = BigInt(campaigns[0].campaignId);
    const requestId = BigInt(request.chainRequestId);
    const requestKey = requestId.toString();
    if (inFlightRequests.has(requestKey)) continue;
    inFlightRequests.add(requestKey);
    try {
      if (await contract.usedDjukeRequests(requestId)) continue;
      await contract.applyDJukeBoost.staticCall(campaignId, requestId);
      const transaction = await contract.applyDJukeBoost(campaignId, requestId);

      if ((await transaction.wait(2))?.status !== 1) throw new Error(`DeVert DJuke boost failed: ${transaction.hash}`);
      applied++;
      log.log(`[devert] Applied DJuke request ${request.chainRequestId} as a priority boost for campaign ${campaigns[0].campaignId}.`);
    } finally {
      inFlightRequests.delete(requestKey);
    }
  }
  return applied;
}

function asSafeNumber(value, label) {
  const number = Number(value);
  if (!Number.isSafeInteger(number) || number < 0) throw new Error(`Invalid DeVert ${label}`);
  return number;
}

function normalizeCampaign(campaignId, raw, weekId) {
  if (!raw || typeof raw !== 'object' || !isAddress(raw.advertiser) || ZERO_ADDRESS.test(raw.advertiser) ||
    typeof raw.title !== 'string' || !raw.title.trim() || raw.title.length > 160 ||
    typeof raw.audioURI !== 'string' || !raw.audioURI.startsWith('ipfs://')) {
    throw new Error('Invalid DeVert campaign');
  }
  const startedAt = asSafeNumber(raw.startedAt, 'campaign start');
  const expiresAt = asSafeNumber(raw.expiresAt, 'campaign expiry');
  const recordWeek = asSafeNumber(raw.weekId, 'campaign week');
  if (expiresAt <= startedAt || expiresAt - startedAt > SECONDS_PER_WEEK ||
    recordWeek > weekId || weekId - recordWeek > 1) {
    throw new Error('Invalid DeVert campaign terms');
  }
  const offerUnits = BigInt(raw.offerUnits);
  const paidUnits = BigInt(raw.paidUnits);
  if (offerUnits < 1_000_000n || paidUnits < 1_000_000n) throw new Error('Invalid DeVert campaign payment');
  return {
    campaignId: BigInt(campaignId).toString(),
    advertiser: raw.advertiser,
    title: raw.title,
    audioURI: raw.audioURI,
    startedAt: new Date(startedAt * 1000).toISOString(),
    expiresAt: new Date(expiresAt * 1000).toISOString(),
    weekId: recordWeek,

    offerUnits: offerUnits.toString(),
    paidUnits: paidUnits.toString(),
    djukeBoosts: asSafeNumber(raw.djukeBoosts, 'DJuke boost count'),
    mainRadioPlays: asSafeNumber(raw.mainRadioPlays, 'main-radio play count'),
    devertPlays: asSafeNumber(raw.devertPlays, 'DeVert play count'),
  };
}

function normalizeMarket(raw) {
  if (!raw || typeof raw !== 'object') throw new Error('Invalid DeVert market snapshot');
  const slots = asSafeNumber(raw.slots, 'market slot count');
  const seated = asSafeNumber(raw.seated, 'seated campaign count');
  const lowest = BigInt(raw.lowestSeatedOfferUnits);
  const mainRadioImpressions = asSafeNumber(raw.mainRadioImpressions ?? 0, 'main-radio impression count');
  if (seated > slots || mainRadioImpressions > slots || (seated > 0 && lowest < 1_000_000n)) {
    throw new Error('Invalid DeVert market snapshot');
  }
  return { slots, seated, lowestSeatedOfferUnits: lowest.toString(), mainRadioImpressions };
}

export function createDevertCampaignReader({ contractAddress, provider, contract, rpcUrl, confirmations = 2, version = '0.1' }) {
  if (!['0.1', '0.2'].includes(version)) throw new Error('Unsupported DeVert contract version');
  if (!isAddress(contractAddress) || ZERO_ADDRESS.test(contractAddress)) throw new Error('Invalid DeVert contract address');
  if (!Number.isSafeInteger(confirmations) || confirmations < 2) throw new Error('DeVert reads need at least two confirmations');
  const rpc = provider || new JsonRpcProvider(rpcUrl);
  const devert = contract || new Contract(contractAddress, DEVERT_ABI, rpc);
  let task = null;

  async function readSnapshot() {
    if (Number((await rpc.getNetwork()).chainId) !== 8453) throw new Error('DeVert is Base-only');

const blockNumber = await rpc.getBlockNumber() - confirmations + 1;
if (!Number.isSafeInteger(blockNumber) || blockNumber < 0) throw new Error('DeVert confirmation block unavailable');
const before = await rpc.getBlock(blockNumber);
if (!before?.hash) throw new Error('DeVert confirmation block unavailable');
const timestamp = asSafeNumber(before.timestamp, 'snapshot timestamp');
const options = { blockTag: blockNumber };
let workerFunding;
if (version === '0.2') {
  if (await devert.CONTRACT_VERSION(options) !== version) throw new Error('DeVert contract version mismatch');
  const worker = await readWorkerGasState({ provider: rpc, workerAddress: await devert.schedulerWallet(options),
    minBalanceWei: SPONSORED_WORKER_MIN_BALANCE_WEI });
  workerFunding = { address: worker.workerAddress, balanceWei: worker.balanceWei.toString(),
    minimumWei: worker.thresholdWei.toString(), available: !worker.lowBalance,
    reason: worker.lowBalance ? 'Campaign checkout is paused until the platform replenishes its worker ETH.' : '' };
}
const weekId = asSafeNumber(await devert.campaignWeek(timestamp, options), 'week ID');
const [ids, marketRaw, paused] = await Promise.all([
  devert.getWeekCampaignIds(weekId, options),
  devert.mainRadioMarket(weekId, options),
  devert.paused(options),
]);
if (!Array.isArray(ids) || ids.length > MAX_WEEKLY_CAMPAIGNS) throw new Error('Invalid or oversized DeVert campaign list');
const uniqueIds = new Set(ids.map(id => BigInt(id).toString()));
if (uniqueIds.size !== ids.length) throw new Error('Duplicate DeVert campaign ID');
const campaigns = [];
for (let offset = 0; offset < ids.length; offset += READ_CONCURRENCY) {

      const batch = await Promise.all(ids.slice(offset, offset + READ_CONCURRENCY).map(async id =>
        normalizeCampaign(id, await devert.getCampaign(id, options), weekId)));
      campaigns.push(...batch);
    }
    const market = normalizeMarket(marketRaw);
    if ((await rpc.getBlock(blockNumber))?.hash !== before.hash) throw new Error('DeVert snapshot is not canonical');
    return {
      chainId: 8453,
      version,
      ...(workerFunding ? { workerFunding } : {}),
      contractAddress,
      blockNumber,
      blockHash: before.hash,
      snapshotAt: new Date(timestamp * 1000).toISOString(),
      weekId,
      paused,
      campaigns,
      market,
    };
  }

  return () => {
    task ||= readSnapshot().finally(() => { task = null; });
    return task;
  };
}

import { Events } from 'discord.js';

const WINDOW_MS = 10 * 60_000;
const MAX_EVENTS = 30;
const MAX_RESTRICTIONS = 10;
const SNAPSHOT_INTERVAL_MS = 5 * 60_000;
const MAX_OBSERVATIONS = 6;
const BOTS = ['dbusker', 'devert-loop'];
const ROUTE_PARTS = new Set([
  'gateway', 'bot', 'channels', 'messages', 'reactions', 'users', '@me',
  'guilds', 'members', 'roles', 'applications', 'commands', 'permissions',
  'interactions', 'callback', 'webhooks', 'original', 'bulk-delete',
]);

export function discordRoute(value) {
  return '/' + String(value || '').split('?')[0].split('/').filter(Boolean).slice(0, 10)
    .map(part => ROUTE_PARTS.has(part) ? part : ':id').join('/');
}

function number(value) {
  if (value === null || value === undefined || value === '') return null;
  const parsed = Number(value);
  return Number.isFinite(parsed) && parsed >= 0 ? parsed : null;
}

function trafficObservation(value) {
  if (!value) return null;
  return {
    at: number(value.at), startedAt: number(value.startedAt),
    bots: Object.fromEntries(BOTS.filter(name => value.bots?.[name]).map(name => {
      const bot = value.bots[name];
      return [name, {
        totals: Object.fromEntries(['requests', 'errors', 'invalid', 'rateLimits']
          .map(key => [key, number(bot.totals?.[key])])),
        invalidLast10Minutes: number(bot.invalidLast10Minutes),
        traffic: bot.traffic ? Object.fromEntries([
          'requestsLastSecond', 'requestsLastMinute', 'requestsLast10Minutes',
          'peakRequestsPerSecond', 'peakRequestsPerMinute',
        ].map(key => [key, number(bot.traffic[key])])) : null,
        routes: Array.isArray(bot.routes) ? bot.routes.slice(-64).map(route => ({

          method: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE'].includes(route.method) ? route.method : 'OTHER',
          route: discordRoute(route.route), status: number(route.status),
          count: number(route.count), retries: number(route.retries),
        })) : [],
      }];
    })),
  };
}

function restriction(value) {
  if (!value) return null;
  return {
    at: number(value.at), route: discordRoute(value.route),
    method: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE'].includes(value.method) ? value.method : 'OTHER',
    status: 429, retryAt: number(value.retryAt),
    scope: ['user', 'global', 'shared'].includes(value.scope) ? value.scope : 'unknown',
    global: value.global === true,
    responseFormat: ['json', 'html', 'text'].includes(value.responseFormat) ? value.responseFormat : 'other',
    edgeRequestId: /^[a-f0-9]{16,32}-[A-Z]{3}$/.test(value.edgeRequestId || '') ? value.edgeRequestId : null,
    bucket: /^[a-f0-9]{8,64}$/.test(value.bucket || '') ? value.bucket : null,
    remaining: number(value.remaining), limit: number(value.limit), resetAfterMs: number(value.resetAfterMs),
    observation: trafficObservation(value.observation),
  };
}

export function discordRetryAt(headers, now = Date.now()) {
  const retry = headers.get('retry-after');
  const seconds = number(retry);
  const date = retry && seconds === null ? Date.parse(retry) : NaN;
  const reset = number(headers.get('x-ratelimit-reset-after'));
  return Math.max(seconds === null ? 0 : now + Math.ceil(seconds * 1000),
    Number.isFinite(date) ? date : 0, reset === null ? 0 : now + Math.ceil(reset * 1000));
}

export function discordFailure(error) {
  const code = String(error?.code || '');
  return {

    code: /^\d{3,6}$/.test(code) || /^(TokenInvalid|DisallowedIntents|InvalidIntents|SessionInvalidated|ECONNRESET|ETIMEDOUT|ENOTFOUND|EAI_AGAIN|UND_ERR_CONNECT_TIMEOUT)$/.test(code) ? code : 'unknown',
    status: number(error?.status),
  };
}

export function createDiscordDiagnostics({ store, now = Date.now, log = console } = {}) {
  const bots = new Map();
  const startedAt = now();
  let restored = false;
  let restoreTask;
  let saveTask = Promise.resolve();
  let loginTask = Promise.resolve();
  let persistence = store ? 'restoring' : 'not-configured';
  let networkCooldownUntil = 0;
  let lastSummary = '';
  let observations = [];
  let lastSnapshotAt = -Infinity;
  let trafficChanged = false;
  const get = name => {
    if (!BOTS.includes(name)) throw new Error('Unknown Discord diagnostic client');
    if (!bots.has(name)) bots.set(name, {
      phase: 'idle', retryAt: null, cooldownUntil: 0, failures: 0,
      totals: { requests: 0, errors: 0, invalid: 0, rateLimits: 0 },
      invalidSeconds: new Map(), routes: new Map(), recent: [], lastRestriction: null, restrictions: [],
      requestSeconds: new Map(), peakRequestsPerSecond: 0, peakRequestsPerMinute: 0,
    });
    return bots.get(name);
  };
  const event = (name, value) => {
    const bot = get(name);
    bot.recent.push({ at: now(), ...value });
    if (bot.recent.length > MAX_EVENTS) bot.recent.shift();
  };
  const prune = bot => {
    const oldest = Math.floor((now() - WINDOW_MS) / 1000);
    for (const second of bot.invalidSeconds.keys()) if (second <= oldest) bot.invalidSeconds.delete(second);
    for (const second of bot.requestSeconds.keys()) if (second <= oldest) bot.requestSeconds.delete(second);
  };
  const traffic = bot => {
    prune(bot);
    const second = Math.floor(now() / 1000);

  let minute = 0;
  let tenMinutes = 0;
  for (const [at, count] of bot.requestSeconds) {
    tenMinutes += count;
    if (at > second - 60) minute += count;
  }
  return { requestsLastSecond: bot.requestSeconds.get(second) || 0,
    requestsLastMinute: minute, requestsLast10Minutes: tenMinutes,
    peakRequestsPerSecond: bot.peakRequestsPerSecond, peakRequestsPerMinute: bot.peakRequestsPerMinute };
};
const observation = () => trafficObservation({
  at: now(), startedAt, bots: Object.fromEntries([...bots].map(([name, bot]) => {
    const currentTraffic = traffic(bot);
    return [name, { totals: bot.totals, traffic: currentTraffic,
      invalidLast10Minutes: [...bot.invalidSeconds.values()].reduce((sum, count) => sum + count, 0),
      routes: [...bot.routes.values()] }];
  })),
});
const persist = () => {
  if (!store) return;
  const value = { schemaVersion: 1, networkCooldownUntil, observations: observations.slice(),
    bots: Object.fromEntries([...bots].map(([name, bot]) => [name, {
      cooldownUntil: bot.cooldownUntil, lastRestriction: bot.lastRestriction,
      restrictions: bot.restrictions.slice(),
    }])) };
  saveTask = saveTask.catch(() => {}).then(async () => {
    try {
      const uri = await store.save(value);
      if (typeof uri !== 'string' || !uri.startsWith('ipfs://')) throw new Error('Discord cooldown checkpoint was not durable');
      persistence = 'saved';
    } catch (error) {
      persistence = 'failed';
      log.error('[discord] Cooldown checkpoint failed; current process still honors the deadline.');
      throw error;
    }
  });
  // The response event cannot await storage; flush() exposes failure to callers.
  void saveTask.catch(() => {});
};

const report = () => ({
  startedAt, windowMs: WINDOW_MS, windowResolutionMs: 1000, persistence, networkCooldownUntil,
  observations: observations.map(trafficObservation),
  bots: Object.fromEntries([...bots].map(([name, bot]) => {
    prune(bot);
    return [name, {
      phase: bot.phase, retryAt: bot.retryAt, cooldownUntil: bot.cooldownUntil,
      failures: bot.failures, totals: { ...bot.totals },
      traffic: traffic(bot),
      invalidLast10Minutes: [...bot.invalidSeconds.values()].reduce((sum, count) => sum + count, 0),
      lastRestriction: restriction(bot.lastRestriction),
      restrictions: bot.restrictions.map(restriction),
      routes: [...bot.routes.values()].map(({ lastLogAt, ...route }) => ({ ...route })),
      recent: bot.recent.map(entry => ({ ...entry })),
    }];
  })),
});
return {
  report,
  withLogin(connect) {
    const task = loginTask.then(connect);
    loginTask = task.catch(() => {});
    return task;
  },
  maintenance() {
    if (restored && trafficChanged && now() - lastSnapshotAt >= SNAPSHOT_INTERVAL_MS) {
      observations.push(observation());
      if (observations.length > MAX_OBSERVATIONS) observations.shift();
      lastSnapshotAt = now();
      trafficChanged = false;
      persist();
    } else if (persistence === 'failed') persist();
    const summary = Object.fromEntries([...bots].map(([name, bot]) => {
      prune(bot);
      const invalid = [...bot.invalidSeconds.values()].reduce((sum, count) => sum + count, 0);
      return [name, { phase: bot.phase, totals: { ...bot.totals }, invalidLast10Minutes: invalid,
        invalidRequestWarning: invalid >= 100, retryAt: bot.retryAt, cooldownUntil: bot.cooldownUntil,

      lastRestriction: restriction(bot.lastRestriction), traffic: traffic(bot),
      routes: [...bot.routes.values()].map(({ lastLogAt, ...route }) => ({ ...route })) }];
  }));
  const text = JSON.stringify({ persistence, bots: summary });
  if (text !== lastSummary) {
    log.log(`[discord] Diagnostic summary ${text}`);
    lastSummary = text;
  }
},
async restore() {
  if (restored) return;
  if (!restoreTask) restoreTask = (async () => {
    try {
      const value = await store?.restore();
      if (value) {
        if (value.schemaVersion !== 1 || !Number.isSafeInteger(value.networkCooldownUntil) ||
            value.networkCooldownUntil < 0 || !value.bots || typeof value.bots !== 'object') {
          throw new Error('Invalid Discord cooldown checkpoint');
        }
        networkCooldownUntil = Math.max(networkCooldownUntil, value.networkCooldownUntil);
        if (value.observations !== undefined && !Array.isArray(value.observations)) {
          throw new Error('Invalid Discord traffic observations');
        }
        observations = (value.observations || []).filter(Boolean).slice(-MAX_OBSERVATIONS).map(trafficObservation);
        for (const name of BOTS) {
          if (!value.bots[name]) continue;
          const deadline = value.bots[name].cooldownUntil;
          if (!Number.isSafeInteger(deadline) || deadline < 0) throw new Error('Invalid Discord cooldown deadline');
          get(name).cooldownUntil = Math.max(get(name).cooldownUntil, deadline);
          get(name).lastRestriction = restriction(value.bots[name].lastRestriction);
          const history = value.bots[name].restrictions;

          if (history !== undefined && !Array.isArray(history)) throw new Error('Invalid Discord restriction history');
          get(name).restrictions = (history || [value.bots[name].lastRestriction])
            .filter(Boolean).slice(-MAX_RESTRICTIONS).map(restriction);
        }
      }
      restored = true;
      persistence = store ? 'restored' : 'not-configured';
    } catch (error) {
      persistence = 'restore-failed';
      log.error('[discord] Cooldown restore failed; Discord login remains paused, website playback continues.');
      restoreTask = null;
      throw error;
    }
  })();
  return restoreTask;
},
flush: () => saveTask,
bot(name) {
  const bot = get(name);
  return {
    notBefore: () => Math.max(networkCooldownUntil, bot.cooldownUntil),
    setState(phase, { retryAt = null, failure } = {}) {
      if (!['idle', 'restoring', 'cooldown', 'connecting', 'ready', 'disconnected', 'backoff', 'blocked', 'stopped'].includes(phase)) {
        throw new Error('Invalid Discord connection phase');
      }
      bot.phase = phase;
      bot.retryAt = retryAt;
      if (failure) bot.failures++;
      event(name, { type: phase, ...(failure ? discordFailure(failure) : {}), retryAt });
    },
    attach(client) {
      const response = (request, result) => {
        // discord.js emits a cloned response; retain metadata, not an unread body.
        if (typeof result.body?.cancel === 'function') {
          void result.body.cancel().catch(() => log.warn(`[discord:${name}] Diagnostic response copy could not be released.`));
        }
        const status = number(result.status);

const route = discordRoute(request.route || request.path);
const method = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE'].includes(String(request.method).toUpperCase())
  ? String(request.method).toUpperCase() : 'OTHER';
const rawScope = result.headers.get('x-ratelimit-scope');
const scope = ['user', 'global', 'shared'].includes(rawScope) ? rawScope : 'unknown';
const global = result.headers.get('x-ratelimit-global') === 'true' || scope === 'global';
const retryAt = status === 429 ? discordRetryAt(result.headers, now()) : 0;
bot.totals.requests++;
if (status >= 400) bot.totals.errors++;
if (status === 429) bot.totals.rateLimits++;
const invalid = status === 401 || status === 403 || (status === 429 && scope !== 'shared');
const second = Math.floor(now() / 1000);
prune(bot);
bot.requestSeconds.set(second, (bot.requestSeconds.get(second) || 0) + 1);
bot.peakRequestsPerSecond = Math.max(bot.peakRequestsPerSecond, bot.requestSeconds.get(second));
bot.peakRequestsPerMinute = Math.max(bot.peakRequestsPerMinute, traffic(bot).requestsLastMinute);
trafficChanged = true;
if (invalid) {
  bot.totals.invalid++;
  bot.invalidSeconds.set(second, (bot.invalidSeconds.get(second) || 0) + 1);
}
const key = `${method} ${route} ${status}`;
if (!bot.routes.has(key) && bot.routes.size >= 64) bot.routes.delete(bot.routes.keys().next().value);
const entry = bot.routes.get(key) || { method, route, status, count: 0, retries: 0, lastLogAt: -Infinity };
entry.count++;

if (number(request.retries) > 0) entry.retries++;
bot.routes.set(key, entry);
if (status < 400) return;
const metadata = { type: 'http-error', method, route, status, scope, global, retryAt: retryAt || null,
  responseFormat: result.headers.get('content-type')?.includes('application/json') ? 'json'
    : result.headers.get('content-type')?.includes('text/html') ? 'html'
      : result.headers.get('content-type')?.includes('text/plain') ? 'text' : 'other',
  edgeRequestId: /^[a-f0-9]{16,32}-[A-Z]{3}$/.test(result.headers.get('cf-ray') || '')
    ? result.headers.get('cf-ray') : null,
