    result = await Promise.race([pending, new Promise(resolve => { timer = setTimeout(() => resolve(timedOut), timeoutMs); })]);
  } catch (error) {
    pendingClaim = null;
    throw error;
  } finally {
    clearTimeout(timer);
  }
