async function fetchLogs(fromBlock, toBlock) {
  if (typeof provider.getLogs === 'function') {
    return provider.getLogs({ address: routerAddress, topics: [[FUNDED_TOPIC, PAID_TOPIC]], fromBlock, toBlock });
  }
