if (!Number.isInteger(size) || size < 1 || size > MAX_UPLOAD_BYTES) throw new Error('Invalid upload size');

      if (!['application/json', 'video/mp4'].includes(type) && !type.startsWith('audio/') && !type.startsWith('image/')) {
