  if (b.mode === 'phase0' && !hashPattern.test(command.reportHash || '')) throw new Error('Pinned report content hash required for Phase 0 payout metadata');
  b.reportHash = command.reportHash || '';
  b.remainderDisposition = required(command.remainderDisposition, 'Remainder disposition');
  b.decision = { payoutBps: bps, ...(liveMusicMinutes === null ? {} : { liveMusicMinutes }), at: new Date(now()).toISOString() };
  b.approvedUnits = (BigInt(b.amountUnits) * BigInt(bps) / 10000n).toString();
  b.remainderUnits = (BigInt(b.amountUnits) - BigInt(b.approvedUnits)).toString();
  b.financialStatus = b.mode === 'phase0' ? 'Decision recorded; router payment/recovery requires separate confirmed transaction' : 'Decision proposal; escrow approval/refund not yet confirmed';
} else if (action === 'cancel') {
  if (command.confirm !== true) throw new Error('Explicit cancellation confirmation required');
  if (b.status === 'paid' || b.status === 'refunded') throw new Error('Cannot cancel a settled booking');
  b.cancelled = true;
  b.cancellationReason = required(command.reason, 'Public cancellation reason');
  const late = now() >= Date.parse(b.startUtc) - b.cancellationWindow * 1000;
  b.cancellationFeeUnits = late ? (BigInt(b.amountUnits) * BigInt(b.killFeeBps) / 10000n).toString() : '0';

        b.financialStatus = b.status === 'draft' ? 'No confirmed deposit; verify any pending wallet transaction' : 'Pending separate financial reconciliation; schedule cancellation does not move funds';
        if (now() >= Date.parse(b.startUtc)) b.financialStatus += '; show started: escrow pre-show cancel unavailable, review/reject after end';
      } else if (action !== 'schedule') throw new Error('Unknown booking action');
    }
    if (action === 'schedule' || action === 'cancel') await syncSchedule(next, b);
    else await commit(next);
    return publicState();
  });
}
async function acknowledgePerformer({ id: bookingId, address, signature }) {
  return run(async () => {
    await initialize();
    const next = clone(state);
    const b = next.bookings.find(item => item.id === bookingId);
    if (!b) throw new Error('Unknown booking');
    if (b.status !== 'draft' || b.cancelled) throw new Error('This booking invitation is no longer open');
    if (now() >= Date.parse(b.startUtc)) throw new Error('This invitation has expired; ask the steward for a new booking and agreement');
    if (lower(address) !== b.wallet) throw new Error('Connect the invited performer wallet');
    if (b.acknowledgements) {
      if (lower(verifyMessage(liveAcknowledgement(b), signature)) === b.wallet) return publicState();
      throw new Error('This booking has already been acknowledged');
    }
    if (!b.stewardApproved) throw new Error('The steward has not approved these exact terms yet');
    const performerSignature = required(signature, 'Performer acknowledgement signature', 1000);
    if (lower(verifyMessage(liveAcknowledgement(b), performerSignature)) !== b.wallet) {
      throw new Error('Performer acknowledgement mismatch');

      }
      b.acknowledgements = { performerSignature, performer: b.wallet, at: new Date(now()).toISOString() };
      b.termsStatus = 'Performer accepted steward-approved terms; awaiting escrow funding';
      await commit(next);
      return publicState();
    });
  }
  function publicState() {
    return { ...clone(state), ready: true, escrowAddress, escrowConfigured: !!escrowAddress, notice: 'Earmarked, NOT escrowed. Phase 0 admin can recoverFund.',
      bookings: state.bookings.map(({ acknowledgements, discordHandle, ...b }) => ({ ...clone(b),
        acknowledged: !!acknowledgements, acknowledgedAt: acknowledgements?.at || null })) };
  }
  async function getState() { return run(async () => { await initialize(); await indexEscrow(); return publicState(); }); }
  return { execute, getState, acknowledgePerformer };
}

import { CID } from 'multiformats/cid';
export const DISCORD_UPLOAD_MAX_BYTES = 10 * 1024 * 1024;

export function isDiscordAttachmentWithinLimit(attachment) {
  return Number.isInteger(attachment.size) && attachment.size > 0 && attachment.size <= DISCORD_UPLOAD_MAX_BYTES;
}

export const MEDIA_TYPES = {
  mp3: 'audio/mpeg', m4a: 'audio/mp4', wav: 'audio/wav', ogg: 'audio/ogg',
  flac: 'audio/flac', aac: 'audio/aac', opus: 'audio/ogg', weba: 'audio/webm', mp4: 'video/mp4',
};

export function mediaTypeFor(filename = '', declaredType = '') {
  const extension = String(filename || '').split('.').pop().toLowerCase();
  return MEDIA_TYPES[extension] || (Object.values(MEDIA_TYPES).includes(declaredType) ? declaredType : '');
}

export function normalizeMediaCid(value) {
  const text = String(value || '').trim().replace(/^ipfs:\/\//i, '');
  try {
    return CID.parse(text).toV1().toString();
  } catch {
    throw new Error('Enter a valid file CID or ipfs://CID, without a directory path or gateway URL');
  }
}

export function buildSubmissionAuthorizationMessage(payload) {
  const { address, origin, issuedAt, title, artist, ipfsCid, mediaType, filename,
    recipient, artworkCid = '', tipWallet = '', parentTokenId = 0, isDevertAd = false, creatorSplits } = payload;
  return [
    'DecentBusking media submission for owner approval',
    `Wallet: ${address.toLowerCase()}`,
    `Origin: ${origin}`,
    `Issued At: ${issuedAt}`,
    JSON.stringify({ title, artist, ipfsCid, mediaType, filename, recipient, artworkCid, tipWallet, parentTokenId, isDevertAd,
      ...(creatorSplits !== undefined ? { creatorSplits } : {}) }),
  ].join('\n');
}

import { ModalBuilder, TextInputBuilder, TextInputStyle, LabelBuilder, FileUploadBuilder, MessageFlags, EmbedBuilder } from 'discord.js';
import { mintRequestKey } from './embed.js';
import { normalizeMediaCid } from './media.js';

const BUTTON_PREFIX = 'mint-request:';
const MODAL_PREFIX = 'mint-wallet:';
const WALLET_PATTERN = /^0x[0-9a-fA-F]{40}$/;
const IMAGE_EXTENSIONS = /\.(png|jpe?g|webp|gif)$/i;
const IMAGE_TYPES = ['image/png', 'image/jpeg', 'image/webp', 'image/gif'];

export function previousArtistWallet(tracks, uploaderId) {
  const wallets = new Map();
  for (const track of tracks) {
    if (track.uploaderId === uploaderId && WALLET_PATTERN.test(track.mintRecipient || '')) {
      wallets.set(track.mintRecipient.toLowerCase(), track.mintRecipient);
    }
  }
  return wallets.size === 1 ? [...wallets.values()][0] : '';
}

export async function ensureDefaultMintArtwork({ requests, getUser, getDefaultArtwork, requestTrackMint, waitForPersistence }) {
  let changed = false;
  const result = [];
  for (const track of requests) {
    if (track.artworkCid || !/^\d{16,22}$/.test(track.uploaderId || '')) { result.push(track); continue; }
    const user = await getUser(track.uploaderId);
    const cid = user ? await getDefaultArtwork(user) : null;
    const updated = cid ? requestTrackMint(track.trackId, track.uploaderId, track.mintRecipient, cid) : null;
    result.push(updated || track);
    if (updated) changed = true;
  }
  if (changed) await waitForPersistence();
  return result;
}

export function createMintRequestInteractionHandler({ getPlaylist, requestTrackMint, waitForPersistence,
  getDefaultArtwork, uploadArtwork }) {
  return async interaction => {
    const button = interaction.isButton?.() && interaction.customId?.startsWith(BUTTON_PREFIX);

const modal = interaction.isModalSubmit?.() && interaction.customId?.startsWith(MODAL_PREFIX);
if (!button && !modal) return false;
const key = interaction.customId.slice((button ? BUTTON_PREFIX : MODAL_PREFIX).length);
const tracks = getPlaylist();
const track = tracks.find(entry => mintRequestKey(entry.trackId) === key);
if (!track || track.uploaderId !== interaction.user.id) {
  await interaction.reply({ content: 'Only the original uploader can request this NFT.', flags: MessageFlags.Ephemeral });
  return true;
}
if (track.pinStatus !== 'pinned' || !track.ipfsCid || track.mintStatus === 'minted') {
  await interaction.reply({ content: 'This track is not ready for a mint request, or has already been minted.', flags: MessageFlags.Ephemeral });
  return true;
}
if (button) {
  const wallet = new TextInputBuilder().setCustomId('artist-wallet').setStyle(TextInputStyle.Short)
    .setRequired(true).setMinLength(42).setMaxLength(42).setPlaceholder('0x...');
  const previous = track.mintRecipient || previousArtistWallet(tracks, interaction.user.id);
  if (WALLET_PATTERN.test(previous)) wallet.setValue(previous);
  const walletLabel = new LabelBuilder().setLabel('Base artist wallet').setTextInputComponent(wallet);
  const artworkLabel = new LabelBuilder().setLabel('NFT artwork (optional, up to 10 MB)')
    .setDescription(track.artworkCid ? 'Keep existing artwork, or use the CID field for images over 10 MB.' : 'Default: Discord profile image. For images over 10 MB, use the artwork CID field.')
    .setFileUploadComponent(new FileUploadBuilder().setCustomId('nft-artwork').setMinValues(0).setMaxValues(1).setRequired(false));

  const artworkCidLabel = new LabelBuilder().setLabel('Artwork file CID (optional)')
    .setDescription('Use an already-uploaded image file CID instead of attaching an image.')
    .setTextInputComponent(new TextInputBuilder().setCustomId('artwork-cid').setStyle(TextInputStyle.Short)
      .setRequired(false).setMaxLength(160).setPlaceholder('bafy... or ipfs://...'));
  await interaction.showModal(new ModalBuilder().setCustomId(`${MODAL_PREFIX}${key}`)
    .setTitle('Request NFT').addLabelComponents(walletLabel, artworkLabel, artworkCidLabel));
  return true;
}
const wallet = interaction.fields.getTextInputValue('artist-wallet').trim();
const artwork = interaction.fields.getUploadedFiles('nft-artwork')?.first();
const rawArtworkCid = interaction.fields.getTextInputValue('artwork-cid').trim();
if (!WALLET_PATTERN.test(wallet)) {
  await interaction.reply({ content: 'Enter a valid 0x Base wallet address, then click Request NFT again.', flags: MessageFlags.Ephemeral });
  return true;
}
if (artwork && rawArtworkCid) {
  await interaction.reply({ content: 'Choose one artwork source: attach an image up to 10 MB, or enter its IPFS file CID.', flags: MessageFlags.Ephemeral });
  return true;
}
let suppliedArtworkCid;
if (rawArtworkCid) {
  try {
    suppliedArtworkCid = normalizeMediaCid(rawArtworkCid);
  } catch {
    await interaction.reply({ content: 'Enter a valid artwork file CID or ipfs://CID, without a directory path or gateway URL.', flags: MessageFlags.Ephemeral });
    return true;
  }
}
if (artwork && (!Number.isInteger(artwork.size) || artwork.size < 1 || artwork.size > 10 * 1024 * 1024 ||

        !(IMAGE_TYPES.includes(artwork.contentType) || IMAGE_EXTENSIONS.test(artwork.name || '')))) {
      await interaction.reply({ content: 'Artwork attachments must be PNG, JPEG, WebP, or GIF, up to 10 MB. For larger images, use the artwork file CID field.', flags: MessageFlags.Ephemeral });
      return true;
    }
    await interaction.deferReply({ flags: MessageFlags.Ephemeral });
    try {
      const artworkCid = suppliedArtworkCid || (artwork ? await uploadArtwork(artwork)
        : track.artworkCid || await getDefaultArtwork(interaction.user));
      if (!artworkCid) throw new Error('Could not archive your profile image; retry or upload an artwork image');
      const queued = requestTrackMint(track.trackId, interaction.user.id, wallet, artworkCid);
      if (!queued) throw new Error('The track changed or was minted while the request was being submitted');
      await waitForPersistence();
      await interaction.editReply({ content: `Requested owner approval for **${queued.title}**.\n` +
        `Artist and royalty wallet: \`${wallet}\`\n` +
        `Artwork: ${suppliedArtworkCid ? 'your IPFS image' : artwork ? 'your uploaded image' : track.artworkCid ? 'existing image' : 'your Discord profile image'}.\nNo NFT has been minted yet.`,
      embeds: [new EmbedBuilder().setTitle('Selected NFT artwork').setImage(`https://gateway.pinata.cloud/ipfs/${artworkCid}`)],
      allowedMentions: { parse: [] } });
    } catch (error) {
      await interaction.editReply({ content: `Could not submit the mint request: ${error.message}`, allowedMentions: { parse: [] } });
    }
    return true;
  };
}

#!/usr/bin/env node
// Owner-only CLI that mints the pending JukeLoop queue from this machine.
// Mirrors the Admin panel: same metadata, registerToken + mintProduct, and the
// same /api/mint-complete report so the live bot announces each NFT.
//
//   node mint-queue.js            dry run: list what would be minted
//   node mint-queue.js --mint     mint every pending request
//   node mint-queue.js --mint --limit 5
//
// Requires MINT_OWNER_PRIVATE_KEY in the local discord-bot/.env (never on Render).

import 'dotenv/config';
import { Contract, JsonRpcProvider, Wallet } from 'ethers';
import { loadConfig } from './config.js';
import { uploadToIPFS } from './ipfs.js';
import { buildAdminAuthorizationMessage } from './ipfs-worker.js';
import { readMintedCollections, audioCidFromMetadata, discoverPinataMetadataGateway, withRetry } from './mint-sync.js';
import { mediaTypeFor } from './media.js';

const NFT_ABI = [
  'function DEFAULT_ADMIN_ROLE() view returns (bytes32)',
  'function hasRole(bytes32 role, address account) view returns (bool)',
  'function nextTokenId() view returns (uint256)',
  'function totalMinted(uint256 tokenId) view returns (uint256)',
  'function uri(uint256 tokenId) view returns (string)',
  'function registerToken(uint256 maxSupply_, string calldata tokenURI_, uint8 kind_, address royaltyReceiver, uint96 royaltyFeeBps) external returns (uint256 tokenId)',
  'function mintProduct(address to, uint256 tokenId, uint256 amount) external',
  'event TokenRegistered(uint256 indexed tokenId, address indexed creator, uint256 maxSupply, uint8 kind, string uri)',
];
const ROYALTY_BPS = 500;

export function buildTrackMetadata(track, registeredBy, now = new Date()) {
  return {
    name: track.title,

    description: `Shared through DecentJukebox by ${track.uploader}`,
    animation_url: `ipfs://${track.ipfsCid}`,
    audioUrl: `ipfs://${track.ipfsCid}`,
    ...(mediaTypeFor(track.filename, track.mediaType) ? { mediaType: mediaTypeFor(track.filename, track.mediaType) } : {}),
    ...(mediaTypeFor(track.filename, track.mediaType) === 'video/mp4' ? { videoUrl: `ipfs://${track.ipfsCid}` } : {}),
    ...(track.artworkCid ? { image: `ipfs://${track.artworkCid}` } : {}),
    artist: track.recipient,
    creator: track.recipient,
    tipWallet: track.tipWallet || track.recipient,
    ...(track.parentTokenId > 0 ? { parentTokenId: track.parentTokenId, royaltyChain: { parentTokenId: track.parentTokenId } } : {}),
    registeredBy,
    mintedAt: now.toISOString(),
  };
}

function slugify(value) {
  return value.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'track';
}

export async function validateResumeToken({ contract, tokenId, track, owner, fetchImpl = fetch, retry = {} }) {
  const read = async (method) => {
    try {
      return await withRetry(() => contract[method](tokenId), retry);
    } catch (error) {
      const detail = error.info?.error?.message || error.shortMessage || error.message;
      throw new Error(`Resume token #${tokenId}: ${method} lookup failed after retries: ${detail}. No mint was sent.`);
    }
  };
  if (Number(await read('totalMinted')) !== 0) throw new Error('Resume token is already minted');
  const uri = await read('uri');
  const response = await fetchImpl(uri.replace('ipfs://', 'https://gateway.pinata.cloud/ipfs/'));
  if (!response.ok) throw new Error('Could not verify resume token metadata');
  const metadata = await response.json();
  if (audioCidFromMetadata(metadata) !== track.ipfsCid ||

      metadata.artist?.toLowerCase() !== track.recipient.toLowerCase() ||
      metadata.registeredBy?.toLowerCase() !== owner.toLowerCase()) {
    throw new Error('Resume token does not match this queued track, recipient, and owner');
  }
}

export async function estimateRegisteredMint({ contract, recipient, tokenId, blockNumber, delayMs = 1000 }) {
  for (let attempt = 0; ; attempt++) {
    try {
      return await contract.mintProduct.estimateGas(recipient, tokenId, 1, { blockTag: blockNumber });
    } catch (error) {
      if (attempt >= 4 || !/token not registered|rate limit|header not found|unknown block/i.test(
        `${error.shortMessage || ''} ${error.message || ''} ${error.info?.error?.message || ''}`,
      )) throw error;
      await new Promise((resolve) => setTimeout(resolve, delayMs * (attempt + 1)));
    }
  }
}

async function postJson(url, body, origin) {
  const response = await fetch(url, {
    method: 'POST',
    headers: { 'content-type': 'application/json', origin },
    body: JSON.stringify(body),
  });
  const result = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(result.error || `${url} failed (${response.status})`);
  return result;
}

async function main() {
  const args = process.argv.slice(2);
  const shouldMint = args.includes('--mint');
  const limitArg = args.indexOf('--limit');
  const limit = limitArg >= 0 ? Number(args[limitArg + 1]) : Infinity;
  const resumeArg = args.indexOf('--resume-token');
  const resumeToken = resumeArg >= 0 ? args[resumeArg + 1] : null;
  if (resumeArg >= 0 && !/^\d+$/.test(resumeToken || '')) throw new Error('--resume-token requires a token ID');

  const privateKey = process.env.MINT_OWNER_PRIVATE_KEY;

if (!privateKey) throw new Error('Set MINT_OWNER_PRIVATE_KEY in discord-bot/.env (local only).');
const config = loadConfig();
const origin = config.allowedOrigins?.[0];
const serviceUrl = (config.publicWorkerUrl || '').replace(/\/$/, '');
if (!origin || !serviceUrl) throw new Error('IPFS_ALLOWED_ORIGINS and PUBLIC_WORKER_URL must be set.');

const provider = new JsonRpcProvider(config.baseRpcUrl);
const wallet = new Wallet(privateKey, provider);
if (wallet.address.toLowerCase() !== config.mintOwnerWallet.toLowerCase()) {
  throw new Error(`The key's address ${wallet.address} is not MINT_OWNER_WALLET.`);
}
const contract = new Contract(config.nftContractAddress, NFT_ABI, wallet);
if (!(await contract.hasRole(await contract.DEFAULT_ADMIN_ROLE(), wallet.address))) {
  throw new Error(`${wallet.address} does not hold DEFAULT_ADMIN_ROLE on DecentNFT.`);
}

const issuedAt = new Date().toISOString();
const signature = await wallet.signMessage(buildAdminAuthorizationMessage({ address: wallet.address, origin, issuedAt }));
const { requests = [] } = await postJson(`${serviceUrl}/api/mint-queue`, { address: wallet.address, signature, issuedAt }, origin);

console.log('Checking Base for audio that is already minted…');
const dedicatedGateway = config.pinataJwt ? await discoverPinataMetadataGateway({ pinataJwt: config.pinataJwt }).catch(() => null) : null;
const metadataGateways = dedicatedGateway ? [dedicatedGateway] : undefined;
const { minted: alreadyMinted } = await readMintedCollections({
  collections: config.nftContractAddresses.map(contractAddress => ({ contractAddress,
    contract: new Contract(contractAddress, NFT_ABI, provider) })),
  metadataGateways,
});

const duplicates = requests.filter((track) => alreadyMinted.has(track.ipfsCid));
const pending = requests.filter((track) => !alreadyMinted.has(track.ipfsCid)).slice(0, limit);

console.log(`Queue: ${requests.length} request(s) · ${duplicates.length} already minted (skipped) · ${pending.length} to mint`);
for (const track of duplicates) console.log(`  skip  ${track.title} — already token #${alreadyMinted.get(track.ipfsCid)}`);
for (const track of pending) console.log(`  mint  ${track.title} → ${track.recipient}`);
const balance = await provider.getBalance(wallet.address);
console.log(`Owner ETH balance on Base: ${Number(balance) / 1e18}`);
if (!shouldMint) {
  console.log('\nDry run only. Re-run with --mint to send transactions.');
  return;
}

let minted = 0;
for (const [index, track] of pending.entries()) {
  const label = `[${index + 1}/${pending.length}] ${track.title}`;
  let tokenId;
  let registrationBlock;
  if (index === 0 && resumeToken !== null) {
    await validateResumeToken({ contract, tokenId: resumeToken, track, owner: wallet.address });
    tokenId = resumeToken;
    registrationBlock = await provider.getBlockNumber();
    console.log(`${label}: reusing registered token #${tokenId}`);
  } else {
  const metadata = buildTrackMetadata(track, wallet.address);
  const metadataUri = await uploadToIPFS(
    Buffer.from(JSON.stringify(metadata, null, 2)),
    `${slugify(track.title)}.json`,
    'application/json',
    { provider: 'pinata', pinataJwt: config.pinataJwt, pinataApiUrl: config.pinataApiUrl },
  );

  const registration = await (await contract.registerToken(0, metadataUri, 0, track.recipient, ROYALTY_BPS)).wait();
  const registered = registration.logs

      .map((log) => { try { return contract.interface.parseLog(log); } catch { return null; } })
      .find((event) => event?.name === 'TokenRegistered');
    if (!registered) throw new Error(`${label}: could not read the registered token ID`);
    tokenId = registered.args.tokenId.toString();
    registrationBlock = registration.blockNumber;
    console.log(`${label}: registered token #${tokenId} in block ${registrationBlock}`);
    }

    let mintReceipt;
    try {
      const estimate = await estimateRegisteredMint({ contract, recipient: track.recipient, tokenId, blockNumber: registrationBlock });
      mintReceipt = await (await contract.mintProduct(track.recipient, tokenId, 1, {
        gasLimit: estimate * 120n / 100n,
      })).wait();
    } catch (error) {
      throw new Error(`${label}: token #${tokenId} is registered; mint failed: ${error.shortMessage || error.message}. ` +
        `Do not register it again. Resume with --mint --resume-token ${tokenId} --limit 1.`);
    }
    minted++;
    try {
      await postJson(`${serviceUrl}/api/mint-complete`, { trackId: track.trackId, tokenId, txHash: mintReceipt.hash }, origin);
      console.log(`✅ ${label} → token #${tokenId} (announced)`);
    } catch (err) {
      console.warn(`⚠️ ${label} → token #${tokenId} minted, but sync failed: ${err.message}`);
      console.warn(`   /jukeloop mark-minted track_id:${track.trackId} token_id:${tokenId} tx_hash:${mintReceipt.hash}`);
    }
  }
  console.log(`\nDone — minted ${minted} of ${pending.length}.`);
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main().catch((err) => {
    console.error(`❌ ${err.shortMessage || err.message}`);
    process.exit(1);
  });
}

// Recovers which playlist tracks are already DecentNFT editions by reading Base,
// the source of truth when bot state is lost (e.g. a Render restart).

import { Contract, JsonRpcProvider, Interface, isAddress, id } from 'ethers';
import { CID } from 'multiformats/cid';
import * as playlistStore from './playlist-store.js';
import { mediaTypeFor } from './media.js';

const NFT_ABI = [
  'function nextTokenId() view returns (uint256)',
  'function totalMinted(uint256 tokenId) view returns (uint256)',
  'function uri(uint256 tokenId) view returns (string)',
];
const METADATA_GATEWAYS = [
  'https://ipfs.orbitor.dev/ipfs/',
  'https://gateway.pinata.cloud/ipfs/',
  'https://ipfs.io/ipfs/',
];
const cacheEvents = new Interface([
  'event URI(string value,uint256 indexed id)',
  'event TransferSingle(address indexed operator,address indexed from,address indexed to,uint256 id,uint256 value)',
  'event TransferBatch(address indexed operator,address indexed from,address indexed to,uint256[] ids,uint256[] values)',
]);

export async function invalidateMintCache({ cache, provider, contractAddress }) {
  const blockNumber = await provider.getBlockNumber() - 1;
  const block = await provider.getBlock(blockNumber);
  if (!block?.hash) throw new Error('NFT cache confirmation block unavailable');
  if (cache.blockNumber === undefined || blockNumber < cache.blockNumber ||
      (await provider.getBlock(cache.blockNumber))?.hash !== cache.blockHash) {
    cache.tokens.clear();
  } else {
    for (let fromBlock = cache.blockNumber + 1; fromBlock <= blockNumber; fromBlock += 1000) {
      const logs = await provider.getLogs({ address: contractAddress, fromBlock,
        toBlock: Math.min(fromBlock + 999, blockNumber),

        topics: [[id('URI(string,uint256)'), id('TransferSingle(address,address,address,uint256,uint256)'),
          id('TransferBatch(address,address,address,uint256[],uint256[])')]] });
      for (const log of logs) {
        const event = cacheEvents.parseLog(log);
        if (event.name === 'URI' && event.args.id === (2n ** 256n - 1n)) cache.tokens.clear();
        else for (const tokenId of event.name === 'TransferBatch' ? event.args.ids : [event.args.id]) cache.tokens.delete(Number(tokenId));
      }
    }
  }
  return { blockNumber, blockHash: block.hash };
}

// The public Base RPC answers bursts with "over rate limit", so retry with backoff.
export async function withRetry(call, { attempts = 5, baseDelayMs = 1_000 } = {}) {
  for (let attempt = 1; ; attempt++) {
    try {
      return await call();
    } catch (err) {
      if (attempt >= attempts) throw err;
      await new Promise((resolve) => setTimeout(resolve, baseDelayMs * 2 ** (attempt - 1)));
    }
  }
}

export function audioCidFromMetadata(metadata = {}) {
  const uri = metadata.animation_url || metadata.audioUrl || '';
  const path = uri.match(/^ipfs:\/\/(?:ipfs\/)?([^?#]+)/)?.[1] ?? uri.match(/\/ipfs\/([^?#]+)/)?.[1];
  if (!path) return null;
  const [root, ...segments] = path.split('/');
  let normalized = root;
  try { normalized = CID.parse(root).toV1().toString(); } catch {}
  return [normalized, ...segments].join('/');
}

export function resolveDevertCampaignMedia(campaign, cid, { playlist = [], nfts = [] } = {}) {
  const advertiser = campaign.advertiser.toLowerCase();
  const track = playlist.find(entry => entry.isDevertAd && entry.ipfsCid === cid &&
    entry.mintRecipient?.toLowerCase() === advertiser);
  const metadata = nfts.find(entry =>

    (entry.artist || entry.creator)?.toLowerCase() === advertiser &&
    audioCidFromMetadata({ audioUrl: entry.videoUrl || entry.audioUrl || entry.animation_url }) === cid);
  if (!metadata) return track || null;
  const videoUrl = metadata.videoUrl || track?.videoUrl || '';
  const filename = metadata.filename || track?.filename || '';
  const mediaType = videoUrl ? 'video/mp4' : metadata.mediaType || mediaTypeFor(filename, track?.mediaType);
  return { ...track, filename, mediaType,
    videoUrl: videoUrl || (mediaType === 'video/mp4' ? `ipfs://${cid}` : '') };
}

function isDevertAdvertMetadata(metadata) {
  return metadata.isDevertAd === true || /^DecentAdvert(?:isement)?(?:\b|[0-9_-])/i.test(String(metadata.name || ''));
}

export function resolveApprovedDevertCampaignMedia(campaign, cid, { playlist = [], nfts = [] } = {}) {
  return resolveDevertCampaignMedia(campaign, cid, { playlist, nfts: nfts.filter(isDevertAdvertMetadata) });
}

export async function readOwnedDevertAds({ collections, address, fetchImpl = fetch, retry = {}, pauseMs = 0,
  ownershipConcurrency = 32, metadataConcurrency = 8, ownershipReader, metadataReader = fetchMintMetadata,
  onProgress, log = console } = {}) {
  if (!Array.isArray(collections) || !/^0x[0-9a-fA-F]{40}$/.test(address || '')) throw new Error('DeVert ad recovery requires collections and a wallet');
  if (!Number.isSafeInteger(ownershipConcurrency) || ownershipConcurrency < 1 ||
      !Number.isSafeInteger(metadataConcurrency) || metadataConcurrency < 1) throw new Error('Invalid ownership scan concurrency');
  const ads = new Map();
  let metadataUnavailable = 0;
  let ownershipUnavailable = 0;
  for (const collection of collections) {

const nextTokenId = Number(await withRetry(() => collection.contract.nextTokenId(), retry));
if (!Number.isSafeInteger(nextTokenId) || nextTokenId < 0 || nextTokenId > 100_000) throw new Error('Invalid NFT token range');
for (let endTokenId = nextTokenId - 1; endTokenId >= 0; endTokenId -= ownershipConcurrency) {
  if (pauseMs && endTokenId < nextTokenId - 1) await new Promise(resolve => setTimeout(resolve, pauseMs));
  const tokenIds = Array.from({ length: Math.min(ownershipConcurrency, endTokenId + 1) }, (_, offset) => endTokenId - offset);
  let balances;
  try {
    balances = ownershipReader
      ? await ownershipReader(collection, address, tokenIds)
      : await Promise.all(tokenIds.map(async tokenId => {
        try { return { balance: await withRetry(() => collection.contract.balanceOf(address, tokenId), retry) }; }
        catch (error) { return { error }; }
      }));
    if (!Array.isArray(balances) || balances.length !== tokenIds.length) throw new Error('Invalid ownership batch response');
  } catch (error) {
    balances = tokenIds.map(() => ({ error }));
  }
  const ownedTokenIds = [];
  for (let index = 0; index < tokenIds.length; index++) {
    const tokenId = tokenIds[index];
    const ownership = balances[index];
    if (ownership.error) {
      ownershipUnavailable++;
      continue;
    }
    if (BigInt(ownership.balance) === 0n) continue;
    ownedTokenIds.push(tokenId);
  }
  for (let index = 0; index < ownedTokenIds.length; index += metadataConcurrency) {
    await Promise.all(ownedTokenIds.slice(index, index + metadataConcurrency).map(async tokenId => {
      try {

          const uri = await withRetry(() => collection.contract.uri(tokenId), retry);
          const metadata = await metadataReader(uri, fetchImpl, { attempts: 1 });
          const isAd = isDevertAdvertMetadata(metadata);
          if (!isAd) return;
          const mediaUri = metadata.videoUrl || metadata.audioUrl || metadata.animation_url || '';
          const ipfsCid = audioCidFromMetadata({ ...metadata, audioUrl: mediaUri });
          if (!ipfsCid) return;
          const mediaType = metadata.mediaType || (metadata.videoUrl ? 'video/mp4' : '');
          const artworkUri = String(metadata.image || metadata.imageUrl || metadata.thumbnailUrl || '');
          ads.set(`${collection.contractAddress.toLowerCase()}:${tokenId}`, {
            trackId: `nft:${collection.contractAddress.toLowerCase()}:${tokenId}`,
            title: String(metadata.name || `DeVert ad #${tokenId}`), ipfsCid,
            image: artworkUri,
            artworkCid: artworkUri,
            mediaType,
            videoUrl: metadata.videoUrl || (mediaType === 'video/mp4' ? mediaUri : ''),
            filename: String(metadata.filename || ''), mintStatus: 'minted', tokenId: String(tokenId),
            state: 'ready', campaignId: null, expiresAt: null, secondsRemaining: 0,
          });
        } catch (error) {
          metadataUnavailable++;
          log.warn(`[mint-sync] Ad metadata unavailable for owned token ${tokenId}: ${error.message}`);
        }
      }));
    }
    onProgress?.({ ads: [...ads.values()], metadataUnavailable, ownershipUnavailable });
  }
  if (ownershipUnavailable) log.warn(`[mint-sync] ${ownershipUnavailable} ad library ownership check(s) failed; results may be incomplete.`);
}

  return { ads: [...ads.values()], metadataUnavailable, ownershipUnavailable };
}

export async function discoverPinataMetadataGateway({ pinataJwt, fetchImpl = fetch,
  apiUrl = 'https://api.pinata.cloud/v3/gateways' } = {}) {
  if (!pinataJwt) throw new Error('PINATA_JWT is required to discover the dedicated metadata gateway');
  const response = await fetchImpl(`${apiUrl}?pageSize=1`, {
    headers: { Authorization: `Bearer ${pinataJwt}` },
    signal: AbortSignal.timeout(15_000),
  });
  if (!response.ok) throw new Error(`Pinata gateway discovery failed (${response.status})`);
  const body = await response.json();
  const row = body?.data?.rows?.[0];
  let domain = row?.domain;
  if (typeof domain !== 'string' || !/^[a-z0-9.-]+$/i.test(domain)) {
    throw new Error('Pinata gateway discovery returned no valid domain');
  }
  if (!domain.includes('.')) domain = `${domain}.mypinata.cloud`;

  let tokenParam = '';
  if (row?.id) {
    try {
      const detailsUrl = `${apiUrl.replace(/\/?$/, '')}/${row.id}`;
      const detailsResp = await fetchImpl(detailsUrl, {
        headers: { Authorization: `Bearer ${pinataJwt}` },
        signal: AbortSignal.timeout(15_000),
      });
      if (detailsResp.ok) {
        const detailsBody = await detailsResp.json();
        const accessTokens = detailsBody?.data?.settings?.restriction_policies?.accessTokens;
        if (Array.isArray(accessTokens) && accessTokens[0]?.value) {
          tokenParam = `?pinataGatewayToken=${encodeURIComponent(accessTokens[0].value)}`;
        }
      }
    } catch {
      // Best-effort gateway token discovery
    }
  }

  return `https://${domain}/ipfs/${tokenParam}`;
}

export function buildGatewayUrl(gateway, cidPath) {
  try {
    const url = new URL(gateway);

    const cleanPath = url.pathname.replace(/\/?$/, '/') + cidPath.replace(/^\/?/, '');
    url.pathname = cleanPath;
    return url.toString();
  } catch {
    return `${gateway.replace(/\/?$/, '/')}${cidPath.replace(/^\/?/, '')}`;
  }
}

export async function fetchMintMetadata(uri, fetchImpl, { attempts = 3, baseDelayMs = 1_000,
  gateways = METADATA_GATEWAYS, wait = delay => new Promise(resolve => setTimeout(resolve, delay)) } = {}) {
  const cidPath = uri.startsWith('ipfs://') ? uri.replace(/^ipfs:\/\/(ipfs\/)?/, '')
    : /^https?:\/\//.test(uri) ? new URL(uri).pathname.split('/ipfs/')[1] : null;
  const urls = [...new Set([
    ...(/^https?:\/\//.test(uri) ? [uri] : []),
    ...(cidPath ? gateways.map(gateway => buildGatewayUrl(gateway, cidPath)) : []),
  ])];
  const failures = new Map();
  for (let attempt = 0; attempt < attempts; attempt++) {
    let transient = false;
    for (const url of urls) {
      const response = await fetchImpl(url, { signal: AbortSignal.timeout(15_000) }).catch(() => null);
      if (response?.ok) {
        const metadata = await response.json().catch(() => null);
        if (metadata && typeof metadata === 'object' && !Array.isArray(metadata)) return metadata;
        failures.set(url, 'invalid JSON metadata');
      } else {
        failures.set(url, response?.status || 'timeout/network error');
        if (!response || response.status === 429 || response.status >= 500) transient = true;
      }
    }
      if (!transient || attempt === attempts - 1) break;
      await wait(baseDelayMs * 2 ** attempt);
  }

  throw new Error(`NFT metadata could not be verified through any IPFS gateway: ${uri}. ${[...failures].map(([url, status]) => `${new URL(url).hostname}: ${status}`).join('; ')}. Mint queue remains locked to prevent duplicate mints; retry after gateway recovery.`);
}

/** Map audio CID → lowest minted token ID for every minted DecentNFT token. */
function markMetadataChecked(metadata, checkedAt) {
  Object.defineProperty(metadata, '_metadataCheckedAt', {
    value: checkedAt,
    writable: true,
    configurable: true,
    enumerable: false,
  });
  return metadata;
}

export async function readMintedAudioCids({ contract, fetchImpl = fetch, retry = {}, pauseMs = 250, artistWalletByAudioCid,
  tokenCache = new Map(), nfts = [], metadataGateways, metadataCacheMs = 300_000, now = Date.now }) {
  const tokenIdByAudioCid = new Map();
  const nextTokenId = Number(await withRetry(() => contract.nextTokenId(), retry));
  if (!Number.isSafeInteger(nextTokenId) || nextTokenId < 0) throw new Error('Invalid NFT token count');
  const fresh = cached => cached && now() - (cached._metadataCheckedAt ?? -Infinity) < metadataCacheMs;
  const load = async tokenId => {
    let cached = tokenCache.get(tokenId);
    if (!fresh(cached)) {
      const [mintedSupply, uri] = await Promise.all([
        withRetry(() => contract.totalMinted(tokenId), retry).then(Number),
        withRetry(() => contract.uri(tokenId), retry),
      ]);
      if (mintedSupply === 0) {
        tokenCache.delete(tokenId);
        return null;
      }
      if (cached?.metadataUri === uri) {
        cached.mintedSupply = mintedSupply;
        markMetadataChecked(cached, now());
        return cached;
      }
      const metadata = await fetchMintMetadata(uri, fetchImpl,

        metadataGateways?.length ? { gateways: metadataGateways } : undefined);
      cached = { ...metadata, tokenId, contractAddress: contract.target || contract.address || '',
        chainId: 8453, metadataUri: uri, mintedSupply };
      markMetadataChecked(cached, now());
      tokenCache.set(tokenId, cached);
    }
    return cached;
  };
  for (let start = 0; start < nextTokenId; start += 3) {
    const ids = Array.from({ length: Math.min(3, nextTokenId - start) }, (_, index) => start + index);
    if (pauseMs && ids.some(tokenId => !fresh(tokenCache.get(tokenId)))) await new Promise(resolve => setTimeout(resolve, pauseMs));
    const results = await Promise.allSettled(ids.map(load));
    const failed = results.find(result => result.status === 'rejected');
    if (failed) throw failed.reason;
    for (const result of results) {
      const metadata = result.value;
      if (!metadata) continue;
      const contractAddress = contract.target || contract.address || '';
      nfts.push({ ...metadata, contractAddress: metadata.contractAddress || contractAddress, chainId: metadata.chainId || 8453 });
      const cid = audioCidFromMetadata(metadata);
      if (cid && !tokenIdByAudioCid.has(cid)) {
        tokenIdByAudioCid.set(cid, String(metadata.tokenId));
        if (typeof metadata.artist === 'string' && isAddress(metadata.artist)) artistWalletByAudioCid?.set(cid, metadata.artist);
      }
    }
  }
  return tokenIdByAudioCid;
}

/** Mark playlist tracks whose audio is already minted on Base. */
export async function readMintedCollections({ collections, fetchImpl = fetch, pauseMs, retry,
  tokenCaches = new Map(), nfts = [], metadataGateways, metadataCacheMs, now }) {

  if (!Array.isArray(collections) || !collections.length) throw new Error('NFT collections are required');
  const minted = new Map();
  const artistWalletByAudioCid = new Map();
  const tokenReferencesByAudioCid = new Map();
  const seen = new Set();
  for (const collection of collections) {
    const address = collection.contractAddress;
    if (!isAddress(address) || seen.has(address.toLowerCase())) throw new Error('Invalid or duplicate NFT collection');
    const cacheKey = address.toLowerCase();
    seen.add(cacheKey);
    let tokenCache = tokenCaches.get(cacheKey);
    if (!tokenCache) {
      tokenCache = new Map();
      tokenCaches.set(cacheKey, tokenCache);
    }
    const artists = new Map();
    const tokens = await readMintedAudioCids({ contract: collection.contract, fetchImpl, pauseMs, retry,
      artistWalletByAudioCid: artists, tokenCache, nfts, metadataGateways, metadataCacheMs, now });
    for (const [cid, tokenId] of tokens) {
      if (!minted.has(cid)) minted.set(cid, tokenId);
      if (!artistWalletByAudioCid.has(cid) && artists.has(cid)) artistWalletByAudioCid.set(cid, artists.get(cid));
      const references = tokenReferencesByAudioCid.get(cid) || [];
      references.push({ chainId: 8453, contractAddress: address, tokenId });
      tokenReferencesByAudioCid.set(cid, references);
    }
  }
  return { minted, artistWalletByAudioCid, tokenReferencesByAudioCid, nfts };
}

export async function syncMintedTracksFromChain({
  rpcUrl,
  provider: rpcProvider,
  contractAddress,
  contract,
  contractAddresses,
  collections,
  fetchImpl = fetch,
  store = playlistStore,
  log = console,
  pauseMs,
  tokenCaches = new Map(),
  metadataGateways,
  metadataCacheMs,
  now,
  onCatalog,
}) {
  let result;
  if (collections || contractAddresses?.length) {

    const provider = collections ? null : (rpcProvider || new JsonRpcProvider(rpcUrl));
    result = await readMintedCollections({ collections: collections || contractAddresses.map(address => ({
      contractAddress: address, contract: new Contract(address, NFT_ABI, provider),
    })), fetchImpl, pauseMs, tokenCaches, metadataGateways, metadataCacheMs, now });
  } else {
    const artistWalletByAudioCid = new Map();
    const minted = await readMintedAudioCids({
      contract: contract || new Contract(contractAddress, NFT_ABI, rpcProvider || new JsonRpcProvider(rpcUrl)),
      fetchImpl, pauseMs, artistWalletByAudioCid, metadataGateways, metadataCacheMs, now,
    });
    result = { minted, artistWalletByAudioCid, nfts: [] };
  }
  onCatalog?.(result.nfts || []);
  const changed = store.applyOnChainMints(result.minted, result);
  if (changed) log.log(`[mint-sync] Marked ${changed} track(s) minted from DecentNFT on Base.`);
  return changed;
}

export function createVerifiedMintQueueReader({ reconcile, getRequests }) {
  let pending = null;
  return async () => {
    if (!pending) pending = Promise.resolve().then(reconcile).finally(() => { pending = null; });
    await pending;
    return getRequests();
  };
}

import { Interface, id, parseUnits } from 'ethers';
import { createFailoverProvider } from './rpc-failover.js';

export const PAYMENT_EVENT_ABI = ['event PayrollPaid(bytes32 indexed fundId,address indexed asset,address indexed recipient,uint256 amount,bytes32 workReference,bytes32 repositoryIdHash,bytes32 contributorIdHash,string metadataUri,bytes32 metadataHash)'];
const iface = new Interface(PAYMENT_EVENT_ABI);
const repositoryHash = id('TheJollyLaMa/DecentBusking');

export async function verifyRepositoryPayment({ entry, config, txHash, provider = createFailoverProvider(config) }) {
  const currency = String(entry.currency || '').toUpperCase();
  const asset = config.assets[currency];
  if (!asset || currency === 'ETH') throw new Error('Only configured Base repository assets can settle');
  if (Number((await provider.getNetwork()).chainId) !== 8453) throw new Error('Repository proof is Base-only');
  const receipt = await provider.getTransactionReceipt(txHash);
  const head = await provider.getBlockNumber();
  if (!receipt || receipt.status !== 1 || head - receipt.blockNumber + 1 < 2) throw new Error('Repository payment needs two successful Base confirmations');
  if ((await provider.getBlock(receipt.blockNumber))?.hash !== receipt.blockHash) throw new Error('Repository payment is not canonical');
  const base = `${entry.issueRef}:${entry.contributorGithub}:${entry.role || 'contributor'}`;
  const workReference = id(currency === 'ART' ? base : `${base}:${currency}`);
  const matches = receipt.logs.filter(log => {
    if (log.address?.toLowerCase() !== config.routerAddress.toLowerCase()) return false;
    let event;
    try { event = iface.parseLog(log); } catch { return false; }
    const args = event?.args;

    return event?.name === 'PayrollPaid' && args.fundId === id(entry.fund || config.fundSlug) &&
      args.asset.toLowerCase() === asset.address.toLowerCase() && args.recipient.toLowerCase() === entry.contributor.toLowerCase() &&
      args.amount === parseUnits(String(entry.amount), asset.decimals) && args.workReference === workReference &&
      args.repositoryIdHash === id(entry.issueRef.split('#')[0]) && args.contributorIdHash === id(entry.contributorGithub.trim());
  });
  if (matches.length !== 1) throw new Error('No exact router payment proof for this repository ledger entry');
  return { txHash, workReference, blockNumber: receipt.blockNumber };
}

export function createPaymentLedger({ provider, routerAddress, restore = async () => null, save = async () => '', startBlock,
  confirmations = 2, now = () => Date.now(), onVerified = async () => {} }) {
  let entries = new Map();
  let scannedFrom = null;
  let scannedThrough = null;
  let snapshotUri = '';
  let backupPending = false;
  let lastCheckedAt = null;
  let lastError = '';
  let comparisonOffset = 0;
  let task = Promise.resolve();
  const pending = new Set();
  const address = routerAddress.toLowerCase();
  const run = operation => {
    const result = task.then(operation);
    task = result.catch(() => {});
    return result;
  };
  function snapshot() {
    return { schemaVersion: 1, chainId: 8453, routerAddress, scannedFrom, scannedThrough,
      lastCheckedAt, entries: [...entries.values()] };
  }
  async function initialize() {
    if (startBlock !== undefined && (!Number.isSafeInteger(startBlock) || startBlock < 0)) throw new Error('PAYROLL_START_BLOCK must be a nonnegative block number');

  if (Number((await provider.getNetwork()).chainId) !== 8453) throw new Error('Payment ledger is Base-only');
  const saved = await restore();
  if (saved) {
    if (saved.schemaVersion !== 1 || saved.chainId !== 8453 || saved.routerAddress?.toLowerCase() !== address || !Array.isArray(saved.entries)) throw new Error('Invalid payment ledger checkpoint');
    entries = new Map(saved.entries.map(entry => [entry.workReference, { ...entry, verification: 'restored-awaiting-comparison' }]));
    scannedFrom = saved.scannedFrom;
    scannedThrough = saved.scannedThrough;
    if (!Number.isSafeInteger(scannedFrom) || scannedFrom < 0 || !Number.isSafeInteger(scannedThrough) || scannedThrough < scannedFrom - 1) throw new Error('Invalid payment scan checkpoint');
    snapshotUri = saved.snapshotUri || '';
  }
  const head = await provider.getBlockNumber();
  if (scannedFrom === null) scannedFrom = Number.isSafeInteger(startBlock) && startBlock >= 0 ? startBlock : Math.max(0, head - 2000);
  if (scannedThrough === null) scannedThrough = scannedFrom - 1;
  return compare();
}
async function persist() {
  if (!backupPending) return;
  try {
    const nextUri = await save({ ...snapshot(), previousSnapshotUri: snapshotUri || null });
    if (!/^ipfs:\/\//.test(nextUri)) throw new Error('Payment backup did not return an IPFS URI');
    snapshotUri = nextUri;
    backupPending = false;
  } catch (error) { lastError = `IPFS backup pending: ${error.message}`; }
}
async function verifyTransaction(txHash, head) {
  if (!/^0x[0-9a-fA-F]{64}$/.test(txHash || '')) throw new Error('Invalid payment transaction hash');
  const receipt = await provider.getTransactionReceipt(txHash);

if (!receipt || receipt.status !== 1) throw new Error('Payment transaction is not successful and confirmed');
const relevantEvent = receipt.logs.some(log => {
  try { return log.address.toLowerCase() === address && iface.parseLog(log)?.args.repositoryIdHash === repositoryHash; } catch { return false; }
});
if (!relevantEvent) throw new Error('No DecentBusking PayrollPaid event from the configured router');
if (head - receipt.blockNumber + 1 < confirmations) { pending.add(txHash); return { pending: true, entries: [] }; }
const block = await provider.getBlock(receipt.blockNumber);
if (!block || block.hash !== receipt.blockHash) throw new Error('Payment receipt is not on the canonical Base chain');
const verified = [];
for (const log of receipt.logs) {
  if (log.address?.toLowerCase() !== address) continue;
  let event;
  try { event = iface.parseLog(log); } catch { continue; }
  if (event?.name !== 'PayrollPaid' || event.args.repositoryIdHash !== repositoryHash) continue;
  const values = event.args;
  const entry = { chainId: 8453, routerAddress, txHash: receipt.hash || txHash, blockNumber: receipt.blockNumber,
    blockHash: receipt.blockHash, logIndex: log.index ?? log.logIndex, fundId: values.fundId,
    asset: values.asset, recipient: values.recipient, amountUnits: values.amount.toString(), workReference: values.workReference,
    repositoryIdHash: values.repositoryIdHash, contributorIdHash: values.contributorIdHash,
    metadataUri: values.metadataUri, metadataHash: values.metadataHash, verification: 'verified',
    paidAt: new Date(Number(block.timestamp) * 1000).toISOString() };
  if (JSON.stringify(entries.get(entry.workReference)) !== JSON.stringify(entry)) {

      entries.set(entry.workReference, entry);
      backupPending = true;
    }
    verified.push(entry);
    await onVerified(entry);
  }
  if (!verified.length) throw new Error('No DecentBusking PayrollPaid event from the configured router');
  pending.delete(txHash);
  return { pending: false, entries: verified };
}
async function reconcile(txHash) {
  return run(async () => {
    const result = await verifyTransaction(txHash, await provider.getBlockNumber());
    lastCheckedAt = new Date(now()).toISOString();
    await persist();
    return { ...result, snapshotUri, backupPending };
  });
}
async function compare() {
  return run(async () => {
    try {
      lastError = '';
      const head = await provider.getBlockNumber();
      const end = Math.min(head - confirmations + 1, scannedThrough + 1000);
      if (end >= scannedFrom && end > scannedThrough) {
        const from = Math.max(scannedFrom, scannedThrough - 12);
        const logs = await provider.getLogs({ address: routerAddress, topics: [iface.getEvent('PayrollPaid').topicHash], fromBlock: from, toBlock: end });
        for (const txHash of new Set(logs.map(log => log.transactionHash))) {
          const receipt = await provider.getTransactionReceipt(txHash);
          const relevant = receipt?.logs.some(log => {
            try { return log.address.toLowerCase() === address && iface.parseLog(log)?.args.repositoryIdHash === repositoryHash; } catch { return false; }
          });
          if (relevant) await verifyTransaction(txHash, head);
        }
        scannedThrough = end;
        if (logs.length) backupPending = true;
      }
      const records = [...entries.values()];

        const checking = Array.from({ length: Math.min(20, records.length) }, (_, offset) => records[(comparisonOffset + offset) % records.length]);
        comparisonOffset = records.length ? (comparisonOffset + checking.length) % records.length : 0;
        for (const entry of checking) {
          const block = await provider.getBlock(entry.blockNumber);
          if (!block || block.hash !== entry.blockHash) { entry.verification = 'chain-mismatch'; backupPending = true; continue; }
          try {
            const proof = await verifyTransaction(entry.txHash, head);
            if (!proof.entries.some(value => value.workReference === entry.workReference)) {
              entry.verification = 'proof-mismatch';
              entries.set(entry.workReference, entry);
              backupPending = true;
            }
          } catch (error) {
            if (/not successful|No DecentBusking|not on the canonical/.test(error.message)) {
              entry.verification = 'proof-mismatch'; entries.set(entry.workReference, entry); backupPending = true;
            } else throw error;
          }
        }
        for (const hash of pending) await verifyTransaction(hash, head);
        lastCheckedAt = new Date(now()).toISOString();
        await persist();
      } catch (error) { lastError = error.message; throw error; }
      return getState();
    });
  }
  function getState() { return { ...snapshot(), snapshotUri, backupPending, pendingTransactions: [...pending], lastError }; }
  return { initialize, reconcile, compare, getState };
}

import { previewRadioPlaylist, radioPlaylistDefinition, playlistTrackReason } from '../js/radio-playlists.mjs';

export function validatePlaylistShowSnapshot(value) {
  if (value?.schemaVersion !== 1 || !Array.isArray(value.occurrences) || value.occurrences.length > 100) throw new Error('Invalid playlist-show checkpoint');
  const ids = new Set();
  for (const state of value.occurrences) {
    radioPlaylistDefinition(state.playlistId, state.playlistDefinition);
    if (typeof state.instanceId !== 'string' || !state.instanceId || ids.has(state.instanceId) ||
      !Number.isFinite(Date.parse(state.capturedAt)) || !Number.isFinite(Date.parse(state.startAt)) ||
      !(Date.parse(state.endAt) > Date.parse(state.startAt)) ||
      !Array.isArray(state.tracks) || state.tracks.length > 10000 || state.tracks.some(track => !track?.trackId || typeof track.trackId !== 'string') ||
      new Set(state.tracks.map(track => track.trackId)).size !== state.tracks.length ||
      !Number.isSafeInteger(state.cursor) || state.cursor < 0 || state.cursor > state.tracks.length ||
      !Array.isArray(state.skipped) || state.skipped.some(item => !state.tracks.some(track => track.trackId === item.trackId) || typeof item.reason !== 'string')) {
      throw new Error('Invalid playlist-show occurrence');
    }
    ids.add(state.instanceId);
  }
  return structuredClone(value);
}

export function createPlaylistShow({ store, now = () => Date.now(), random = Math.random } = {}) {
  let snapshot = { schemaVersion: 1, occurrences: [] };
  let initialized = false;
  let pending = null;
  let pendingShuffled = false;
  let error = '';
  let task = Promise.resolve();
  const exclusive = operation => {
    const result = task.then(operation, operation);

  task = result.catch(failure => { error = failure.message; });
  return result;
};
const find = id => snapshot.occurrences.find(item => item.instanceId === id);
async function save(next) {
  if (!store) throw new Error('Durable playlist-show storage unavailable; normal rotation continues');
  const valid = validatePlaylistShowSnapshot(next);
  const uri = await store.save(valid);
  if (!/^ipfs:\/\//.test(uri || '')) throw new Error('Playlist-show checkpoint unconfirmed; normal rotation continues');
  snapshot = valid;
  error = '';
}
const api = {
  ensure(show, catalog) {
    return exclusive(async () => {
      if (find(show.instanceId)) {
        if (error) await save(snapshot);
        return;
      }
      if (pending?.instanceId !== show.instanceId) {
        const preview = previewRadioPlaylist(show.playlistId, catalog, { definition: show.playlistDefinition, now: now() });
        const tracks = [...preview.tracks];
        pendingShuffled = false;
        pending = { instanceId: show.instanceId, playlistId: show.playlistId, playlistRevision: preview.revision, capturedAt: new Date(now()).toISOString(),
          ...(show.playlistDefinition ? { playlistDefinition: show.playlistDefinition } : {}),
          shuffle: !preview.ranking || preview.ranking === 'shuffle',
          startAt: show.startAt, endAt: show.endAt, tracks, cursor: 0, skipped: [], unknownCount: preview.unknownCount };
      }
      if (!initialized) {
        const restored = store ? await store.restore() : null;
        if (restored) snapshot = validatePlaylistShowSnapshot(restored);
        initialized = true;
      }
      if (find(show.instanceId)) {
        pending = null;
        if (error) await save(snapshot);

      return;
    }
    if (!pendingShuffled && pending.shuffle !== false) {
      for (let index = pending.tracks.length - 1; index > 0; index--) {
        const swap = Math.floor(random() * (index + 1));
        [pending.tracks[index], pending.tracks[swap]] = [pending.tracks[swap], pending.tracks[index]];
      }
      pendingShuffled = true;
    }
    await save({ schemaVersion: 1, occurrences: [...snapshot.occurrences.slice(-99), pending] });
    pending = null;
  });
},
async next(show, catalog) {
  await api.ensure(show, catalog);
  let state = find(show.instanceId);
  while (state.cursor < state.tracks.length) {
    const entry = state.tracks[state.cursor];
    const track = catalog.find(item => item.trackId === entry.trackId);
    const selection = { ...entry, instanceId: state.instanceId, cursor: state.cursor, totalTracks: state.tracks.length,
      playlistId: state.playlistId, playlistDefinition: state.playlistDefinition, capturedAt: state.capturedAt,
      title: show.label, track };
    const reason = playlistTrackReason(track, radioPlaylistDefinition(state.playlistId, state.playlistDefinition), Date.parse(state.capturedAt));
    if (!reason) return selection;
    await api.advance(selection, reason);
    state = find(show.instanceId);
  }
  return null;
},
advance(selection, reason = null) {
  return exclusive(async () => {
    const state = find(selection.instanceId);
    if (!state || state.cursor !== selection.cursor) throw new Error('Playlist-show position changed');
    const next = { ...state, cursor: state.cursor + 1,
      ...(reason ? { skipped: [...state.skipped, { trackId: selection.trackId, reason }] }

            : { lastStarted: { trackId: selection.trackId, at: new Date(now()).toISOString() } }) };
        await save({ ...snapshot, occurrences: snapshot.occurrences.map(item => item === state ? next : item) });
      });
    },
    recordSkip(selection, reason) {
      return exclusive(async () => {
        const state = find(selection.instanceId);
        if (!state) throw new Error('Playlist-show occurrence missing');
        await save({ ...snapshot, occurrences: snapshot.occurrences.map(item => item !== state ? item :
          { ...state, skipped: [...state.skipped, { trackId: selection.trackId, reason }] }) });
      });
    },
    publicState(show) {
      if (show.type !== 'playlist_show') return null;
      const state = find(show.instanceId);
      const fallbackReason = error || (!state ? 'Preparing opening snapshot' : !state.tracks.length ? 'Empty eligible pool' :
        state.cursor >= state.tracks.length ? 'Eligible pool exhausted' : null);
      return { ...(state ? structuredClone(state) : { instanceId: show.instanceId, tracks: [] }),
        lateSnapshot: state ? Date.parse(state.capturedAt) - Date.parse(state.startAt) > 15_000 : false,
        status: fallbackReason ? 'normal_rotation' : 'ready', fallbackReason,
        invitation: radioPlaylistDefinition(show.playlistId, show.playlistDefinition).invitation };
    },
  };
  return api;
}

// discord-bot/playlist-store.js
// Persistent playlist store for JukeLoop.
//
// Tracks are sourced from the #DecentJukebox text channel. Each entry stores
// the Discord message ID and channel ID so that the attachment URL can always
// be re-fetched (Discord CDN URLs carry expiring tokens).
//
// Ratings accumulate from 👍 / 👎 reactions collected after each play and are
// used to compute a weight for the weighted-random shuffle so popular tracks
// play more often.

import { readFileSync, writeFileSync, existsSync } from 'fs';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';
import { randomUUID } from 'node:crypto';
import { isEligibleRadioMusic } from '../js/radio-playlists.mjs';
import { currentPayrollPeriod, payrollPeriodFromKey, payrollPeriods } from '../js/payroll-week.mjs';

const __dirname = dirname(fileURLToPath(import.meta.url));
const STORE_PATH = process.env.JUKELOOP_PLAYLIST_PATH || join(__dirname, 'jukeloop-playlist.json');
const MIN_WEEKLY_PLAY_MS = 30_000;
const NEW_TRACK_WINDOW_MS = 7 * 24 * 60 * 60 * 1000;

export function getUtcWeekKey(date = new Date()) {
  const day = new Date(date);
  day.setUTCHours(0, 0, 0, 0);
  day.setUTCDate(day.getUTCDate() + 4 - (day.getUTCDay() || 7));
  const year = day.getUTCFullYear();
  const yearStart = new Date(Date.UTC(year, 0, 1));
  const week = Math.ceil((((day - yearStart) / 86400000) + 1) / 7);
  return `${year}-W${String(week).padStart(2, '0')}`;
}

/**
 * @typedef {Object} TrackEntry
 * @property {string} trackId    - Stable playlist identity (Discord attachment ID when available)
 * @property {string} messageId  - Discord message ID of the original upload
 * @property {string} [attachmentId] - Discord attachment ID

// ── Persistence ───────────────────────────────────────────────────────────────

function _normalizePlaylist(playlist) {
  return playlist.map((track) => ({
    ...track,
    trackId: track.trackId || getTrackId(track),
    pinStatus: track.pinStatus || (track.ipfsCid ? 'pinned' : 'untracked'),
    mintStatus: track.mintStatus || 'unminted',
    payrollTrackingStartedAt: track.payrollTrackingStartedAt || new Date().toISOString(),
  }));
}

/** Load the playlist from a restored snapshot or the local runtime cache. */
export function loadPlaylist(restoredPlaylist = null) {
  _pendingHistoryEvents = [];
  if (Array.isArray(restoredPlaylist)) {
    _playlist = _normalizePlaylist(restoredPlaylist);
    console.log(`[playlist-store] Restored ${_playlist.length} track(s) from IPFS`);
    try {
      writeFileSync(STORE_PATH, JSON.stringify(_playlist, null, 2), 'utf8');
    } catch (err) {
      console.warn('[playlist-store] Could not refresh local playlist cache:', err.message);
    }
  } else if (existsSync(STORE_PATH)) {
    try {
      const raw = readFileSync(STORE_PATH, 'utf8');
      _playlist = _normalizePlaylist(JSON.parse(raw));
      console.log(`[playlist-store] Loaded ${_playlist.length} track(s) from ${STORE_PATH}`);
    } catch (err) {
      console.error('[playlist-store] Failed to parse playlist file, starting empty:', err.message);
      _playlist = [];
    }
  } else {
    _playlist = [];
  }
  return _playlist;
}

/** Configure the durable snapshot writer used after every mutation. */
export function configureRemotePersistence(saveSnapshot, { schedule, flush } = {}) {
  _remoteSaver = saveSnapshot;

  _remoteScheduler = schedule;
  _remoteFlusher = flush;
  _remoteSaveQueue = Promise.resolve();
}

/** Wait until all queued remote snapshots have completed. */
export function waitForRemotePersistence() {
  return _remoteSaveQueue.then(() => _remoteFlusher?.());
}

function _save({ routine = false, events = [] } = {}) {
  events = [..._pendingHistoryEvents, ...events];
  _pendingHistoryEvents = [];
  for (const track of _playlist) track.payrollTrackingStartedAt ||= new Date().toISOString();
  try {
    writeFileSync(STORE_PATH, JSON.stringify(_playlist, null, 2), 'utf8');
  } catch (err) {
    console.error('[playlist-store] Failed to save playlist:', err.message);
  }
  if (_remoteSaver) {
    const snapshot = structuredClone(_playlist);
    _remoteSaveQueue = _remoteSaveQueue.catch(() => {})
      .then(() => routine && _remoteScheduler ? _remoteScheduler(snapshot, { events }) : _remoteSaver(snapshot, { events }));
    _remoteSaveQueue.catch(err => console.error('[playlist-store] Failed to checkpoint playlist to IPFS:', err.message));
  }
}

// ── Mutations ─────────────────────────────────────────────────────────────────

/**
 * Return the stable identity for a playlist entry.
 * New Discord uploads use the attachment snowflake; legacy entries fall back
 * to message ID + filename so multiple attachments from one message survive.
 *
 * @param {{ attachmentId?: string, messageId: string, filename: string }} track
 * @returns {string}
 */
export function getTrackId(track) {
  return track.attachmentId || `${track.messageId}:${track.filename}`;
}

/**
 * Add a track to the playlist (idempotent — keyed on attachment identity).
 *

 * @param {Omit<TrackEntry, 'likes'|'dislikes'|'plays'|'addedAt'>} track
 * @returns {boolean} true if the track was newly added, false if already present
 */
export function addTrack(track) {
  const trackId = getTrackId(track);
  if (_playlist.some((existing) => existing.trackId === trackId)) return false;
  _playlist.push({
    ...track,
    trackId,
    mintStatus: track.mintStatus || 'unminted',
    likes:    0,
    dislikes: 0,
    plays:    0,
    addedAt:  new Date().toISOString(),
  });
  const added = _playlist.at(-1);
  _save({ events: [{ id: `submission:${trackId}`, type: 'submission', observedAt: added.addedAt,
    occurredAt: added.addedAt, trackId, source: added.source || 'discord',
    title: added.title || added.filename, ipfsCid: added.ipfsCid || null,
    mediaType: added.mediaType || null, isDevertAd: added.isDevertAd === true }] });
  return true;
}

export function submitMediaTrack({ address, title, artist, ipfsCid, mediaType, filename, recipient, artworkCid, tipWallet, parentTokenId, isDevertAd = false, creatorSplits }) {
  const trackId = `site:${address.toLowerCase()}:${ipfsCid}`;
  const existing = _playlist.find(track => track.trackId === trackId);
  if (existing) {
    if ((existing.isDevertAd === true) !== (isDevertAd === true) ||
      (creatorSplits && JSON.stringify(existing.creatorSplits || [{ wallet: existing.mintRecipient, shareBps: 10000 }]) !== JSON.stringify(creatorSplits))) {
      throw new Error('This recording was already submitted with a different advert classification or DJuke split. Contact the owner to review it; existing payout settings were not changed.');
    }
    return existing;
  }
  const videoUrl = mediaType === 'video/mp4' ? `ipfs://${ipfsCid}` : '';

  addTrack({ attachmentId: trackId, source: 'site', uploaderId: `wallet:${address.toLowerCase()}`,
    uploader: artist, title, ipfsCid, mediaType, filename, pinStatus: 'pinned', artworkCid, videoUrl,
    tipWallet: tipWallet || recipient, parentTokenId, isDevertAd, ...(creatorSplits ? { creatorSplits } : {}),
    mintStatus: 'requested', mintRecipient: recipient, mintRequestedAt: new Date().toISOString() });
  return _playlist.find(track => track.trackId === trackId);
}

/**
 * Persist the outcome of an IPFS pin attempt.
 * @param {string} trackId
 * @param {{ status: 'pending'|'pinned'|'failed'|'disabled'|'untracked', ipfsCid?: string, error?: string }} result
 * @param {{ save?: boolean }} [options] - Pass save:false when batching, then call savePlaylist()
 * @returns {TrackEntry|null}
 */
export function updateTrackPin(trackId, result, { save = true } = {}) {
  const track = _playlist.find((entry) => entry.trackId === trackId);
  if (!track) return null;

  track.pinStatus = result.status;
  if (result.ipfsCid) track.ipfsCid = result.ipfsCid;
  if (result.error) track.pinError = result.error;
  else delete track.pinError;
  if (save) _save();
  return track;
}

/** Persist batched mutations locally and to the remote checkpoint. */
export function savePlaylist() {
  _save();
}

export function hasPayrollHistoryRecovery(snapshotCid) {
  return _playlist.some(track => track.payrollRecoveryCids?.includes(`v2:${snapshotCid}`));
}

export function seedPlaylistFromPayrollSnapshot(archivedPlaylist, snapshotCid, snapshotSavedAt) {
  if (_playlist.length) throw new Error('Payroll recovery can seed only an empty playlist');
  if (!Array.isArray(archivedPlaylist) || !/^[a-zA-Z0-9]{20,120}$/.test(snapshotCid || '')) {

    throw new Error('A valid archived playlist and snapshot CID are required');
  }
  const savedAt = Date.parse(snapshotSavedAt || '');
  if (!Number.isFinite(savedAt)) throw new Error('Archived playlist snapshot timestamp is required');
  _playlist = _normalizePlaylist(archivedPlaylist);
  const recoveredAt = new Date().toISOString();
  for (const track of _playlist) {
    track.payrollLiveTrackingStartedAt = recoveredAt;
    track.payrollRecoverySnapshotAt = new Date(savedAt).toISOString();
    track.payrollRecoveryCids = [...new Set([...(track.payrollRecoveryCids || []), snapshotCid, `v2:${snapshotCid}`])].slice(-32);
  }
  _save();
  return _playlist.length;
}

export function mergePayrollHistorySnapshot(archivedPlaylist, snapshotCid, { snapshotSavedAt } = {}) {
  if (!Array.isArray(archivedPlaylist) || !/^[a-zA-Z0-9]{20,120}$/.test(snapshotCid || '')) {
    throw new Error('A valid archived playlist and snapshot CID are required');
  }
  const archivedAt = Date.parse(snapshotSavedAt || '');
  const currentById = new Map(_playlist.map(track => [track.trackId, track]));
  let mergedTracks = 0;
  let addedPlays = 0;
  let addedVotes = 0;
  let correctedPlays = 0;
  let correctedVotes = 0;
  for (const archived of archivedPlaylist) {
    const current = currentById.get(archived.trackId);
    const recoveryKey = `v2:${snapshotCid}`;
    if (!current || current.payrollRecoveryCids?.includes(recoveryKey)) continue;
    const alreadyMergedByEarlierCode = current.payrollRecoveryCids?.includes(snapshotCid) === true;
    current.payrollLiveTrackingStartedAt ||= current.payrollRecoverySnapshotAt || current.payrollTrackingStartedAt || new Date().toISOString();
    const liveTrackingStartedAt = Date.parse(current.payrollLiveTrackingStartedAt);

const previousRecoveryAt = Date.parse(current.payrollRecoverySnapshotAt || '');
const isNewerRecoverySnapshot = Number.isFinite(archivedAt) &&
  (!Number.isFinite(previousRecoveryAt) || archivedAt > previousRecoveryAt);
const currentStartedAfterSnapshot = isNewerRecoverySnapshot && Number.isFinite(liveTrackingStartedAt) && liveTrackingStartedAt > archivedAt;
for (const field of ['payrollPlays', 'payrollVotes']) {
  const source = archived[field];
  if (!source || typeof source !== 'object' || Array.isArray(source)) continue;
  current[field] ||= {};
  for (const [week, rawValue] of Object.entries(source)) {
    const value = Number(rawValue);
    if (!Number.isSafeInteger(value) || value < 0) throw new Error(`Invalid ${field} value in archived playlist`);
    const existing = Number(current[field][week] || 0);
    if (!Number.isSafeInteger(existing) || existing < 0) throw new Error(`Invalid current ${field} value`);
    const periodClosedAtLiveStart = /^NY-\d{4}-\d{2}-\d{2}$/.test(week) &&
      Date.parse(payrollPeriodFromKey(week).endAt) <= liveTrackingStartedAt;
    const shouldAdd = !alreadyMergedByEarlierCode && currentStartedAfterSnapshot && !periodClosedAtLiveStart;
    const merged = alreadyMergedByEarlierCode && periodClosedAtLiveStart ? value
      : shouldAdd ? existing + value : Math.max(existing, value);
    if (!Number.isSafeInteger(merged)) throw new Error(`Merged ${field} exceeds safe accounting precision`);
    current[field][week] = merged;
    const delta = merged - existing;
    if (field === 'payrollPlays') {
      if (delta >= 0) addedPlays += delta;
      else correctedPlays -= delta;
    } else if (delta >= 0) addedVotes += delta;

        else correctedVotes -= delta;
      }
    }
    if (Number.isFinite(archivedAt)) current.payrollRecoverySnapshotAt = new Date(Math.max(
      Number.isFinite(previousRecoveryAt) ? previousRecoveryAt : 0, archivedAt,
    )).toISOString();
    if (archived.payrollTrackingStartedAt && (!current.payrollTrackingStartedAt ||
        Date.parse(archived.payrollTrackingStartedAt) < Date.parse(current.payrollTrackingStartedAt))) {
      current.payrollTrackingStartedAt = archived.payrollTrackingStartedAt;
    }
    current.payrollRecoveryCids = [...new Set([...(current.payrollRecoveryCids || []), snapshotCid, recoveryKey])].slice(-32);
    mergedTracks++;
  }
  if (mergedTracks) _save();
  return { mergedTracks, addedPlays, addedVotes, correctedPlays, correctedVotes };
}

/**
 * Mark tracks minted from on-chain DecentNFT records (audio CID → token ID),
 * so lost local state can never re-queue an existing NFT. Checkpoints once.
 * @param {Map<string, string>} tokenIdByAudioCid
 * @returns {number} Tracks newly marked minted
 */
export function applyOnChainMints(tokenIdByAudioCid, {
  artistWalletByAudioCid = new Map(), tokenReferencesByAudioCid = new Map(),
} = {}) {
  let changed = 0;
  for (const track of _playlist) {
    const tokenId = track.ipfsCid && tokenIdByAudioCid.get(track.ipfsCid);
    if (!tokenId) continue;
    let updated = false;
    if (track.mintStatus !== 'minted') {
      track.mintStatus = 'minted';
      track.tokenId = tokenId;
      track.mintedAt ??= new Date().toISOString();
      updated = true;
    }
    const references = tokenReferencesByAudioCid.get(track.ipfsCid);
    if (references && JSON.stringify(track.nftReferences) !== JSON.stringify(references)) {
      track.nftReferences = references.map(reference => ({ ...reference }));

      updated = true;
    }
    const artistWallet = artistWalletByAudioCid.get(track.ipfsCid);
    if (!track.mintRecipient && /^0x[0-9a-fA-F]{40}$/.test(artistWallet || '')) {
      track.mintRecipient = artistWallet;
      updated = true;
    }
    if (updated) changed++;
  }
  if (changed) _save();
  return changed;
}

/** Apply corrected display titles in one checkpoint; returns how many changed. */
export function restoreTrackTitles(updates) {
  let changed = 0;
  for (const { trackId, legacyTrackId, title } of updates) {
    const track = _playlist.find((entry) => entry.trackId === trackId || entry.trackId === legacyTrackId);
    if (!track || !title || track.title === title) continue;
    track.title = title;
    changed++;
  }
  if (changed) _save();
  return changed;
}

/** Queue a pinned track for manual owner-wallet mint approval. */
export function requestTrackMint(trackId, uploaderId, recipient, artworkCid) {
  const track = _playlist.find((entry) => entry.trackId === trackId);
  if (!track || track.uploaderId !== uploaderId) return null;
  if (track.pinStatus !== 'pinned' || !track.ipfsCid || track.mintStatus === 'minted') return null;

  track.mintStatus = 'requested';
  track.mintRecipient = recipient;
  track.mintRequestedAt = new Date().toISOString();
  if (artworkCid) track.artworkCid = artworkCid;
  _save();
  return track;
}

/**
 * Queue every pinned, unminted, not-yet-requested upload by one Discord user,
 * oldest first, for owner-wallet minting to `recipient`. Checkpoints once.
 * `artworkCid` becomes the default image for queued and already-requested tracks without artwork.
 * @returns {{ queued: TrackEntry[], skipped: number }} skipped = uploads not on IPFS yet
 */

export function queueUploaderMints(uploaderId, recipient, { artworkCid, now = Date.now() } = {}) {
  const uploads = _playlist
    .filter((track) => track.uploaderId === uploaderId && track.mintStatus === 'unminted')
    .sort((first, second) => Date.parse(first.addedAt) - Date.parse(second.addedAt));
  const ready = uploads.filter((track) => track.pinStatus === 'pinned' && track.ipfsCid);
  ready.forEach((track, index) => {
    track.mintStatus = 'requested';
    track.mintRecipient = recipient;
    // Offset by index so the queue keeps posting order.
    track.mintRequestedAt = new Date(now + index).toISOString();
  });
  let artworkAdded = 0;
  if (artworkCid) {
    for (const track of _playlist) {
      if (track.uploaderId !== uploaderId || track.mintStatus !== 'requested' || track.artworkCid) continue;
      track.artworkCid = artworkCid;
      artworkAdded++;
    }
  }
  if (ready.length || artworkAdded) _save();
  return { queued: ready, skipped: uploads.length - ready.length };
}

/** Record a manually approved owner-wallet mint. */
export function completeTrackMint(trackId, { tokenId, txHash, contractAddress }) {
  const track = _playlist.find((entry) => entry.trackId === trackId);
  if (!track) return null;
  if (track.mintStatus === 'minted') return String(track.tokenId) === String(tokenId) ? track : null;
  if (track.mintStatus !== 'requested') return null;

  track.mintStatus = 'minted';
  track.tokenId = String(tokenId);
  track.mintTxHash = txHash;
  if (contractAddress) track.nftReferences = [{ chainId: 8453, contractAddress, tokenId: String(tokenId) }];
  track.mintedAt = new Date().toISOString();
  _save();
  return track;
}

/**
 * Remove a track by its Discord upload message ID.
 * @param {string} messageId

 * @returns {TrackEntry|null} The removed entry, or null if not found.
 */
export function removeTrack(trackId) {
  const idx = _playlist.findIndex((track) => track.trackId === trackId);
  if (idx === -1) return null;
  const [removed] = _playlist.splice(idx, 1);
  _save();
  return removed;
}

/**
 * Merge a Discord message's current reaction counts into the master vote totals.
 * Repeated snapshots apply only their delta; this never increments play counts.
 *
 * @param {string} trackId
 * @param {number} newLikes    - Current human 👍 count for this message
 * @param {number} newDislikes - Current human 👎 count for this message
 * @param {string} messageId
 */
export function applyRating(trackId, newLikes, newDislikes, messageId, { initialCounts, save = true, weekly = true, now = Date.now() } = {}) {
  const track = _playlist.find((entry) => entry.trackId === trackId);
  if (!track) return null;
  const likes = Math.max(0, Number(newLikes) || 0);
  const dislikes = Math.max(0, Number(newDislikes) || 0);
  if (likes > 0 || dislikes > 0 || track.likes > 0 || track.dislikes > 0) track.everHumanVoted = true;
  track.discordRatings ||= {};
  const previous = messageId && Object.hasOwn(track.discordRatings, messageId) ? track.discordRatings[messageId] : initialCounts;
  const legacy = messageId && track.ratedMessageIds?.includes(messageId) && !previous;
  const delta = legacy ? 0 : likes - (previous?.likes || 0) - dislikes + (previous?.dislikes || 0);
  if (weekly && delta) {
    const week = getUtcWeekKey(new Date(now));
    track.weeklyVotes ||= {};
    track.weeklyVotes[week] = (track.weeklyVotes[week] || 0) + delta;
    const payrollWeek = currentPayrollPeriod(now).week;
    track.payrollVotes ||= {};

    track.payrollVotes[payrollWeek] = (track.payrollVotes[payrollWeek] || 0) + delta;
  }
  track.likes = Math.max(0, (track.likes || 0) + (legacy ? 0 : likes - (previous?.likes || 0)));
  track.dislikes = Math.max(0, (track.dislikes || 0) + (legacy ? 0 : dislikes - (previous?.dislikes || 0)));
  if (messageId) track.discordRatings[messageId] = { likes, dislikes };
  if (messageId && !track.ratedMessageIds?.includes(messageId)) track.ratedMessageIds = [...(track.ratedMessageIds || []), messageId].slice(-500);
  const changed = !legacy && (likes !== (previous?.likes || 0) || dislikes !== (previous?.dislikes || 0));
  if (changed) _pendingHistoryEvents.push({
    id: randomUUID(), type: weekly ? 'vote' : 'vote-reconciliation', source: 'discord', trackId, messageId: messageId || null,
    observedAt: new Date(now).toISOString(), occurredAt: null, likes, dislikes,
    likesDelta: likes - (previous?.likes || 0), dislikesDelta: dislikes - (previous?.dislikes || 0),
  });
  if (save) _save({ routine: true });
  return track;
}

export function applySiteVote(trackId, vote, { now = Date.now() } = {}) {
  if (vote !== 1 && vote !== -1) throw new Error('Invalid vote');
  const track = _playlist.find((entry) => entry.trackId === trackId);
  if (!track) throw new Error('Track is no longer in the playlist');
  track.everHumanVoted = true;
  if (vote === 1) track.likes += 1;
  else track.dislikes += 1;
  const week = getUtcWeekKey(new Date(now));
  track.weeklyVotes ||= {};
  track.weeklyVotes[week] = (track.weeklyVotes[week] || 0) + vote;
  const payrollWeek = currentPayrollPeriod(now).week;
  track.payrollVotes ||= {};
  track.payrollVotes[payrollWeek] = (track.payrollVotes[payrollWeek] || 0) + vote;

  _save({ routine: true, events: [{ id: randomUUID(), type: 'vote', source: 'site', trackId, vote,
    observedAt: new Date(now).toISOString(), occurredAt: new Date(now).toISOString() }] });
  return track;
}

/** Reconcile many Discord announcements atomically and checkpoint once. */
export function reconcileRatings(events) {
  let reconciled = 0;
  const floors = new Map();
  const observed = new Map();
  const recoveredTracks = new Set();
  for (const { trackId, likes, dislikes } of events) {
    const counts = observed.get(trackId) || { likes: 0, dislikes: 0 };
    counts.likes += Math.max(0, Number(likes) || 0);
    counts.dislikes += Math.max(0, Number(dislikes) || 0);
    observed.set(trackId, counts);
  }
  for (const { trackId, legacyTotals } of events) {
    if (!legacyTotals) continue;
    const floor = floors.get(trackId) || { likes: 0, dislikes: 0, plays: 0 };
    for (const field of ['likes', 'dislikes', 'plays']) floor[field] = Math.max(floor[field], Number(legacyTotals[field]) || 0);
    floors.set(trackId, floor);
  }
  for (const track of _playlist) {
    const floor = floors.get(track.trackId);
    if (!floor || track.discordLegacyTotalsRecovered) continue;
    floor.likes = Math.max(floor.likes, observed.get(track.trackId)?.likes || 0);
    floor.dislikes = Math.max(floor.dislikes, observed.get(track.trackId)?.dislikes || 0);
    for (const field of ['likes', 'dislikes', 'plays']) track[field] = Math.max(track[field] || 0, floor[field]);
    track.discordLegacyTotalsRecovered = true;
    recoveredTracks.add(track.trackId);
    reconciled++;
  }
  for (const { trackId, likes, dislikes, messageId, playId, legacyTotals } of events) {
    const track = _playlist.find((entry) => entry.trackId === trackId);
    if (!track || !messageId) continue;

    const alreadyRated = track.ratedMessageIds?.includes(messageId) || Object.hasOwn(track.discordRatings || {}, messageId);
    const before = JSON.stringify([track.likes, track.dislikes, track.discordRatings?.[messageId]]);
    applyRating(trackId, likes, dislikes, messageId, { save: false, weekly: false,
      initialCounts: legacyTotals || recoveredTracks.has(trackId) ? { likes, dislikes } : undefined });
    if (!alreadyRated && !playId && !legacyTotals && !track.audibleMessageIds?.includes(messageId)) track.plays = (track.plays || 0) + 1;
    if (!alreadyRated || before !== JSON.stringify([track.likes, track.dislikes, track.discordRatings?.[messageId]])) reconciled++;
  }
  if (reconciled > 0) _save({ routine: true });
  return reconciled;
}

/** Count one completed, audible play in its UTC week; retries are idempotent by playId. */
export function recordAudiblePlay(trackId, { playId, startedAt, endedAt, audibleMs, firstWeekBonus = false, announcementId } = {}) {
  if (!playId || !Number.isFinite(startedAt) || !Number.isFinite(endedAt)) return { counted: false, reason: 'invalid-event' };
  if (!Number.isFinite(audibleMs) || audibleMs < 0) return { counted: false, reason: 'under-30-seconds' };
  const track = _playlist.find((entry) => entry.trackId === trackId);
  if (!track) return { counted: false, reason: 'track-not-found' };
  const event = { id: `play:${playId}`, type: 'play', trackId, playId,
    observedAt: new Date().toISOString(), occurredAt: new Date(endedAt).toISOString(),
    startedAt: new Date(startedAt).toISOString(), endedAt: new Date(endedAt).toISOString(), audibleMs,
    qualified: audibleMs >= MIN_WEEKLY_PLAY_MS, announcementId: announcementId || null };
  if (audibleMs < MIN_WEEKLY_PLAY_MS) {
    _save({ routine: true, events: [event] });

    return { counted: false, reason: 'under-30-seconds' };
  }
  const week = getUtcWeekKey(new Date(endedAt));
  track.weeklyPlayIds ||= {};
  track.weeklyPlayIds[week] ||= [];
  if (track.weeklyPlayIds[week].includes(playId)) return { counted: false, reason: 'duplicate' };
  track.recordedPlayIds ||= [];
  if (track.recordedPlayIds.includes(playId)) return { counted: false, reason: 'duplicate' };
  track.weeklyPlays ||= {};
  track.weeklyPlays[week] = (track.weeklyPlays[week] || 0) + 1;
  const payrollWeek = currentPayrollPeriod(endedAt).week;
  track.payrollPlays ||= {};
  track.payrollPlays[payrollWeek] = (track.payrollPlays[payrollWeek] || 0) + 1;
  track.plays = (track.plays || 0) + 1;
  if (announcementId) track.audibleMessageIds = [...new Set([...(track.audibleMessageIds || []), announcementId])].slice(-5000);
  track.weeklyPlayIds[week].push(playId);
  track.weeklyPlayIds[week] = track.weeklyPlayIds[week].slice(-5000);
  if (firstWeekBonus) track.firstWeekBonusUsed = true;
  track.recordedPlayIds.push(playId);
  track.recordedPlayIds = track.recordedPlayIds.slice(-5000);
  _save({ routine: true, events: [event] });
  return { counted: true, week, weeklyPlays: track.weeklyPlays[week] };
}

export function getWeeklyPlayReport(week, { wallet } = {}) {
  return buildPlayReport(week, wallet);
}

export function getAllTimePlayReport({ wallet } = {}) {
  return buildPlayReport(null, wallet);
}

function buildPlayReport(week, wallet) {
  const allTime = week === null;
  const targetWallet = typeof wallet === 'string' ? wallet.toLowerCase() : null;
  const tracks = _playlist
    .filter((track) => allTime ? (track.plays || track.likes || track.dislikes || 0) > 0 : (track.weeklyPlays?.[week] || 0) > 0 || Boolean(track.weeklyVotes?.[week]))

    .filter((track) => !targetWallet || track.mintRecipient?.toLowerCase() === targetWallet)
    .map((track) => ({
      trackId: track.trackId,
      title: track.title,
      artist: track.uploader,
      wallet: track.mintRecipient || null,
      uploadedAt: track.addedAt || null,
      plays: allTime ? track.plays || 0 : track.weeklyPlays?.[week] || 0,
      votes: allTime ? (track.likes || 0) - (track.dislikes || 0) : track.weeklyVotes?.[week] || 0,
      likes: track.likes || 0,
      dislikes: track.dislikes || 0,
    }))
    .sort((first, second) => second.plays - first.plays || first.title.localeCompare(second.title));
  const artists = new Map();
  for (const track of tracks) {
    const artist = artists.get(track.artist) || { artist: track.artist, wallet: track.wallet, plays: 0, tracks: 0, likes: 0, dislikes: 0 };
    artist.plays += track.plays;
    artist.likes += track.likes;
    artist.dislikes += track.dislikes;
    artist.tracks++;
    artists.set(track.artist, artist);
  }
  return {
    week: allTime ? 'all-time' : week,
    qualification: allTime ? 'All-time recorded plays, including legacy Discord announcement counts. Votes are all-time.'
      : 'Completed Discord playback with at least 30 audible seconds; one event per play ID.',
    totalPlays: tracks.reduce((total, track) => total + track.plays, 0),
    trackCount: tracks.length,
    artists: [...artists.values()].sort((first, second) => second.plays - first.plays),
    tracks,
  };
}

export function getWeeklyPlayWeeks() {
  return [...new Set(_playlist.flatMap((track) => [...Object.keys(track.weeklyPlays || {}), ...Object.keys(track.weeklyVotes || {})]))].sort();
}

export function getWeeklyPlayHistory({ weeks = 12, now = Date.now(), wallet, includeAllTime = false, calendar } = {}) {

if (calendar === 'new-york') {
  const current = currentPayrollPeriod(now);
  const history = payrollPeriods(weeks, now).map(period => {
    const tracks = _playlist.filter(track => !wallet || track.mintRecipient?.toLowerCase() === wallet.toLowerCase())
      .filter(track => (track.payrollPlays?.[period.week] || 0) > 0 || Boolean(track.payrollVotes?.[period.week]))
      .map(track => ({ trackId: track.trackId, title: track.title, artist: track.uploader, wallet: track.mintRecipient || null,
        ipfsCid: track.ipfsCid || null,
        uploadedAt: track.addedAt || null, plays: track.payrollPlays?.[period.week] || 0, votes: track.payrollVotes?.[period.week] || 0,
        likes: track.likes || 0, dislikes: track.dislikes || 0 }));
    const startedAt = _playlist.map(track => track.payrollTrackingStartedAt).filter(Boolean).sort()[0] || new Date(now).toISOString();
    return { ...period, current: period.week === current.week, tracks, artists: [], accountingStartedAt: startedAt,
      partial: Date.parse(startedAt) > Date.parse(period.startAt), totalPlays: tracks.reduce((sum, track) => sum + track.plays, 0), trackCount: tracks.length };
  });
  if (includeAllTime) history.push(getAllTimePlayReport({ wallet }));
  return history;
}
const current = getUtcWeekKey(new Date(now));
const [year, weekNumber] = current.split('-W').map(Number);
const monday = new Date(Date.UTC(year, 0, 4 + (weekNumber - 1) * 7));
monday.setUTCDate(monday.getUTCDate() - ((monday.getUTCDay() + 6) % 7));
const history = [];
for (let offset = Math.max(1, Math.min(52, Number(weeks) || 12)) - 1; offset >= 0; offset--) {
  const start = new Date(monday);
  start.setUTCDate(start.getUTCDate() - offset * 7);
  const week = getUtcWeekKey(start);

    history.push({ ...getWeeklyPlayReport(week, { wallet }), current: week === current });
  }
  if (includeAllTime) history.push(getAllTimePlayReport({ wallet }));
  return history;
}

