export function getDevertAdsForWallet(address, campaigns = [], now = Date.now()) {
  if (!/^0x[0-9a-fA-F]{40}$/.test(address || '')) throw new Error('Invalid advertiser wallet');
  const owner = address.toLowerCase();
  return _playlist.filter(track => track.isDevertAd === true && track.mintRecipient?.toLowerCase() === owner)
    .map(track => {
      const campaign = campaigns.find(item => item.advertiser?.toLowerCase() === owner &&
        item.audioURI === `ipfs://${track.ipfsCid}` && Date.parse(item.startedAt) <= now && now < Date.parse(item.expiresAt));
      const minted = track.mintStatus === 'minted' && track.tokenId != null;
      return {
        trackId: track.trackId,

        title: track.title,
        ipfsCid: track.ipfsCid,
        image: track.artworkCid || '',
        artworkCid: track.artworkCid || '',
        mediaType: track.mediaType || (track.videoUrl ? 'video/mp4' : ''),
        videoUrl: track.videoUrl || (track.mediaType === 'video/mp4' ? `ipfs://${track.ipfsCid}` : ''),
        filename: track.filename || '',
        mintStatus: minted ? 'minted' : 'pending',
        tokenId: minted ? String(track.tokenId) : null,
        state: campaign ? 'active' : minted ? 'ready' : 'pending',
        campaignId: campaign?.campaignId || null,
        expiresAt: campaign?.expiresAt || null,
        secondsRemaining: campaign ? Math.max(0, Math.ceil((Date.parse(campaign.expiresAt) - now) / 1000)) : 0,
      };
    }).sort((first, second) => first.title.localeCompare(second.title));
}

export function mergeDevertAdsForWallet(submittedAds = [], ownedAds = []) {
  const byCid = new Map();
  for (const ad of submittedAds) if (ad.ipfsCid) byCid.set(ad.ipfsCid, ad);
  for (const ad of ownedAds) {
    if (!ad.ipfsCid) continue;
    const previous = byCid.get(ad.ipfsCid);
    const previousId = /^\d+$/.test(String(previous?.tokenId || '')) ? BigInt(previous.tokenId) : -1n;
    const ownedId = /^\d+$/.test(String(ad.tokenId || '')) ? BigInt(ad.tokenId) : -1n;
    if (!previous || previous.mintStatus !== 'minted' || ownedId > previousId) byCid.set(ad.ipfsCid, ad);
  }
  return [...byCid.values()].sort((first, second) => first.title.localeCompare(second.title));
}

/**
 * Compute the playback weight for a track.
 * Formula: max(0.1, 1 + likes − dislikes × 0.5)
 *
 * A brand-new track has weight 1.0.
 * Each 👍 adds 1; each 👎 removes 0.5.  Minimum weight is 0.1 so even heavily
 * down-voted tracks still occasionally appear.
 *

 * @param {TrackEntry} track
 * @returns {number}
 */
export function getWeight(track) {
  return Math.max(0.1, 1.0 + track.likes - track.dislikes * 0.5);
}

/**
 * Return a weighted-random shuffled copy of the playlist.
 *
 * Uses repeated weighted reservoir sampling: at each step a track is drawn
 * with probability proportional to its weight and removed from the candidate
 * pool, producing a fully-ordered sequence where higher-rated tracks appear
 * earlier (and thus play sooner in each loop pass).
 *
 * @returns {TrackEntry[]}
 */
export function getWeightedShuffledPlaylist(now = Date.now()) {
  const eligible = _playlist.filter(isEligibleRadioMusic);
  if (eligible.length === 0) return [];

  // Build mutable candidate array with weights
  const candidates = eligible.map((track) => ({ track, weight: getWeight(track) }));
  const result = [];

  while (candidates.length > 0) {
    const totalWeight = candidates.reduce((sum, c) => sum + c.weight, 0);
    let rand = Math.random() * totalWeight;
    let chosen = candidates.length - 1; // fallback
    for (let i = 0; i < candidates.length; i++) {
      rand -= candidates[i].weight;
      if (rand <= 0) {
        chosen = i;
        break;
      }
    }
    result.push(candidates[chosen].track);
    candidates.splice(chosen, 1);
  }

  const fresh = result
    .map((track, index) => ({ track, index, addedAt: Date.parse(track.addedAt || 0) }))
    .filter((entry) => !entry.track.firstWeekBonusUsed && entry.addedAt > 0 && now >= entry.addedAt && now - entry.addedAt < NEW_TRACK_WINDOW_MS);
  for (const entry of fresh.sort((first, second) => second.index - first.index)) {
    const target = (entry.index + Math.floor(result.length / 2)) % result.length;
    result.splice(target, 0, { ...entry.track, firstWeekBonus: true });

  }
  return result;
}

/**
 * Return the top N tracks sorted by net score (likes − dislikes×0.5), descending.
 * @param {number} [n=10]
 * @returns {TrackEntry[]}
 */
export function getTopTracks(n = 10) {
  return [..._playlist]
    .filter(track => !track.isDevertAd)
    .sort((a, b) => getWeight(b) - getWeight(a))
    .slice(0, n);
}

/** The message ID of the most recently added track (for incremental backfill). */
export function getLatestMessageId() {
  const discordTracks = _playlist.filter(track => /^\d+$/.test(track.messageId || ''));
  if (discordTracks.length === 0) return null;
  // Messages with larger IDs are newer (Discord snowflake IDs are monotonically
  // increasing and sortable as BigInt).
  return discordTracks.reduce((latest, t) => {
    return BigInt(t.messageId) > BigInt(latest) ? t.messageId : latest;
  }, discordTracks[0].messageId);
}

import { randomBytes, randomUUID, webcrypto } from 'node:crypto';
import { verifyMessage } from 'ethers';
import { PermissionFlagsBits } from 'discord.js';
import { radioCalendarOccurrences } from '../js/radio-calendar.mjs';
import { announcementHash as sharedHash, announcementAuthorization, announcementContent, defaultAnnouncementReason } from '../js/radio-announcement.mjs';

const announcementHash = value => sharedHash(value, webcrypto);

export function deserializeAnnouncements(snapshot) {
  const object = value => value && typeof value === 'object' && !Array.isArray(value);
  if (snapshot?.schemaVersion !== 1 || !object(snapshot.deliveries) || !object(snapshot.requests) ||
      Object.values(snapshot.requests).some(item => !object(item) || !['pending', 'sent'].includes(item.status) ||
        typeof item.occurrenceId !== 'string' || typeof item.nonce !== 'string' || typeof item.hash !== 'string' ||
        typeof item.marker !== 'string' || !Number.isFinite(item.createdAt)) ||
      Object.values(snapshot.deliveries).some(item => !object(item) || item.status !== 'sent' ||
        typeof item.messageId !== 'string' || !/^https:\/\/discord\.com\/channels\/\d+\/\d+\/\d+$/.test(item.messageUrl) ||
        !Number.isFinite(Date.parse(item.announcedAt)))) throw new Error('Invalid announcement checkpoint; sending disabled');
  return snapshot;
}

export function announcementMentions(selection, guild) {
  if (!selection || typeof selection.everyone !== 'boolean' || !Array.isArray(selection.roles) || selection.roles.length > 50) {
    throw new Error('Choose @everyone, mentionable roles, or no mentions');
  }
  const roles = [...new Set(selection.roles)].sort();
  for (const id of roles) {

    const role = typeof id === 'string' && /^\d{17,20}$/.test(id) && guild.roles.cache.get(id);
    if (!role || role.id === guild.id || !role.mentionable || role.managed) throw new Error('Selected role is no longer mentionable in this guild; refresh the preview');
  }
  return { mentions: { everyone: selection.everyone, roles },
    allowedMentions: { parse: selection.everyone ? ['everyone'] : [], roles, users: [], repliedUser: false } };
}

// One service/worker owns this journal. Every send is serialized and checkpointed before Discord sees it.
export function createRadioAnnouncements({ store, getSchedule, getClient, ownerWallet, channelId = '943117480883265539',
  defaultMention = 'everyone', voiceChannelId, listenUrl, now = () => Date.now(),
  canAnnounce = () => true, log = console }) {
  let state;
  let restoreError;
  let queue = Promise.resolve();
  const seen = new Map();
  let reminderTask = null;
  let reminderRetryAt = 0;
  let reminderError = null;
  let lastReminder = null;
  const ready = (async () => {
    try {
      if (!store) throw new Error('Durable announcement storage is unavailable');
      state = deserializeAnnouncements(await store.restore() || { schemaVersion: 1, deliveries: {}, requests: {} });
    } catch (error) { restoreError = error; }
  })();
  const save = async () => {
    const uri = await store.save(structuredClone(state));
    if (typeof uri !== 'string' || !uri.startsWith('ipfs://')) throw new Error('Durable checkpoint did not confirm an IPFS receipt');
  };
  const lastDelivery = id => Object.hasOwn(state.deliveries, id) ? state.deliveries[id] : null;
  const reminderId = (id, startUtc) => `reminder:${id}:${startUtc}`;

  async function destination() {

  if (!canAnnounce()) throw new Error('Discord cooldown active; wait before announcing');
  const client = getClient();
  if (!client?.isReady()) throw new Error('Discord bot is reconnecting; retry shortly');
  const channel = await client.channels.fetch(channelId);
  if (!channel?.guild || !channel.isTextBased() || typeof channel.send !== 'function') throw new Error('Announcement channel is unavailable');
  const permissions = channel.permissionsFor(client.user);
  for (const permission of ['ViewChannel', 'SendMessages', 'EmbedLinks', 'ReadMessageHistory']) {
    if (!permissions?.has(PermissionFlagsBits[permission])) throw new Error(`Bot needs ${permission} permission in #${channel.name}`);
  }
  const voiceId = voiceChannelId;
  const voice = voiceId && channel.guild.channels.cache.get(voiceId);
  if (!voice?.isVoiceBased()) throw new Error('Configure JUKE_LOOP_VOICE_CHANNEL_ID to a voice channel in the announcement guild');
  return { channel, permissions, voiceUrl: `https://discord.com/channels/${channel.guild.id}/${voiceId}` };
}

async function draftFor(payload, dest, automatic = false) {
  const schedule = await getSchedule();
  if (schedule.ready !== true) throw new Error('Shared calendar is restoring; refresh before announcing');
  const event = radioCalendarOccurrences(schedule, { now: now(), days: 90, pastDays: 0 }).find(item => item.id === payload.occurrenceId);
  if (!event || event.startUtc !== payload.startUtc) throw new Error('Occurrence changed or removed; refresh the calendar and preview again');
  if (event.status === 'cancelled' || Date.parse(event.endUtc) <= now()) throw new Error('Cannot announce a canceled or ended occurrence');

  if (automatic && (event.announce === false || Date.parse(event.startUtc) <= now() ||
    Date.parse(event.startUtc) - now() > 5 * 60_000)) throw new Error('Reminder is disabled or outside its five-minute window');
  const show = schedule.schedule?.find(item => item.id === event.showId);
  const revision = await announcementHash({ event, show: show || null });
  if (payload.revision && payload.revision !== revision) throw new Error('Stale preview: occurrence changed; refresh and reconfirm');
  const reason = payload.reason === undefined ? defaultAnnouncementReason(event, show) : payload.reason;
  if (typeof reason !== 'string' || !reason.trim() || reason.length > 600) throw new Error('Reason must be 1–600 characters');
  const { mentions, allowedMentions } = announcementMentions(payload.mentions, dest.channel.guild);
  if (mentions.everyone && !dest.permissions.has(PermissionFlagsBits.MentionEveryone)) {
    throw new Error('Bot lacks Mention Everyone permission in this channel; grant it or choose roles/none and preview again');
  }
  if (payload.requestId !== undefined && !/^[a-f\d-]{36}$/i.test(payload.requestId)) throw new Error('Invalid confirmation ID');
  const draft = { requestId: payload.requestId || randomUUID(), occurrenceId: event.id, startUtc: event.startUtc, revision, reason: reason.trim(), mentions,
    reannounce: payload.reannounce === true, channelId, voiceUrl: dest.voiceUrl, listenUrl };
  const content = announcementContent({ event, ...draft });
  if (content.length > 2000) throw new Error('Announcement exceeds Discord’s 2000-character limit; shorten the reason or reduce roles');
  return { draft, content, allowedMentions };
}

async function reconcile(request, channel) {

  if (request.messageId) return request;
  let before;
  for (let page = 0; page < 20; page++) {
    const messages = await channel.messages.fetch({ limit: 100, ...(before ? { before } : {}) });
    for (const message of messages.values()) {
      if (message.author.id === getClient().user.id && message.embeds.some(embed => embed.footer?.text === request.marker)) {
        return { ...request, messageId: message.id, messageUrl: message.url, announcedAt: new Date(message.createdTimestamp).toISOString() };
      }
    }
    if (!messages.size || [...messages.values()].some(message => message.createdTimestamp < request.createdAt - 5000)) break;
    before = messages.last().id;
  }
  throw new Error('Delivery uncertain: no duplicate was sent. Check Discord and retry reconciliation; an operator must resolve the pending checkpoint if no post exists.');
}

async function send(body, dest) {
  dest = await destination();
  const id = body.automatic ? reminderId(body.payload.occurrenceId, body.payload.startUtc) : body.payload.occurrenceId;
  const previousRequest = state.requests[body.nonce];
  if (previousRequest && previousRequest.hash !== body.contentHash) throw new Error('Nonce already used for different content');
  let pending = previousRequest || Object.values(state.requests).find(item => item.occurrenceId === id && item.status === 'pending');
  if (pending) {
    if (pending.status !== 'sent') {
      if (pending.channelId !== channelId) throw new Error('Pending announcement belongs to a previous destination; reconcile that channel before sending again');
      pending = { ...await reconcile(pending, dest.channel), status: 'sent' };
      state.requests[pending.nonce] = pending;

    state.deliveries = { ...state.deliveries, [id]: pending };
  }
  await save();
  return { delivery: pending, duplicate: true };
}
if (Date.parse(body.expiresAt) <= now()) throw new Error('Announcement authorization expired; confirm again');
const built = await draftFor(body.payload, dest, body.automatic);
if (await announcementHash(built.draft) !== body.contentHash) throw new Error('Stale preview or destination changed; refresh and reconfirm');
if (lastDelivery(id) && !built.draft.reannounce) return { delivery: lastDelivery(id), duplicate: true };
const request = { occurrenceId: id, nonce: body.nonce, hash: body.contentHash, status: 'pending',
  marker: `Radio announcement ${randomBytes(16).toString('hex')}`, channelId, createdAt: now() };
state.requests[body.nonce] = request;
try { await save(); } catch (error) { delete state.requests[body.nonce]; throw new Error(`Checkpoint failed; nothing sent. ${error.message}`); }
// The checkpoint upload can take time. Revalidate immediately before the Discord call too.
try {
  if (Date.parse(body.expiresAt) <= now()) throw new Error('Announcement authorization expired during checkpoint; confirm again');
  dest = await destination();
  const current = await draftFor(body.payload, dest, body.automatic);
  if (await announcementHash(current.draft) !== body.contentHash) throw new Error('Stale preview; refresh and reconfirm');
  if (!canAnnounce()) throw new Error('Discord cooldown began before delivery; wait before announcing');
} catch (error) {
  delete state.requests[body.nonce];
  await save();
  throw error;
}
let message;
try {

    message = await dest.channel.send({ content: built.content, allowedMentions: built.allowedMentions,
      embeds: [{ footer: { text: request.marker } }], nonce: randomBytes(12).toString('hex'), enforceNonce: true });
  } catch (error) {
    // Definite Discord rejections are safe to retry; timeouts/5xx retain the durable pending marker.
    if (error.status >= 400 && error.status < 500 && error.status !== 408) {
      delete state.requests[body.nonce];
      try { await save(); } catch { state.requests[body.nonce] = request; }
    }
    throw new Error(`Discord delivery failed: ${error.message}. Retry safely; uncertain delivery will be reconciled, not resent.`);
  }
  const delivery = { ...request, status: 'sent', messageId: message.id, messageUrl: message.url,
    announcedAt: new Date(now()).toISOString() };
  // Retain the receipt in memory even if the final checkpoint fails. Restart recovery uses the footer marker.
  state.requests[body.nonce] = delivery;
  state.deliveries = { ...state.deliveries, [id]: delivery };
  try { await save(); } catch (error) { throw new Error(`Message delivered but receipt checkpoint failed; retry safely to recover: ${error.message}`); }
  return { delivery, duplicate: false };
}

return { ready,
  reminderStatus: () => ({ retryAt: reminderRetryAt || null, error: reminderError, lastDelivery: lastReminder }),
  tick() {
    if (reminderTask) return reminderTask;
    reminderTask = (async () => {
      await ready;
      if (restoreError) throw new Error(`Announcements disabled: ${restoreError.message}`);
      if (now() < reminderRetryAt || !canAnnounce() || !getClient()?.isReady()) return;
      const schedule = await getSchedule();
      if (schedule.ready !== true) return;

    const due = radioCalendarOccurrences(schedule, { now: now(), days: 1, pastDays: 0 }).filter(event =>
      event.status !== 'cancelled' && event.announce !== false &&
      Date.parse(event.startUtc) > now() && Date.parse(event.startUtc) <= now() + 5 * 60_000 &&
      !lastDelivery(reminderId(event.id, event.startUtc)));
    for (const event of due) {
      const operation = queue.then(async () => {
        if (lastDelivery(reminderId(event.id, event.startUtc))) return;
        const dest = await destination();
        const built = await draftFor({ occurrenceId: event.id, startUtc: event.startUtc,
          mentions: { everyone: true, roles: [] }, reason: `Starting soon! ${defaultAnnouncementReason(event)}` }, dest, true);
        const result = await send({ automatic: true, payload: built.draft, nonce: built.draft.requestId,
          contentHash: await announcementHash(built.draft), expiresAt: event.startUtc }, dest);
        lastReminder = result.delivery;
        reminderError = null;
        reminderRetryAt = 0;
      });
      queue = operation.catch(() => {});
      await operation;
    }
  })().catch(error => {
    if (now() >= reminderRetryAt) log.error(`[radio-reminder] ${error.message}`);
    reminderError = error.message;
    reminderRetryAt = Math.max(reminderRetryAt, now() + 60_000);
  }).finally(() => { reminderTask = null; });
  return reminderTask;
},
async handle(action, body, origin) {
await ready;
const expires = Date.parse(body.expiresAt);
if (!['options', 'preview', 'send'].includes(action) || !/^0x[\da-f]{40}$/i.test(body.address || '') ||

    !/^[\da-f-]{16,100}$/i.test(body.nonce || '') || !Number.isFinite(expires) || expires <= now() || expires > now() + 300_000 ||
    body.contentHash !== await announcementHash(body.payload)) throw new Error('Invalid or expired announcement authorization');
const message = announcementAuthorization({ ...body, action, origin, occurrenceId: body.payload.occurrenceId, startUtc: body.payload.startUtc });
const recovered = verifyMessage(message, body.signature).toLowerCase();
if (recovered !== body.address.toLowerCase() || recovered !== ownerWallet.toLowerCase()) throw new Error('Announcement authorization is not from the radio owner');
if (restoreError) throw new Error(`Announcements disabled: ${restoreError.message}`);
for (const [nonce, entry] of seen) if (entry.expires < now()) seen.delete(nonce);
const binding = `${action}:${body.contentHash}`;
if (seen.has(body.nonce) && seen.get(body.nonce).binding !== binding) throw new Error('Nonce already used');
seen.set(body.nonce, { binding, expires });
const dest = await destination();
if (action === 'options') {
  const roles = [...dest.channel.guild.roles.cache.values()].filter(role => role.id !== dest.channel.guild.id && role.mentionable && !role.managed)
    .map(role => ({ id: role.id, name: role.name }));
  const defaults = { everyone: defaultMention === 'everyone', roles: defaultMention === 'everyone' || defaultMention === 'none' ? [] : defaultMention.split(',').map(id => id.trim()) };
  announcementMentions(defaults, dest.channel.guild);
  return { channelId, channelName: dest.channel.name, roles, defaultMentions: defaults, deliveries: state.deliveries };
}
if (action === 'preview') {
  const built = await draftFor(body.payload, dest);

      return { ...built, contentHash: await announcementHash(built.draft), channelName: dest.channel.name,
        lastAnnouncement: lastDelivery(built.draft.occurrenceId) };
    }
    if (!body.payload.requestId) throw new Error('Preview and explicitly confirm before sending');
    const result = queue.then(() => send({ ...body, automatic: false, nonce: body.payload.requestId }, dest));
    queue = result.catch(() => {});
    return result;
  } };
}

import { mkdtemp, rm } from 'node:fs/promises';
import { createWriteStream } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { Readable, Transform } from 'node:stream';
import { pipeline } from 'node:stream/promises';

/** Finish the HTTP transfer before a real-time decoder can backpressure the gateway. */
export async function bufferRadioMedia(url, { fetchImpl = fetch, signal,
  maxBytes = 256 * 1024 * 1024, timeoutMs = 90_000 } = {}) {
  const directory = await mkdtemp(join(tmpdir(), 'dbusk-paid-media-'));
  const path = join(directory, 'recording');
  const dispose = () => rm(directory, { recursive: true, force: true });
  try {
    const transferSignal = signal
      ? AbortSignal.any([signal, AbortSignal.timeout(timeoutMs)])
      : AbortSignal.timeout(timeoutMs);
    const response = await fetchImpl(url, { signal: transferSignal });
    if (response.status !== 200 || !response.body) {
      await response.body?.cancel();
      throw new Error(`Paid media download failed (HTTP ${response.status})`);
    }
    const length = response.headers.get('content-length');
    const expected = length === null ? null : Number(length);
    if (expected !== null && (!Number.isSafeInteger(expected) || expected < 1 || expected > maxBytes)) {
      await response.body.cancel();
      throw new Error('Paid media download exceeds the size limit or has an invalid length');
    }
    let bytes = 0;
    const limit = new Transform({
      transform(chunk, encoding, callback) {
        bytes += chunk.length;
        callback(bytes > maxBytes ? new Error('Paid media download exceeds the size limit') : null, chunk);
      },
    });
    await pipeline(Readable.fromWeb(response.body), limit, createWriteStream(path, { flags: 'wx' }),

      { signal: transferSignal });
    if (bytes === 0 || (expected !== null && bytes !== expected)) throw new Error('Paid media download was incomplete');
    return { path, bytes, dispose };
  } catch (error) {
    await dispose();
    throw error;
  }
}

// discord-bot/radio.js
// IPFS track-list fetcher and per-guild RadioSession manager.
//
// RadioSession streams audio files from an IPFS directory to a Discord voice
// channel using FFmpeg for transcoding and @discordjs/voice for playback.

import { spawn }  from 'child_process';
import {
  joinVoiceChannel,
  createAudioPlayer,
  createAudioResource,
  AudioPlayerStatus,
  VoiceConnectionStatus,
  entersState,
  StreamType,
} from '@discordjs/voice';

// ── IPFS helpers ──────────────────────────────────────────────────────────────

const AUDIO_EXTENSIONS_RE = /\.(mp3|m4a|wav|ogg|flac|aac|opus)$/i;

/**
 * Fetch an ordered list of audio track URLs from an IPFS directory.
 * The function fetches the HTTP gateway directory listing HTML and parses
 * every href that ends with a recognised audio extension.
 *
 * @param {string} cid     - IPFS CID (with or without ipfs:// prefix)
 * @param {string} gateway - IPFS HTTP gateway base URL (e.g. https://w3s.link)
 * @returns {Promise<string[]>} Sorted array of full HTTP track URLs
 */
export async function fetchTrackList(cid, gateway) {
  const normalizedCid = cid.replace(/^ipfs:\/\//, '').trim();
  const dirUrl = `${gateway.replace(/\/$/, '')}/ipfs/${normalizedCid}/`;

  const response = await fetch(dirUrl);
  if (!response.ok) {
    throw new Error(`HTTP ${response.status} fetching IPFS directory at ${dirUrl}`);
  }

  const html   = await response.text();
  const tracks = [];

  // Parse href attributes from the directory listing HTML.
  // Handles relative paths (track.mp3), root-relative (/ipfs/CID/track.mp3),
  // and absolute URLs.
  const hrefRe = /href="([^"]+)"/g;
  let match;

  while ((match = hrefRe.exec(html)) !== null) {
    const href = match[1];
    // Skip navigation fragments, query-only links, and parent-dir links
    if (href.startsWith('#') || href.startsWith('?') || href === '../') continue;
    if (AUDIO_EXTENSIONS_RE.test(href)) {
      try {
        tracks.push(new URL(href, dirUrl).toString());
      } catch {
        // Ignore malformed hrefs
      }
    }
  }

  return tracks.sort();
}

// ── FFmpeg stream helper ──────────────────────────────────────────────────────

/** Path to the ffmpeg binary — override via the FFMPEG_PATH env var. */
const FFMPEG_BIN = process.env.FFMPEG_PATH || 'ffmpeg';

/**
 * Spawn FFmpeg to pull an HTTP(S) audio URL and output raw 16-bit LE PCM
 * at 48 kHz stereo (the format expected by @discordjs/voice's StreamType.Raw).
 *
 * @param {string} url - Full HTTP URL of the audio file
 * @returns {{ stream: import('stream').Readable, process: import('child_process').ChildProcess }}
 */
function createFFmpegStream(url) {
  const args = [
    '-reconnect',            '1',
    '-reconnect_streamed',   '1',
    '-reconnect_delay_max',  '5',
    '-i',                    url,
    '-analyzeduration',      '0',
    '-loglevel',             '0',
    '-vn',
    '-f',  's16le',
    '-ar', '48000',
    '-ac', '2',
    'pipe:1',
  ];

  const ffmpeg = spawn(FFMPEG_BIN, args, { stdio: ['ignore', 'pipe', 'ignore'] });
  ffmpeg.on('error', (err) => console.error('[radio] FFmpeg spawn error:', err.message));
  return { stream: ffmpeg.stdout, process: ffmpeg };
}

// ── Per-guild session registry ────────────────────────────────────────────────

/** @type {Map<string, RadioSession>} guildId → active session */
const sessions = new Map();

/**
 * Return the active RadioSession for a guild, or null.
 * @param {string} guildId
 * @returns {RadioSession|null}
 */
export function getSession(guildId) {
  return sessions.get(guildId) ?? null;
}

/**
 * Create a new RadioSession for a guild, destroying any existing session first.
 *
 * @param {string} guildId
 * @param {{ voiceChannel: import('discord.js').VoiceBasedChannel, textChannel: import('discord.js').TextBasedChannel }} opts
 * @returns {RadioSession}
 */
export function createSession(guildId, opts) {
  const existing = sessions.get(guildId);
  if (existing) existing.destroy();
  const session = new RadioSession(opts);
  sessions.set(guildId, session);
  return session;
}

// ── RadioSession ──────────────────────────────────────────────────────────────

export class RadioSession {
  /**
   * @param {object} opts
   * @param {import('discord.js').VoiceBasedChannel} opts.voiceChannel
   * @param {import('discord.js').TextBasedChannel}  opts.textChannel
   */
  constructor({ voiceChannel, textChannel }) {
    this.voiceChannel  = voiceChannel;
    this.textChannel   = textChannel;
    this.queue         = [];
    this.trackIndex    = 0;
    this.isPaused      = false;
    this._destroyed    = false;
    this.connection    = null;
    this._ffmpeg       = null; // current FFmpeg child process
    this.player        = createAudioPlayer();

  this.player.on(AudioPlayerStatus.Idle, () => this._playNext());
  this.player.on('error', (err) => {
    console.error('[radio] Audio player error:', err.message);
    this._playNext();
  });
}

// ── Connection ──────────────────────────────────────────────────────────────

/** Join the voice channel and subscribe the audio player to it. */
async connect() {
  this.connection = joinVoiceChannel({
    channelId:      this.voiceChannel.id,
    guildId:        this.voiceChannel.guild.id,
    adapterCreator: this.voiceChannel.guild.voiceAdapterCreator,
  });

  await entersState(this.connection, VoiceConnectionStatus.Ready, 30_000);
  this.connection.subscribe(this.player);

  // Auto-clean-up if the bot is disconnected from outside
  this.connection.on(VoiceConnectionStatus.Disconnected, async () => {
    try {
      await Promise.race([
        entersState(this.connection, VoiceConnectionStatus.Signalling, 5_000),
        entersState(this.connection, VoiceConnectionStatus.Connecting, 5_000),
      ]);
    } catch {
      this.destroy();
    }
  });
}

// ── Playback ────────────────────────────────────────────────────────────────

/**
 * Load a track list into the queue and start playback from the beginning.
 * @param {string[]} tracks - Array of HTTP audio URLs
 */
async start(tracks) {
  this.queue      = tracks;
  this.trackIndex = 0;
  await this._playNext();
}

async _playNext() {

  // Kill any lingering FFmpeg process from the previous track
  if (this._ffmpeg) {
    try { this._ffmpeg.kill(); } catch {}
    this._ffmpeg = null;
  }

  // If the session was explicitly stopped, don't post a "finished" message
  if (this._destroyed) return;

  if (this.trackIndex >= this.queue.length) {
    await this.textChannel
      .send('✅ Radio playlist finished. Disconnecting from voice channel.')
      .catch(() => {});
    this.destroy();
    return;
  }

  const url       = this.queue[this.trackIndex];
  const filename  = url.split('/').pop();
  const trackName = filename ? decodeURIComponent(filename) : `Track ${this.trackIndex + 1}`;
  this.trackIndex++;

  try {
    const { stream, process: ffmpeg } = createFFmpegStream(url);
    this._ffmpeg = ffmpeg;

    const resource = createAudioResource(stream, { inputType: StreamType.Raw });
    this.player.play(resource);

    await this.textChannel
      .send(`🎵 Now Playing (${this.trackIndex}/${this.queue.length}): **${trackName}**`)
      .catch(() => {});
  } catch (err) {
    console.error('[radio] Failed to start track:', err.message);
    await this.textChannel
      .send(`⚠️ Skipping **${trackName}**: ${err.message}`)
      .catch(() => {});
    await this._playNext();
  }
}

// ── Controls ────────────────────────────────────────────────────────────────

/** Skip the current track and move to the next one. */
skip() {
  // Calling stop(true) forces the player into Idle state, which triggers _playNext.
  this.player.stop(true);
}

/**
 * Toggle between paused and playing.

   * @returns {boolean} true if now paused, false if now resumed
   */
  togglePause() {
    if (this.isPaused) {
      this.player.unpause();
      this.isPaused = false;
    } else {
      this.player.pause();
      this.isPaused = true;
    }
    return this.isPaused;
  }

  /** Stop playback, clear the queue, and disconnect from voice. */
  stop() {
    this.queue      = [];
    this.trackIndex = 0;
    this.destroy();
    // stop() after destroy() so the Idle event (if it fires) sees _destroyed=true
    this.player.stop(true);
  }

  /** Tear down the voice connection and remove this session from the registry. */
  destroy() {
    this._destroyed = true;
    sessions.delete(this.voiceChannel.guild.id);
    if (this._ffmpeg) {
      try { this._ffmpeg.kill(); } catch {}
      this._ffmpeg = null;
    }
    if (this.connection) {
      try { this.connection.destroy(); } catch {}
      this.connection = null;
    }
  }
}

import { JsonRpcProvider, Network } from 'ethers';

// Provider-side refusals (rate limits, archive-only gating, range caps) are retried on the next URL;
// deterministic JSON-RPC errors such as reverts are returned as-is.
const RETRYABLE_RPC_ERROR = /archive|personal token|limit|rate|too many|exceeded|range|unavailable|timeout|capacity/i;

function isRetryableResult(result) {
  return Boolean(result?.error) && RETRYABLE_RPC_ERROR.test(`${result.error.message || ''} ${result.error.data || ''}`);
}

export function rpcUrlsFromConfig(config = {}) {
  return [...new Set([config.rpcUrl, ...(config.rpcFallbackUrls || [])]
    .map(url => String(url || '').trim()).filter(Boolean))];
}

export class FailoverJsonRpcProvider extends JsonRpcProvider {
  constructor(urls, chainId = 8453) {
    const list = [...new Set((urls || []).map(url => String(url || '').trim()).filter(Boolean))];
    if (!list.length) throw new Error('At least one RPC URL is required');
    const network = Network.from(chainId);
    super(list[0], network, { staticNetwork: network, batchMaxCount: 1 });
    this.rpcUrls = list;
    this.backups = list.slice(1).map(url => new JsonRpcProvider(url, network, { staticNetwork: network, batchMaxCount: 1 }));
  }

  async _send(payload) {
    let lastError = null;
    let lastResults = null;
    for (const send of [p => super._send(p), ...this.backups.map(backup => p => backup._send(p))]) {
      try {
        const results = await send(payload);
        if (!results.some(isRetryableResult)) return results;
        lastResults = results;
      } catch (error) {
        lastError = error;
      }
    }
    if (lastResults) return lastResults;
    throw lastError;
  }

  destroy() {
    for (const backup of this.backups) backup.destroy();
    super.destroy();
  }
}

export function createFailoverProvider(config) {
  return new FailoverJsonRpcProvider(rpcUrlsFromConfig(config), config?.chainId || 8453);
}

// Read-only Base JSON-RPC proxy for browsers whose public RPC calls failed (#205).
// The paid key never leaves the worker; strict allow-lists and rate limits keep it from becoming an open relay.

const ADDRESS = /^0x[0-9a-fA-F]{40}$/;
const HASH = /^0x[0-9a-fA-F]{64}$/;
const BLOCK_TAG = /^(latest|safe|finalized|0x[0-9a-fA-F]{1,16})$/;
export const RPC_PROXY_MAX_BATCH = 10;

function rpcError(id, code, message) {
  return { jsonrpc: '2.0', id: id ?? null, error: { code, message } };
}

export function createRpcProxy({
  request,
  allowedContracts = [],
  perIpPerMinute = 120,
  globalPerMinute = 1500,
  now = () => Date.now(),
}) {
  const contracts = new Set(allowedContracts.filter(Boolean).map(address => String(address).toLowerCase()));
  const perIp = new Map();
  let globalWindow = { minute: 0, count: 0 };

  function validate(method, params) {
    if (!Array.isArray(params)) return 'params must be an array';
    switch (method) {
      case 'eth_chainId':
      case 'eth_blockNumber':
        return params.length ? 'unexpected params' : '';
      case 'eth_call': {
        const [call, tag = 'latest'] = params;
        if (!call || typeof call !== 'object' || !ADDRESS.test(call.to || '')) return 'eth_call needs a contract address';
        if (!contracts.has(call.to.toLowerCase())) return 'contract is not allow-listed';
        if (call.data != null && !/^0x[0-9a-fA-F]*$/.test(call.data)) return 'invalid call data';
        if (String(call.data || '').length > 8 * 1024) return 'call data too large';
        if (params.length > 2 || !BLOCK_TAG.test(String(tag))) return 'invalid block tag';
        return '';
      }
      case 'eth_getCode':

      if (!ADDRESS.test(params[0] || '') || !contracts.has(params[0].toLowerCase())) return 'contract is not allow-listed';
      return params.length <= 2 && BLOCK_TAG.test(String(params[1] ?? 'latest')) ? '' : 'invalid block tag';
    case 'eth_getBalance':
      return ADDRESS.test(params[0] || '') && params.length <= 2 && BLOCK_TAG.test(String(params[1] ?? 'latest')) ? '' : 'invalid params';
    case 'eth_getTransactionReceipt':
      return params.length === 1 && HASH.test(params[0] || '') ? '' : 'invalid transaction hash';
    case 'eth_getBlockByNumber':
      return params.length === 2 && BLOCK_TAG.test(String(params[0])) && params[1] === false ? '' : 'only block headers are available';
    default:
      return 'method is not available through the DecentBusking proxy';
  }
}

function take(ip, count) {
  const minute = Math.floor(now() / 60_000);
  if (globalWindow.minute !== minute) globalWindow = { minute, count: 0 };
  if (perIp.size > 5000) for (const [key, entry] of perIp) if (entry.minute !== minute) perIp.delete(key);
  const entry = perIp.get(ip)?.minute === minute ? perIp.get(ip) : { minute, count: 0 };
  if (entry.count + count > perIpPerMinute || globalWindow.count + count > globalPerMinute) return false;
  entry.count += count;
  globalWindow.count += count;
  perIp.set(ip, entry);
  return true;
}

async function one(item) {
  if (!item || typeof item !== 'object' || item.jsonrpc !== '2.0' || typeof item.method !== 'string') {
    return rpcError(item?.id, -32600, 'Invalid request');
  }
  const params = item.params ?? [];
  const problem = validate(item.method, params);
  if (problem) return rpcError(item.id, -32601, problem);
  try {

      const outcome = await request(item.method, params);
      return outcome.error
        ? { jsonrpc: '2.0', id: item.id, error: outcome.error }
        : { jsonrpc: '2.0', id: item.id, result: outcome.result };
    } catch (error) {
      return rpcError(item.id, -32603, `Base RPC unavailable: ${String(error.message || error).slice(0, 120)}`);
    }
  }

  async function handle(body, ip = 'unknown') {
    const batch = Array.isArray(body);
    const items = batch ? body : [body];
    if (!items.length || items.length > RPC_PROXY_MAX_BATCH) {
      return { status: 400, body: rpcError(null, -32600, `Send 1-${RPC_PROXY_MAX_BATCH} requests per batch`) };
    }
    if (!take(ip, items.length)) return { status: 429, body: rpcError(null, -32005, 'Rate limit reached; try again shortly') };
    const results = await Promise.all(items.map(one));
    return { status: 200, body: batch ? results : results[0] };
  }

  return { handle };
}

import { JsonRpcProvider, Network, keccak256 } from 'ethers';

// Tiered RPC routing (#205): cheap reads go public-first, history scans and
// our own transactions go paid-first, and every endpoint has a circuit breaker
// so a rate-limited host is skipped instead of hammered.

const KNOWN_PUBLIC_HOSTS = new Set([
  'mainnet.base.org', 'base-rpc.publicnode.com', 'base.drpc.org', 'base.llamarpc.com',
  '1rpc.io', 'base.meowrpc.com', 'base-mainnet.public.blastapi.io', 'base.gateway.tenderly.co',
]);
// Ordered by what works without a key: Tenderly serves historical getLogs (<= ~500 blocks),
// publicnode serves recent logs and calls, blastapi and base.org serve calls.
export const DEFAULT_PUBLIC_BASE_URLS = [
  'https://base-rpc.publicnode.com', 'https://base.gateway.tenderly.co', 'https://mainnet.base.org',
  'https://base-mainnet.public.blastapi.io', 'https://base.drpc.org',
];

// Approximate Alchemy compute-unit costs; unknown methods count as 20.
const CU_COSTS = {
  eth_chainId: 0, eth_blockNumber: 10, eth_call: 26, eth_getBalance: 19, eth_getLogs: 75,
  eth_getBlockByNumber: 16, eth_getBlockByHash: 16, eth_getTransactionReceipt: 15, eth_getTransactionByHash: 17,
  eth_getTransactionCount: 26, eth_estimateGas: 87, eth_sendRawTransaction: 250, eth_gasPrice: 19,
  eth_maxPriorityFeePerGas: 10, eth_feeHistory: 10, eth_getCode: 26,
};
const CRITICAL_METHODS = new Set(['eth_sendRawTransaction', 'eth_getTransactionCount', 'eth_estimateGas']);
const TIMEOUTS = { read: 4000, logs: 10000, critical: 15000 };
const SMALL_LOG_RANGE = 500;
const RATE_LIMIT_CODES = new Set([-32005, -32011, -32016, -32090, 429]);
const RATE_LIMIT_TEXT = /rate.?limit|request limit|too many requests|exceeded.*(quota|capacity|compute)|capacity|throughput|unavailable|timeout|temporarily/i;

// The endpoint is healthy but cannot serve this request (e.g. archive data on a free tier).
const UNSUPPORTED_TEXT = /archive|personal token|not supported on free|upgrade to (a )?paid|method not (found|available|supported)/i;
// The paid account is out of money for the month, not just briefly throttled.
const EXHAUSTED_TEXT = /monthly|spending (limit|cap)|billing|out of (compute|cu)|credits? (exhausted|depleted)|plan limit/i;
const RANGE_TEXT = /block range|ranges? over \d+ blocks|range (is )?too (large|wide)|query returned more than|too many (results|logs)|response size|limited to \d+|log response size exceeded|max.*range|range.*exceed/i;
const ALREADY_SENT_TEXT = /already known|known transaction|nonce too low|already imported/i;

export function isPaidRpcUrl(url) {
  try {
    return !KNOWN_PUBLIC_HOSTS.has(new URL(url).hostname);
  } catch {
    return false;
  }
}

function uniqueUrls(values) {
  return [...new Set(values.map(value => String(value || '').trim()).filter(Boolean))];
}

/** Builds the public and paid Base endpoint lists from env vars and payroll-assets.json. */
export function baseRpcEndpointsFromEnv(env = process.env, assets = {}) {
  const publicUrls = uniqueUrls(env.BASE_PUBLIC_RPC_URLS
    ? env.BASE_PUBLIC_RPC_URLS.split(',')
    : [assets.rpcUrl, ...(assets.rpcFallbackUrls || []), ...DEFAULT_PUBLIC_BASE_URLS]);
  const overrides = uniqueUrls([env.ALCHEMY_BASE_URL, env.BASE_RPC_URL, env.BASE_LOGS_RPC_URL, env.PAYROLL_ARCHIVE_RPC_URL]);
  const paidUrls = overrides.filter(isPaidRpcUrl);
  for (const url of overrides) if (!isPaidRpcUrl(url) && !publicUrls.includes(url)) publicUrls.unshift(url);
  return { publicUrls, paidUrls };
}

function endpointLabel(url, tier, index) {
  try {
    return `${tier}#${index + 1} ${new URL(url).hostname}`;

  } catch {
    return `${tier}#${index + 1}`;
  }
}

function percentile(values, fraction) {
  if (!values.length) return null;
  const sorted = [...values].sort((a, b) => a - b);
  return sorted[Math.min(sorted.length - 1, Math.floor(fraction * sorted.length))];
}

function parseBlock(value) {
  if (typeof value === 'number') return value;
  if (typeof value === 'string' && /^0x[0-9a-f]+$/i.test(value)) return Number.parseInt(value, 16);
  return null;
}

const toHex = value => `0x${value.toString(16)}`;

class RpcAttemptError extends Error {
  constructor(message, { kind, ambiguous = false } = {}) {
    super(message);
    this.kind = kind;
    this.ambiguous = ambiguous;
  }
}

export function classifyRpcError(error) {
  const message = `${error?.message || ''} ${typeof error?.data === 'string' ? error.data : ''}`;
  if (RANGE_TEXT.test(message)) return 'range';
  if (EXHAUSTED_TEXT.test(message)) return 'exhausted';
  if (UNSUPPORTED_TEXT.test(message)) return 'unsupported';
  if (RATE_LIMIT_CODES.has(Number(error?.code)) || RATE_LIMIT_TEXT.test(message)) return 'limit';
  return 'final';
}

// Budget for the paid tier, sized for a $33/month Alchemy cap. Our CU counts are estimates,
// so the default stays under the plan's ~73M CU to leave headroom.
export const DEFAULT_MONTHLY_CU_BUDGET = 60_000_000;
export const BUDGET_MODES = Object.freeze({
  normal: 'normal',              // paid-first for logs and transactions, public-first for reads
  conserve: 'conserve',          // ahead of the monthly pace: everything but transactions goes public-first
  criticalOnly: 'critical-only', // spendable budget used: paid tier only for transaction paths
  exhausted: 'exhausted',        // budget gone or Alchemy refused: public only, probe paid occasionally
});

function monthWindow(time) {
  const date = new Date(time);
  const start = Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), 1);
  const end = Date.UTC(date.getUTCFullYear(), date.getUTCMonth() + 1, 1);
  return { key: date.toISOString().slice(0, 7), start, end, days: Math.round((end - start) / 86_400_000) };
}

export function createRpcRouter({
  chainId = 8453,
  publicUrls = [],
  paidUrls = [],
  fetchImpl = globalThis.fetch,
  now = () => Date.now(),
  timeouts = TIMEOUTS,
  dailyCuSoftLimit = Infinity,
  monthlyCuBudget = Infinity,
  reserveFraction = 0.1,
  exhaustedProbeMs = 30 * 60_000,
  initialUsage = null,
  onModeChange = () => {},
  readCacheMs = 10_000,
  breakerBaseMs = 30_000,
  breakerMaxMs = 5 * 60_000,
  minLogRange = 10,
} = {}) {
  const endpoints = [
    ...paidUrls.map((url, index) => ({ url, tier: 'paid', label: endpointLabel(url, 'paid', index) })),
    ...publicUrls.map((url, index) => ({ url, tier: 'public', label: endpointLabel(url, 'public', index) })),
  ].map(endpoint => ({
    ...endpoint, requests: 0, ok: 0, failed: 0, rateLimited: 0, latencies: [],
    strikes: 0, openUntil: 0, lastError: '',
  }));
  if (!endpoints.length) throw new Error('At least one RPC URL is required');
  const paid = endpoints.filter(endpoint => endpoint.tier === 'paid');
  const pub = endpoints.filter(endpoint => endpoint.tier === 'public');
  const inflight = new Map();
  const cache = new Map();
  const consumers = {};
  const usage = { day: '', dayCu: 0, minute: 0, minuteCu: 0, byMethod: {}, month: '', monthCu: 0 };
  // Adds usage persisted before a restart to what this process has spent since booting. Call once per snapshot.
  function restoreUsage(snapshot) {
    if (!snapshot || typeof snapshot !== 'object') return false;

  const window = monthWindow(now());
  let changed = false;
  if (snapshot.month === window.key && Number.isFinite(snapshot.monthCu) && snapshot.monthCu > 0) {
    if (usage.month !== window.key) Object.assign(usage, { month: window.key, monthCu: 0 });
    usage.monthCu += snapshot.monthCu;
    changed = true;
  }
  const today = new Date(now()).toISOString().slice(0, 10);
  if (snapshot.day === today && Number.isFinite(snapshot.dayCu) && snapshot.dayCu > 0) {
    if (usage.day !== today) Object.assign(usage, { day: today, dayCu: 0, byMethod: {} });
    usage.dayCu += snapshot.dayCu;
    changed = true;
  }
  return changed;
}
restoreUsage(initialUsage);
let requestId = 0;
let exhaustedUntil = 0;
let lastMode = null;

function budget() {
  const time = now();
  const window = monthWindow(time);
  const monthCu = usage.month === window.key ? usage.monthCu : 0;
  const today = new Date(time).toISOString().slice(0, 10);
  const dayCu = usage.day === today ? usage.dayCu : 0;
  if (!Number.isFinite(monthlyCuBudget)) {
    const mode = exhaustedUntil > time ? BUDGET_MODES.exhausted : dayCu >= dailyCuSoftLimit ? BUDGET_MODES.conserve : BUDGET_MODES.normal;
    return { mode, monthCu, dayCu, monthlyBudget: null };
  }
  const spendable = monthlyCuBudget * (1 - reserveFraction);
  const elapsed = (time - window.start) / (window.end - window.start);
  // Linear pace through the month plus one day of slack.
  const pacedTarget = Math.min(spendable, spendable * elapsed + spendable / window.days);
  let mode = BUDGET_MODES.normal;
  if (exhaustedUntil > time || monthCu >= monthlyCuBudget) mode = BUDGET_MODES.exhausted;
  else if (monthCu >= spendable) mode = BUDGET_MODES.criticalOnly;

  else if (monthCu > pacedTarget || dayCu >= dailyCuSoftLimit) mode = BUDGET_MODES.conserve;
  const elapsedMs = Math.max(time - window.start, 3_600_000);
  const projected = Math.round(monthCu / elapsedMs * (window.end - window.start));
  return {
    mode, monthCu, dayCu, monthlyBudget: monthlyCuBudget, reserve: Math.round(monthlyCuBudget * reserveFraction),
    pacedTarget: Math.round(pacedTarget), projectedMonthCu: projected,
    dailyAllowance: Math.round(Math.max(0, spendable - monthCu) / Math.max(1, (window.end - time) / 86_400_000)),
    month: window.key,
  };
}

function currentMode() {
  const { mode } = budget();
  if (mode !== lastMode) {
    const previous = lastMode;
    lastMode = mode;
    if (previous !== null) {
      try { onModeChange(mode, previous); } catch { /* observer errors never block RPC */ }
    }
  }
  return mode;
}

function chargeCu(method) {
  const time = now();
  const day = new Date(time).toISOString().slice(0, 10);
  const minute = Math.floor(time / 60_000);
  if (usage.day !== day) Object.assign(usage, { day, dayCu: 0, byMethod: {} });
  const month = day.slice(0, 7);
  if (usage.month !== month) Object.assign(usage, { month, monthCu: 0 });
  if (usage.minute !== minute) Object.assign(usage, { minute, minuteCu: 0 });
  const cost = CU_COSTS[method] ?? 20;
  usage.dayCu += cost;
  usage.minuteCu += cost;
  usage.monthCu += cost;
  usage.byMethod[method] = (usage.byMethod[method] || 0) + cost;
}


function classify(method, kind) {
  if (method === 'eth_getLogs') return 'logs';
  if (CRITICAL_METHODS.has(method)) return 'critical';
  return kind;
}

function logRange(params) {
  const filter = params?.[0] || {};
  if (filter.blockHash) return 0;

  const from = parseBlock(filter.fromBlock);
  const to = parseBlock(filter.toBlock);
  return from == null || to == null ? Infinity : Math.max(0, to - from + 1);
}

function orderFor(cls, method, params) {
  const mode = currentMode();
  const time = now();
  const transactionPath = CRITICAL_METHODS.has(method) || method === 'eth_getTransactionReceipt';
  let first = paid;
  let second = pub;
  if (cls === 'read' || (cls === 'logs' && logRange(params) <= SMALL_LOG_RANGE)) [first, second] = [pub, paid];
  // 'fallback' = the browser already tried public RPCs, so go paid-first while the budget allows.
  if (mode === BUDGET_MODES.conserve && !transactionPath) [first, second] = [pub, paid];
  if (mode === BUDGET_MODES.criticalOnly) {
    [first, second] = cls === 'critical' || transactionPath ? [paid, pub] : [pub, []];
  }
  if (mode === BUDGET_MODES.exhausted) {
    // Retry the paid tier once per probe window so a new month or raised cap is picked up.
    const probe = paid.length && exhaustedUntil <= time;
    [first, second] = [pub, probe && (cls === 'critical' || transactionPath) ? paid : []];
  }
  const ordered = [...first, ...second];
  return [...ordered.filter(endpoint => endpoint.openUntil <= time), ...ordered.filter(endpoint => endpoint.openUntil > time)];
}

function trip(endpoint, message) {
  endpoint.strikes += 1;
  endpoint.openUntil = now() + Math.min(breakerMaxMs, breakerBaseMs * 2 ** (endpoint.strikes - 1));
  endpoint.lastError = String(message || '').slice(0, 160);
}

async function attempt(endpoint, method, params, timeoutMs) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  const started = now();

endpoint.requests += 1;
if (endpoint.tier === 'paid') chargeCu(method);
try {
  let response;
  try {
    response = await fetchImpl(endpoint.url, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ jsonrpc: '2.0', id: ++requestId, method, params }),
      signal: controller.signal,
    });
  } catch (error) {
    throw new RpcAttemptError(controller.signal.aborted ? `timeout after ${timeoutMs}ms` : error.message, { kind: 'limit', ambiguous: true });
  }
  if (!response.ok) {
    const errorBody = await response.json().catch(() => null);
    const rpcError = errorBody?.error;
    const rpcKind = rpcError ? classifyRpcError(rpcError) : '';
    if (rpcKind === 'range' || rpcKind === 'unsupported') throw new RpcAttemptError(rpcError.message, { kind: rpcKind });
    if (rpcKind === 'exhausted') throw new RpcAttemptError(rpcError.message, { kind: endpoint.tier === 'paid' ? 'exhausted' : 'unsupported' });
    const kind = [401, 403, 408, 429].includes(response.status) || response.status >= 500 ? 'limit' : 'final';
    const detail = rpcError?.message ? `: ${String(rpcError.message).slice(0, 120)}` : '';
    throw new RpcAttemptError(`HTTP ${response.status}${detail}`, { kind, ambiguous: response.status >= 500 });
  }
  let body;
  try {
    body = await response.json();
  } catch {
    throw new RpcAttemptError('Invalid JSON-RPC response', { kind: 'limit', ambiguous: true });
  }
  if (body?.error) {
    const kind = classifyRpcError(body.error);
    if (kind === 'exhausted' && endpoint.tier === 'public') throw new RpcAttemptError(body.error.message || 'RPC error', { kind: 'unsupported' });

      if (kind === 'final') return { error: body.error };
      throw new RpcAttemptError(body.error.message || 'RPC error', { kind });
    }
    endpoint.latencies.push(now() - started);
    if (endpoint.latencies.length > 200) endpoint.latencies.shift();
    return { result: body?.result ?? null };
  } finally {
    clearTimeout(timer);
  }
}

async function dispatch(cls, method, params) {
  let lastError = null;
  let rangeError = null;
  let ambiguousSend = false;
  for (const endpoint of orderFor(cls, method, params)) {
    try {
      const outcome = await attempt(endpoint, method, params, timeouts[cls] || timeouts.read);
      if (outcome.error && method === 'eth_sendRawTransaction' && ambiguousSend && ALREADY_SENT_TEXT.test(outcome.error.message || '')) {
        endpoint.ok += 1;
        return { result: keccak256(params[0]) };
      }
      endpoint.ok += 1;
      endpoint.strikes = 0;
      return outcome;
    } catch (error) {
      endpoint.failed += 1;
      lastError = error;
      if (error.kind === 'range') {
        rangeError = error;
        endpoint.lastError = String(error.message).slice(0, 160);
        continue;
      }
      if (error.kind === 'unsupported') {
        endpoint.lastError = String(error.message).slice(0, 160);
        continue;
      }
      if (error.kind === 'exhausted') {
        exhaustedUntil = now() + exhaustedProbeMs;
        endpoint.lastError = String(error.message).slice(0, 160);
        currentMode();
        continue;
      }
      if (error.kind === 'limit') {
        endpoint.rateLimited += 1;
        trip(endpoint, error.message);
      }

      if (error.ambiguous && method === 'eth_sendRawTransaction') ambiguousSend = true;
    }
  }
  throw rangeError || lastError || new Error('No RPC endpoint available');
}

// A range error from every endpoint means the filter spans too many blocks or logs: split and merge.
async function getLogs(params) {
  try {
    return await dispatch('logs', 'eth_getLogs', params);
  } catch (error) {
    const filter = params?.[0] || {};
    const from = parseBlock(filter.fromBlock);
    const to = parseBlock(filter.toBlock);
    if (error.kind !== 'range' || from == null || to == null || to - from + 1 <= minLogRange) throw error;
    const middle = from + Math.floor((to - from) / 2);
    const left = await getLogs([{ ...filter, fromBlock: toHex(from), toBlock: toHex(middle) }]);
    if (left.error) return left;
    const right = await getLogs([{ ...filter, fromBlock: toHex(middle + 1), toBlock: toHex(to) }]);
    if (right.error) return right;
    return { result: [...(left.result || []), ...(right.result || [])] };
  }
}

async function request(kind, method, params = []) {
  const cls = classify(method, kind);
  if (method === 'eth_chainId') return { result: toHex(chainId) };
  const key = cls === 'critical' ? null : `${method}:${JSON.stringify(params)}`;
  const cacheMs = method === 'eth_blockNumber' ? 2000
    : method === 'eth_call' && (cls === 'read' || cls === 'fallback') ? (currentMode() === BUDGET_MODES.normal ? readCacheMs : readCacheMs * 6) : 0;
  if (cacheMs) {
    const hit = cache.get(key);
    if (hit && hit.expiresAt > now()) return hit.value;
  }
  if (key && inflight.has(key)) return inflight.get(key);

  const task = (method === 'eth_getLogs' ? getLogs(params) : dispatch(cls, method, params)).then(value => {
    if (cacheMs && !value.error) {
      cache.set(key, { value, expiresAt: now() + cacheMs });
      if (cache.size > 2000) {
        const time = now();
        for (const [entryKey, entry] of cache) if (entry.expiresAt <= time) cache.delete(entryKey);
        while (cache.size > 2000) cache.delete(cache.keys().next().value);
      }
    }
    return value;
  });
  if (key) {
    inflight.set(key, task);
    task.finally(() => inflight.delete(key)).catch(() => {});
  }
  return task;
}

class TieredJsonRpcProvider extends JsonRpcProvider {
  constructor(kind) {
    const network = Network.from(chainId);
    super('http://127.0.0.1:0', network, { staticNetwork: network, batchMaxCount: 1 });
    this.rpcKind = kind;
  }

  async _send(payload) {
    const list = Array.isArray(payload) ? payload : [payload];
    return Promise.all(list.map(async item => {
      try {
        const outcome = await request(this.rpcKind, item.method, item.params);
        return outcome.error ? { id: item.id, error: outcome.error } : { id: item.id, result: outcome.result };
      } catch (error) {
        return { id: item.id, error: { code: -32603, message: `All RPC endpoints failed: ${error.message}` } };
      }
    }));
  }
}

const providers = {};
function provider(kind = 'read', consumer = '') {
  if (!['read', 'logs', 'critical'].includes(kind)) throw new Error(`Unknown RPC tier: ${kind}`);
  if (consumer) consumers[consumer] = kind;
  providers[kind] ||= new TieredJsonRpcProvider(kind);
  return providers[kind];
}

function health() {
  const time = now();
  return {
    chainId,

      tiers: { paid: paid.length, public: pub.length },
      consumers: { ...consumers },
      budget: budget(),
      computeUnits: {
        today: usage.day === new Date(time).toISOString().slice(0, 10) ? usage.dayCu : 0,
        lastMinute: usage.minute === Math.floor(time / 60_000) ? usage.minuteCu : 0,
        dailySoftLimit: Number.isFinite(dailyCuSoftLimit) ? dailyCuSoftLimit : null,
        overBudget: currentMode() !== BUDGET_MODES.normal,
        todayByMethod: usage.day === new Date(time).toISOString().slice(0, 10) ? { ...usage.byMethod } : {},
      },
      endpoints: endpoints.map(endpoint => ({
        label: endpoint.label,
        tier: endpoint.tier,
        requests: endpoint.requests,
        ok: endpoint.ok,
        failed: endpoint.failed,
        rateLimited: endpoint.rateLimited,
        p50Ms: percentile(endpoint.latencies, 0.5),
        p95Ms: percentile(endpoint.latencies, 0.95),
        breaker: endpoint.openUntil > time ? { open: true, retryInMs: endpoint.openUntil - time } : { open: false },
        lastError: endpoint.lastError,
      })),
    };
  }

  function describe() {
    return Object.entries(consumers).map(([name, kind]) => `${name}=${kind}`).join(', ');
  }

  function usageSnapshot() {
    return { month: usage.month, monthCu: usage.monthCu, day: usage.day, dayCu: usage.dayCu };
  }

  return { provider, request, health, describe, mode: currentMode, usageSnapshot, restoreUsage };
}

export const SUBMISSION_TIMEOUT_MS = 10 * 60 * 1000;
const DISCORD_UPLOAD_MAX_BYTES = 10 * 1024 * 1024;
const EPHEMERAL = 64;

function mediaTypeFor(filename = '', declaredType = '') {
  const extension = String(filename || '').split('.').pop().toLowerCase();
  return { mp3: 'audio/mpeg', m4a: 'audio/mp4', wav: 'audio/wav', ogg: 'audio/ogg',
    flac: 'audio/flac', aac: 'audio/aac', opus: 'audio/ogg', weba: 'audio/webm', mp4: 'video/mp4' }[extension] ||
    (['audio/mpeg', 'audio/mp4', 'audio/wav', 'audio/ogg', 'audio/flac', 'audio/aac', 'video/mp4', 'audio/webm'].includes(declaredType) ? declaredType : '');
}

export function submissionKey(messageId, attachmentId) {
  return `${messageId}__${attachmentId}`;
}

export function submissionMediaKind(attachment) {
  return mediaTypeFor(attachment?.name || '', attachment?.contentType || '') === 'video/mp4' ? 'video' : 'audio';
}

export function buildSubmissionPrompt({ filename, mediaKind }) {
  return `🎧 Got **${filename}** (${mediaKind}). What is it?`;
}

export function buildSubmissionButtons(key, defaultKind) {
  const primary = defaultKind === 'advert' ? 'advert' : 'song';
  return [{
    type: 1,
    components: [
      {
        type: 2,
        custom_id: `submission:choice:${key}:song`,
        label: 'Song',
        style: primary === 'song' ? 1 : 2,
      },
      {
        type: 2,
        custom_id: `submission:choice:${key}:advert`,
        label: 'Advert',
        style: primary === 'advert' ? 1 : 2,
      },
    ],
  }];
}

export function buildWalletButtons({ linkUrl, key }) {
  const components = [];
  if (linkUrl) {
    components.push({ type: 2, label: 'Link wallet', style: 5, url: linkUrl });
  }
  if (key) {

    components.push({ type: 2, custom_id: `submission:continue:${key}`, label: 'Continue', style: 1 });
  }
  return components.length ? [{ type: 1, components }] : [];
}

export function buildChangeButtons(key) {
  return [{ type: 1, components: [{ type: 2, custom_id: `submission:change:${key}`, label: 'Change', style: 2 }] }];
}

export function createSubmissionIntake({
  siteUrl = '',
  timeoutMs = SUBMISSION_TIMEOUT_MS,
  setTimer = setTimeout,
  clearTimer = clearTimeout,
  isAdmin = () => false,
  onChoose = async () => ({ handled: true }),
} = {}) {
  const pending = new Map();

  const finish = async (record, choice, interaction, extra = {}) => {
    const key = record.key;
    if (!extra.keepPending) {
      pending.delete(key);
      clearTimer(record.timer);
    }
    const result = await onChoose({ choice, record, interaction, ...extra });
    if ((result && result.keepPending) || extra.keepPending) pending.set(key, record);
    return result;
  };

  const prompt = async (message, attachment, defaultKind) => {
    const key = submissionKey(message.id, attachment.id);
    const record = {
      key,
      message,
      messageId: message.id,
      channelId: message.channelId,
      attachmentId: attachment.id,
      attachment,
      defaultKind,
      authorId: message.author.id,
      defaultUrl: siteUrl,
    };
    pending.set(key, record);
    record.timer = setTimer(() => {
      const current = pending.get(key);
      if (!current) return;
      finish(current, current.defaultKind, null, { timedOut: true }).catch(() => {});
    }, timeoutMs);
    record.timer?.unref?.();
    await message.reply({
      content: buildSubmissionPrompt({ filename: attachment.name || 'file', mediaKind: submissionMediaKind(attachment) }),

    components: buildSubmissionButtons(key, defaultKind),
    allowedMentions: { parse: [] },
  });
  return record;
};

return {
  pending,
  async prompt(message, attachment, defaultKind) {
    if (!attachment || !message) return null;
    if (attachment.size > DISCORD_UPLOAD_MAX_BYTES) {
      const components = siteUrl ? [{
        type: 1,
        components: [{ type: 2, label: 'Open DVert panel', style: 5, url: siteUrl }],
      }] : [];
      await message.reply({
        content: 'This file is too big for Discord. Upload it here:',
        components,
        allowedMentions: { parse: [] },
      }).catch(() => {});
      return null;
    }
    return prompt(message, attachment, defaultKind);
  },
  async handleInteraction(interaction) {
    if (!interaction.isButton?.() || !interaction.customId?.startsWith('submission:')) return false;
    const [, action, key, choice] = interaction.customId.split(':');
    const record = pending.get(key);
    if (!record) {
      await interaction.reply({ content: 'This upload is no longer pending.', flags: EPHEMERAL }).catch(() => {});
      return true;
    }
    const allowed = interaction.user.id === record.authorId || isAdmin(interaction);
    if (!allowed) {
      await interaction.reply({ content: 'Only the uploader can choose.', flags: EPHEMERAL }).catch(() => {});
      return true;
    }
    if (action === 'change') {
      pending.delete(key);
      clearTimer(record.timer);
      return onChoose({ choice: 'change', record, interaction });
    }
    if (action === 'continue') {
      return finish(record, record.defaultKind, interaction, { resume: true });
    }

      if (action === 'choice' && (choice === 'song' || choice === 'advert')) {
        return finish(record, choice, interaction);
      }
      return false;
    },
    complete(key) {
      const record = pending.get(key);
      if (!record) return null;
      pending.delete(key);
      clearTimer(record.timer);
      return record;
    },
  };
}

export function shouldHandleDevertLoopSubmission(message, { jukeboxChannelId, vertLoopChannelId, adIntakeEnabled = false } = {}) {
  if (!message || !message.channelId) return false;
  if (message.channelId === vertLoopChannelId && /^!devert-ad\b/i.test(message.content || '')) return true;
  if (message.channelId === jukeboxChannelId && /^!devert-ad\b/i.test(message.content || '')) return true;
  return false;
}

