  return { ...result, funds: Object.fromEntries(Object.entries(funds).map(([category, fund]) => [category,
    { ...fund, estimatedShares: fund.estimatedShares.filter(entry => entry.wallet?.toLowerCase() === key) }])), currentSongs: songs };
