export function createWeeklyPayrollReporter({ config, channelId, siteUrl, getWeeklyPayflow,
  getPaymentLedger, getReports, getChannel, restore, save, now = () => Date.now() }) {
  const records = new Map();
  let initialized = false;
  let dirty = false;

let pending = null;
let lastError = '';
let lastCheckedAt = null;
let waitingReason = '';

async function persist() {
  if (!dirty) return;
  const uri = await save({ schemaVersion: 1, chainId: 8453, routerAddress: config.routerAddress,
    channelId, reports: [...records.values()] });
  if (!/^ipfs:\/\//.test(uri)) throw new Error('Payroll announcement checkpoint did not return an IPFS URI');
  dirty = false;
}

async function initialize() {
  if (!restore || !save) throw new Error('Payroll announcements require durable checkpoint storage');
  const saved = await restore();
  if (saved) {
    if (saved.schemaVersion !== 1 || saved.chainId !== 8453 ||
        !same(saved.routerAddress, config.routerAddress) || saved.channelId !== channelId ||
        !Array.isArray(saved.reports)) throw new Error('Invalid payroll announcement checkpoint');
    for (const record of saved.reports) {
      if (!/^NY-\d{4}-\d{2}-\d{2}$/.test(record.week) || records.has(record.week) ||
          !snowflake(record.afterMessageId) || (record.messageId && !snowflake(record.messageId)) ||
          !/^0x[0-9a-f]{64}$/.test(record.allocationHash || '') ||
          record.payload?.embeds?.[0]?.footer?.text !== markerFor(record.week)) {
        throw new Error('Invalid payroll announcement record');
      }
      records.set(record.week, record);
    }
  }
  initialized = true;
}

function paymentsComplete(allocations, ledger, report) {
  const proofs = new Map(ledger.entries.map(entry => [entry.workReference, entry]));
  let complete = true;
  for (const record of allocations) {
    const allocation = record.allocation;
    validateRadioReceipt(allocation, { routerAddress: config.routerAddress,

      assetAddress: config.assets.USDC.address, funds: config.radioFunds, report });
    if (record.metadataHash !== id(JSON.stringify(allocation)) || !/^ipfs:\/\/[^/\s]+$/.test(record.metadataUri)) {
      throw new Error('Invalid payroll allocation proof');
    }
    for (const entry of allocation.entries) {
      const proof = proofs.get(id(entry.workReferenceText));
      if (!proof || proof.verification !== 'verified') { complete = false; continue; }
      if (proof.chainId !== 8453 || !same(proof.routerAddress, config.routerAddress) ||
          !same(proof.fundId, id(allocation.fundSlug)) || !same(proof.asset, allocation.assetAddress) ||
          !same(proof.recipient, entry.wallet) || proof.amountUnits !== entry.amountUnits ||
          proof.repositoryIdHash !== id('TheJollyLaMa/DecentBusking') ||
          proof.contributorIdHash !== id(`radio-artist:${entry.wallet.toLowerCase()}`) ||
          proof.metadataUri !== record.metadataUri || proof.metadataHash !== record.metadataHash) {
        throw new Error(`Payroll payment proof does not match ${entry.workReferenceText}`);
      }
    }
  }
  return complete;
}

async function findPosted(channel, record) {
  let before;
  for (;;) {
    const messages = await channel.messages.fetch({ limit: 100, ...(before ? { before } : {}) });
    if (!messages.size) return null;
    let oldest;
    for (const message of messages.values()) {
      if (message.author?.id === channel.client.user.id &&
          message.embeds?.some(embed => embed.footer?.text === markerFor(record.week))) return message;
      if (!oldest || BigInt(message.id) < BigInt(oldest)) oldest = message.id;
    }
    if (BigInt(oldest) <= BigInt(record.afterMessageId)) return null;

    if (before && BigInt(oldest) >= BigInt(before)) throw new Error('Discord announcement history did not advance');
    before = oldest;
  }
}

async function update() {
  if (!initialized) await initialize();
  await persist();
  lastCheckedAt = new Date(now()).toISOString();
  const weekly = await getWeeklyPayflow();
  const ledger = await getPaymentLedger();
  if (!weekly.ready || weekly.lastError || weekly.backupPending ||
      !ledger.ready || ledger.lastError || ledger.backupPending) {
    waitingReason = 'Waiting for healthy, backed-up weekly allocations and verified payment ledger';
    return;
  }
  if (ledger.chainId !== 8453 || !same(ledger.routerAddress, config.routerAddress)) {
    throw new Error('Payroll announcement ledger does not match Base router');
  }
  const weeks = [...new Set(weekly.allocations.map(record => record.allocation.week))]
    .filter(week => /^NY-\d{4}-\d{2}-\d{2}$/.test(week)).sort();
  waitingReason = 'Waiting for both published allocations and all their verified payments';
  for (const week of weeks) {
    if (records.get(week)?.messageId) continue;
    const allocations = weekly.allocations.filter(record => record.allocation.week === week);
    const playback = allocations.find(record => record.allocation.category === 'playback');
    const top10 = allocations.find(record => record.allocation.category === 'top10');
    if (!playback || !top10) continue;
    if (allocations.length !== 2) throw new Error('Duplicate weekly payroll allocations');
    if (top10.allocation.schemaVersion < 5) continue;
    if (Date.parse(playback.allocation.endAt) > now() || Date.parse(top10.allocation.endAt) > now()) continue;

    const report = (await getReports()).find(value => value.week === week);
    if (!allocations.every(record => radioAllocationMatchesReport(report, record.allocation))) {
      throw new Error(`Payroll report no longer matches frozen allocations for ${week}`);
    }
    if (!paymentsComplete(allocations, ledger, report)) continue;
    const channel = await getChannel();
    if (channel.id !== channelId || !channel.messages?.fetch || !channel.send || !channel.client?.user?.id) {
      throw new Error('Payroll announcement channel is unavailable or not a message channel');
    }
    const allocationHash = id(JSON.stringify([playback.metadataHash, top10.metadataHash]));
    let record = records.get(week);
    if (!record) {
      const latest = await channel.messages.fetch({ limit: 1 });
      record = { week, allocationHash, afterMessageId: latest.first()?.id || '0',
        payload: buildWeeklyPayrollReport({ playback, top10, report, siteUrl }) };
      records.set(week, record);
      dirty = true;
      await persist();
    }
    if (record.allocationHash !== allocationHash) throw new Error('Payroll allocations changed after announcement preparation');
    // Recover a successful send whose response or checkpoint was lost before trying another POST.
    const message = await findPosted(channel, record) || await channel.send({ ...record.payload,
      nonce: id(markerFor(week)).slice(2, 26), enforceNonce: true });
    if (!snowflake(message.id)) throw new Error('Discord did not return a payroll announcement message ID');
    record.messageId = message.id;
    record.sentAt = new Date(now()).toISOString();
    dirty = true;
    await persist();
    waitingReason = '';
  }
}

function tick() {

    if (!pending) pending = update().then(() => { lastError = ''; return getState(); })
      .catch(error => { lastError = error.message; throw error; }).finally(() => { pending = null; });
    return pending;
  }
  function getState() {
    return { ready: initialized, channelId, lastCheckedAt, lastError, backupPending: dirty, waitingReason,
      reports: [...records.values()].map(({ week, messageId, sentAt }) => ({ week,
        status: messageId ? 'sent' : 'prepared', messageId, sentAt })) };
  }
  return { tick, getState };
}

// Formats the public weekly usage receipt posted to the JukeLoop channel.
export function buildWeeklyPlayReportMessage(report) {
  const marker = `jukeloop-weekly-report:${report.week}`;
  const lines = [
    `## Weekly JukeLoop Play Report · ${report.week}`,
    `**${report.totalPlays} qualifying plays** across ${report.trackCount} songs. Weeks use UTC; plays require at least 30 audible seconds. This is a play count, not a payout statement.`,
  ];
  if (report.artists.length) {
    lines.push('', '**By artist**');
    for (const artist of report.artists.slice(0, 8)) lines.push(`• ${artist.artist}: **${artist.plays}** plays (${artist.tracks} songs)`);
  }
  if (report.tracks.length) {
    lines.push('', '**Top songs**');
    for (const track of report.tracks.slice(0, 8)) lines.push(`• ${track.title} — ${track.artist}: **${track.plays}**`);
  }
  lines.push('', `Receipt ID: \`${marker}\``);
  return lines.join('\n').slice(0, 1900);
}

import { Transaction, getAddress, keccak256 } from 'ethers';

export const WORKER_RESERVE_POLICY = Object.freeze({
  thresholdWei: 1_000_000_000_000_000n,
  targetWei: 3_000_000_000_000_000n,
  maxRefillWei: 2_000_000_000_000_000n,
  dailyCapWei: 6_000_000_000_000_000n,
});

export function createWorkerReserve({ provider, signer, workerAddress, restore, save, enabled = false,
  policy = WORKER_RESERVE_POLICY, maxNetworkFeeWei = 20_000_000_000_000n, now = () => Date.now() }) {
  const worker = getAddress(workerAddress);
  if (/^0x0{40}$/i.test(worker) || typeof maxNetworkFeeWei !== 'bigint' || maxNetworkFeeWei <= 0n) throw new Error('Invalid worker or network fee cap');
  if (typeof restore !== 'function' || typeof save !== 'function') throw new Error('Durable reserve journal required');
  if (Object.values(policy).some(value => typeof value !== 'bigint' || value <= 0n) ||
      policy.thresholdWei >= policy.targetWei || policy.maxRefillWei > policy.dailyCapWei) throw new Error('Invalid reserve caps');
  let state;
  let queue = Promise.resolve();
  const run = operation => {
    const task = queue.then(operation);
    queue = task.catch(() => {});
    return task;
  };
  const commit = async next => {
    const uri = await save(next);
    if (!/^ipfs:\/\//.test(uri || '')) throw new Error('Reserve journal did not confirm');
    state = next;
  };
  const verifyEntry = (entry, reserveAddress) => {
    const transaction = Transaction.from(entry.rawTransaction);
    const gasPrice = transaction.maxFeePerGas ?? transaction.gasPrice;
    if (transaction.chainId !== 8453n || transaction.to !== worker || transaction.data !== '0x' ||
        transaction.value !== BigInt(entry.valueWei) || transaction.value <= 0n || transaction.value > policy.maxRefillWei ||

      gasPrice == null || transaction.gasLimit <= 0n || transaction.gasLimit * gasPrice > maxNetworkFeeWei ||
      transaction.from?.toLowerCase() !== reserveAddress.toLowerCase() ||
      transaction.hash !== entry.hash || !/^\d{4}-\d{2}-\d{2}$/.test(entry.day) ||
      !['pending', 'confirmed', 'failed'].includes(entry.status)) throw new Error('Invalid reserve journal transfer');
};
return {
  check: () => run(async () => {
    if (Number((await provider.getNetwork()).chainId) !== 8453) throw new Error('Reserve funding is Base-only');
    const balance = await provider.getBalance(worker);
    if (!enabled) return { enabled: false, worker, balanceWei: balance.toString(),
      low: balance < policy.thresholdWei, reason: 'Reserve funding awaits explicit treasury approval' };
    if (!signer) throw new Error('Approved reserve signer is not configured');
    const reserveAddress = getAddress(await signer.getAddress());
    if (reserveAddress === worker) throw new Error('Worker cannot be its own reserve');
    if (!state) {
      const restored = await restore() || { schemaVersion: 1, reserveAddress, worker, refills: [] };
      if (restored.schemaVersion !== 1 || restored.reserveAddress !== reserveAddress || restored.worker !== worker ||
          !Array.isArray(restored.refills) || restored.refills.filter(entry => entry.status === 'pending').length > 1) {
        throw new Error('Invalid reserve journal');
      }
      restored.refills.forEach(entry => verifyEntry(entry, reserveAddress));
      const totals = new Map();
      for (const entry of restored.refills) totals.set(entry.day, (totals.get(entry.day) || 0n) + BigInt(entry.valueWei));

  if ([...totals.values()].some(total => total > policy.dailyCapWei)) throw new Error('Reserve journal exceeds daily cap');
  state = restored;
}
const pending = state.refills.find(entry => entry.status === 'pending');
if (pending) {
  const receipt = await provider.getTransactionReceipt(pending.hash);
  if (receipt) {
    await commit({ ...state, refills: state.refills.map(entry => entry.hash === pending.hash
      ? { ...entry, status: receipt.status === 1 ? 'confirmed' : 'failed' } : entry) });
    if (receipt.status !== 1) throw new Error(`Reserve refill reverted: ${pending.hash}`);
    return { enabled: true, confirmed: pending.hash };
  }
  if (await provider.getTransaction(pending.hash)) return { enabled: true, pending: pending.hash };
  const sent = await provider.broadcastTransaction(pending.rawTransaction);
  if (sent.hash !== pending.hash) throw new Error('Reserve broadcast hash mismatch');
  return { enabled: true, pending: pending.hash };
}
if (balance >= policy.thresholdWei) return { enabled: true, low: false, balanceWei: balance.toString() };
const day = new Date(now()).toISOString().slice(0, 10);
const used = state.refills.filter(entry => entry.day === day).reduce((sum, entry) => sum + BigInt(entry.valueWei), 0n);
const remaining = policy.dailyCapWei - used;
if (remaining <= 0n) throw new Error('Worker refill daily cap reached');
const value = [policy.targetWei - balance, policy.maxRefillWei, remaining].reduce((a, b) => a < b ? a : b);
const transaction = await signer.populateTransaction({ to: worker, value, chainId: 8453 });
const gasPrice = transaction.maxFeePerGas ?? transaction.gasPrice;

      if (gasPrice == null || transaction.gasLimit == null) throw new Error('Reserve gas budget unavailable');
      if (BigInt(transaction.gasLimit) * BigInt(gasPrice) > maxNetworkFeeWei) throw new Error('Reserve network fee exceeds cap');
      if (await provider.getBalance(reserveAddress) < value + BigInt(transaction.gasLimit) * BigInt(gasPrice)) {
        throw new Error('Approved ETH reserve cannot cover refill and network gas');
      }
      const rawTransaction = await signer.signTransaction(transaction);
      const entry = { rawTransaction, hash: keccak256(rawTransaction), valueWei: value.toString(), day, status: 'pending' };
      verifyEntry(entry, reserveAddress);
      await commit({ ...state, refills: [...state.refills, entry] });
      const sent = await provider.broadcastTransaction(rawTransaction);
      if (sent.hash !== entry.hash) throw new Error('Reserve broadcast hash mismatch');
      return { enabled: true, pending: entry.hash };
    }),
  };
}

