}

import { createBrowserIpfsUploader } from './ipfs-upload.js?v=20261015-mime-sniff';
import { canEditArtwork, extractArtworkPreviewUri, submitArtworkUpdateRequest, validateArtworkFile } from './artwork-update.mjs';

let _dialog;
let _current;
let _fileUrl = '';

function _status(message, state = '') {
  const el = _dialog?.querySelector('[data-artwork-status]');
  if (!el) return;
  el.textContent = message;
  el.classList.toggle('error', state === true || state === 'error');
  el.classList.toggle('success', state === 'success');
}

function _setBusy(busy) {
  const save = _dialog?.querySelector('[data-artwork-save]');
  const file = _dialog?.querySelector('[data-artwork-file]');
  _dialog?.classList.toggle('is-busy', busy);
  if (save) save.disabled = busy || !file?.files?.length || _dialog.classList.contains('is-done');
  if (file) file.disabled = busy;
}

function _setFileName(file) {
  const name = _dialog?.querySelector('[data-artwork-file-name]');
  if (name) name.textContent = file ? file.name : 'PNG, JPG, WebP or GIF';
}

function _previewCurrent(nft) {
  const image = _dialog?.querySelector('[data-artwork-current-preview]');
  if (!image) return;
  image.src = extractArtworkPreviewUri(nft, window.DecentConfig?.ipfsGateway || 'https://gateway.pinata.cloud/ipfs/');
}

function _previewNew(file) {
  const image = _dialog?.querySelector('[data-artwork-new-preview]');
  if (!image) return;
  if (_fileUrl) URL.revokeObjectURL(_fileUrl);
  _fileUrl = file ? URL.createObjectURL(file) : '';
  if (file) image.src = _fileUrl;
  else image.removeAttribute('src');
  image.hidden = !file;
  const placeholder = _dialog?.querySelector('[data-artwork-new-placeholder]');
  if (placeholder) placeholder.hidden = Boolean(file);

  _dialog?.querySelector('.artwork-editor-frame.is-new')?.classList.toggle('has-image', Boolean(file));
}

function _close() {
  if (_fileUrl) URL.revokeObjectURL(_fileUrl);
  _fileUrl = '';
  _current = null;
  _dialog?.close();
}

async function _save() {
  if (!_current) return;
  const cfg = window.DecentConfig || {};
  const signer = window._wallet?.signer;
  const address = window._wallet?.address;
  if (!canEditArtwork(_current, address)) throw new Error('Connect the creator wallet to edit this artwork');
  const file = _dialog?.querySelector('[data-artwork-file]')?.files?.[0];
  validateArtworkFile(file);
  const uploader = createBrowserIpfsUploader({
    provider: cfg.ipfsUploadProvider || 'pinata',
    serviceUrl: cfg.ipfsUploadServiceUrl,
    ipfsApiUrl: cfg.ipfsApiUrl,
    signer,
    address,
    origin: window.location.origin,
    purpose: 'submission',
  });
  _status('Uploading artwork…');
  const artworkUri = await uploader(file, { onProgress: progress => {
    _status(`Uploading artwork… ${Math.round(progress.progress * 100)}%`);
  }});
  _status('Submitting request for review…');
  const response = await submitArtworkUpdateRequest({
    serviceUrl: cfg.ipfsUploadServiceUrl,
    signer,
    address,
    origin: window.location.origin,
    request: {
      chainId: _current.chainId || cfg.chainId || 8453,
      contractAddress: _current.contractAddress || cfg.contractAddress,
      tokenId: _current.tokenId,
      artworkCid: artworkUri,
    },
  });
  _status('✅ Submitted! An admin will approve it from the mint queue.', 'success');
  _dialog?.classList.add('is-done');
  document.dispatchEvent(new CustomEvent('artwork-update-requested', { detail: { nft: _current, request: response.request } }));
}

function _open(detail = {}) {

  const nft = detail.nft || detail;
  if (!nft || !canEditArtwork(nft, window._wallet?.address)) return;
  _current = nft;
  const file = _dialog?.querySelector('[data-artwork-file]');
  if (file) file.value = '';
  _dialog?.classList.remove('is-done', 'is-busy');
  _previewCurrent(nft);
  _previewNew(null);
  _setFileName(null);
  _setBusy(false);
  _status('Choose a new image to continue.');
  _dialog?.showModal();
}

function initArtworkEditor() {
  _dialog = document.getElementById('nft-artwork-editor');
  if (!_dialog) return;
  _dialog.querySelector('[data-artwork-editor-close]')?.addEventListener('click', _close);
  _dialog.querySelector('[data-artwork-save]')?.addEventListener('click', () => {
    _setBusy(true);
    _save()
      .catch(error => _status(error.message, 'error'))
      .finally(() => _setBusy(false));
  });
  _dialog.querySelector('[data-artwork-file]')?.addEventListener('change', event => {
    const file = event.target.files?.[0];
    _dialog.classList.remove('is-done');
    _setFileName(file);
    _setBusy(false);
    if (!file) {
      _previewNew(null);
      _status('Choose a new image to continue.');
      return;
    }
    try {
      validateArtworkFile(file);
      _previewNew(file);
      _status('Looking good! Sign & submit when ready.');
    } catch (error) {
      _previewNew(null);
      _status(error.message, 'error');
    }
  });
  _dialog.addEventListener('close', () => {
    if (_fileUrl) URL.revokeObjectURL(_fileUrl);
    _fileUrl = '';
  });
  _dialog.addEventListener('cancel', event => {
    event.preventDefault();
    _close();
  });
  document.addEventListener('open-artwork-editor', event => _open(event.detail));
}

document.addEventListener('DOMContentLoaded', initArtworkEditor);

const MAX_ARTWORK_BYTES = 10 * 1024 * 1024;
const ACCEPTED_ARTWORK_TYPES = ['image/png', 'image/jpeg', 'image/webp', 'image/gif'];

export function buildArtworkUpdateAuthorizationMessage({
  address, origin, chainId = 8453, contractAddress, tokenId, artworkCid, nonce, issuedAt, expiresAt,
}) {
  return [
    'DecentBusking artwork update request',
    `Wallet: ${address.toLowerCase()}`,
    `Origin: ${origin}`,
    `Chain ID: ${chainId}`,
    `Contract: ${contractAddress.toLowerCase()}`,
    `Token ID: ${String(tokenId)}`,
    `Artwork CID: ${artworkCid}`,
    `Nonce: ${nonce}`,
    `Issued At: ${issuedAt}`,
    `Expires At: ${expiresAt}`,
  ].join('\n');
}

export function buildArtworkUpdateMetadata(metadata = {}, imageUri) {
  return { ...metadata, image: imageUri };
}

export function canEditArtwork(nft = {}, walletAddress = '', linkedWallet = '') {
  const creator = String(nft.creator || nft.artist || '').toLowerCase();
  const wallet = String(walletAddress || '').toLowerCase();
  const linked = String(linkedWallet || '').toLowerCase();
  return !!creator && (creator === wallet || creator === linked);
}

export function validateArtworkFile(file) {
  if (!file) throw new Error('Choose a PNG, JPEG, WebP, or GIF file up to 10 MB');
  if (!Number.isSafeInteger(file.size) || file.size < 1 || file.size > MAX_ARTWORK_BYTES || !ACCEPTED_ARTWORK_TYPES.includes(file.type)) {
    throw new Error('Artwork must be PNG, JPEG, WebP, or GIF up to 10 MB');
  }
}

export async function submitArtworkUpdateRequest({
  serviceUrl,
  signer,
  address,
  origin,
  request,
  fetchImpl = globalThis.fetch,
  now = () => Date.now(),
}) {
  if (!serviceUrl || !signer || !address) throw new Error('Connect the creator wallet before updating artwork');

  const issuedAt = new Date(now()).toISOString();
  const expiresAt = new Date(now() + 5 * 60 * 1000).toISOString();
  const payload = {
    address,
    origin,
    issuedAt,
    expiresAt,
    nonce: crypto.randomUUID(),
    chainId: Number(request.chainId || 8453),
    contractAddress: request.contractAddress,
    tokenId: Number(request.tokenId),
    artworkCid: String(request.artworkCid || '').trim().replace(/^ipfs:\/\//i, ''),
  };
  const signature = await signer.signMessage(buildArtworkUpdateAuthorizationMessage(payload));
  const response = await fetchImpl(`${serviceUrl.replace(/\/$/, '')}/api/artwork-update`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ ...payload, signature }),
    signal: AbortSignal.timeout(30000),
  });
  const result = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(result.error || `Artwork update request failed (${response.status})`);
  return result;
}

export async function completeArtworkUpdateRequest({
  serviceUrl,
  signer,
  address,
  origin,
  requestId,
  txHash,
  fetchImpl = globalThis.fetch,
  now = () => Date.now(),
}) {
  const issuedAt = new Date(now()).toISOString();
  const authorization = { address, origin, issuedAt };
  const signature = await signer.signMessage([
    'DecentBusking admin mint queue',
    `Wallet: ${address.toLowerCase()}`,
    `Origin: ${origin}`,
    `Issued At: ${issuedAt}`,
  ].join('\n'));
  const response = await fetchImpl(`${serviceUrl.replace(/\/$/, '')}/api/artwork-update-complete`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ ...authorization, signature, requestId, txHash }),
    signal: AbortSignal.timeout(30000),
  });

  const result = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(result.error || `Artwork update completion failed (${response.status})`);
  return result;
}

export async function rejectArtworkUpdateRequest({
  serviceUrl,
  signer,
  address,
  origin,
  requestId,
  reason = 'rejected',
  fetchImpl = globalThis.fetch,
  now = () => Date.now(),
}) {
  const issuedAt = new Date(now()).toISOString();
  const authorization = { address, origin, issuedAt };
  const signature = await signer.signMessage([
    'DecentBusking admin mint queue',
    `Wallet: ${address.toLowerCase()}`,
    `Origin: ${origin}`,
    `Issued At: ${issuedAt}`,
  ].join('\n'));
  const response = await fetchImpl(`${serviceUrl.replace(/\/$/, '')}/api/artwork-update-reject`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ ...authorization, signature, requestId, reason }),
    signal: AbortSignal.timeout(30000),
  });
  const result = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(result.error || `Artwork update rejection failed (${response.status})`);
  return result;
}

export function extractArtworkPreviewUri(nft = {}, gateway = 'https://gateway.pinata.cloud/ipfs/') {
  const image = String(nft.image || nft.imageUrl || nft.thumbnailUrl || '').trim();
  if (!image) return '';
  if (image.startsWith('ipfs://')) return image.replace('ipfs://', `${gateway.replace(/\/$/, '')}/`);
  return image;
}

export const BASE_CHAIN_ID = 8453;
export const BASE_CHAIN_HEX = `0x${BASE_CHAIN_ID.toString(16)}`;

const BASE_CHAIN_PARAMS = {
  chainId: BASE_CHAIN_HEX,
  chainName: 'Base',
  nativeCurrency: { name: 'Ether', symbol: 'ETH', decimals: 18 },
  rpcUrls: ['https://mainnet.base.org'],
  blockExplorerUrls: ['https://basescan.org'],
};

export async function ensureBaseNetwork(provider) {
  if (Number((await provider.getNetwork()).chainId) === BASE_CHAIN_ID) return;
  if (typeof window === 'undefined' || !window.ethereum?.request) throw new Error('Switch your wallet to Base');
  try {
    await window.ethereum.request({ method: 'wallet_switchEthereumChain', params: [{ chainId: BASE_CHAIN_HEX }] });
  } catch (error) {
    if (error.code !== 4902) throw error;
    await window.ethereum.request({ method: 'wallet_addEthereumChain', params: [BASE_CHAIN_PARAMS] });
  }
  if (Number((await provider.getNetwork()).chainId) !== BASE_CHAIN_ID) {
    throw new Error('Switch your wallet to Base');
  }
}

// Shown before every token approval so a wallet security banner doesn't surprise users.
export function approvalNotice(amountText, { workerContribution = true } = {}) {
  const amount = String(amountText).replace(/\s*USDC$/i, '');
  return `Set a spending allowance of exactly ${amount} USDC. Approval does not purchase playback. Review the separate purchase transaction for its USDC total, ${workerContribution ? 'any worker ETH contribution, and ' : 'and '}wallet network gas before confirming.`;
}

export async function waitForAllowance(token, owner, spender, minimumAmount, { retries = 10, delayMs = 50 } = {}) {
  for (let attempt = 0; attempt < retries; attempt++) {
    if (await token.allowance(owner, spender) >= minimumAmount) return;

    if (attempt + 1 < retries) await new Promise(resolve => setTimeout(resolve, delayMs));
  }
  throw new Error('Waiting for approval to confirm timed out');
}

export function isMissingRevertData(error) {
  return error?.code === 'CALL_EXCEPTION' && /missing revert data/i.test(String(error?.message || ''));
}

export async function retryMissingRevertData(action, refresh) {
  try {
    return await action();
  } catch (error) {
    if (!isMissingRevertData(error)) throw error;
    if (refresh) await refresh();
    return action();
  }
}

// ── Read-only Base RPC for the browser (#205) ──
// Public endpoints first (free), each behind a small circuit breaker; if every public endpoint fails,
// fall back to the worker's /api/rpc proxy, which can use the paid tier without exposing its key.
export const DEFAULT_PUBLIC_BASE_RPC_URLS = Object.freeze([
  'https://base-rpc.publicnode.com',
  'https://mainnet.base.org',
  'https://base.gateway.tenderly.co',
  'https://base.drpc.org',
]);
const RATE_LIMIT_CODES = new Set([-32005, -32011, -32016, -32090, 429]);
const RATE_LIMIT_TEXT = /rate limit|request limit|too many|exceeded|capacity|throttl|personal token|free plan|timeout/i;
const READ_BATCH_MAX = 10;

export function baseReadEndpoints(config = globalThis.window?.DecentConfig || {}) {
  const publicUrls = [...new Set([config.rpcUrl, ...(config.rpcFallbackUrls || []), ...DEFAULT_PUBLIC_BASE_RPC_URLS]
    .map(url => String(url || '').trim()).filter(url => /^https:\/\//.test(url)))];
  const service = String(config.ipfsUploadServiceUrl || '').replace(/\/$/, '');
  return { publicUrls, workerUrl: /^https?:\/\//.test(service) ? `${service}/api/rpc` : '' };
}

function isLimitError(error) {

  return RATE_LIMIT_CODES.has(Number(error?.code)) || RATE_LIMIT_TEXT.test(String(error?.message || ''));
}

export function createBaseRpcTransport({
  publicUrls = [],
  workerUrl = '',
  fetchImpl = globalThis.fetch?.bind(globalThis),
  now = () => Date.now(),
  timeoutMs = 6000,
  workerTimeoutMs = 15000,
  breakerBaseMs = 30_000,
  breakerMaxMs = 5 * 60_000,
} = {}) {
  const endpoints = publicUrls.map(url => ({ url, openUntil: 0, strikes: 0 }));
  const worker = workerUrl ? { url: workerUrl, openUntil: 0, strikes: 0, worker: true } : null;

  function trip(endpoint) {
    endpoint.strikes += 1;
    endpoint.openUntil = now() + Math.min(breakerMaxMs, breakerBaseMs * 2 ** (endpoint.strikes - 1));
  }

  async function post(endpoint, payload) {
    const controller = typeof AbortController === 'function' ? new AbortController() : null;
    const timer = controller ? setTimeout(() => controller.abort(), endpoint.worker ? workerTimeoutMs : timeoutMs) : null;
    try {
      const response = await fetchImpl(endpoint.url, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify(payload),
        ...(controller ? { signal: controller.signal } : {}),
      });
      const body = await response.json().catch(() => null);
      if (!response.ok || body == null) throw Object.assign(new Error(`HTTP ${response.status}`), { body });
      const list = Array.isArray(body) ? body : [body];
      if (list.some(item => item?.error && isLimitError(item.error))) throw new Error('rate limited');
      return list;
    } finally {
      if (timer) clearTimeout(timer);
    }
  }

  // payload: one JSON-RPC request or a batch; resolves to an array of responses matched by id.
  async function send(payload) {

    const items = Array.isArray(payload) ? payload : [payload];
    const time = now();
    const ready = endpoints.filter(endpoint => endpoint.openUntil <= time);
    const order = [...ready, ...(worker ? [worker] : []), ...endpoints.filter(endpoint => endpoint.openUntil > time)];
    let lastError = null;
    for (const endpoint of order) {
      if (endpoint.worker && endpoint.openUntil > now()) continue;
      try {
        const results = await post(endpoint, Array.isArray(payload) ? items : items[0]);
        endpoint.strikes = 0;
        endpoint.openUntil = 0;
        return results;
      } catch (error) {
        lastError = error;
        trip(endpoint);
      }
    }
    throw new Error(`Base RPC unavailable${lastError?.message ? ` (${lastError.message})` : ''}`);
  }

  function health() {
    const time = now();
    return [...endpoints, ...(worker ? [worker] : [])].map(endpoint => ({
      host: new URL(endpoint.url).host, worker: !!endpoint.worker, open: endpoint.openUntil > time, strikes: endpoint.strikes,
    }));
  }

  return { send, health };
}

const readProviders = new Map();

// Shared ethers v6 provider for read-only Base calls in the browser. Never use it to send transactions.
export function getBaseReadProvider({ ethers = globalThis.window?.ethers || globalThis.ethers, config, fetchImpl } = {}) {
  if (!ethers?.JsonRpcProvider) return null;
  const endpoints = baseReadEndpoints(config || globalThis.window?.DecentConfig || {});
  if (typeof ethers.Network?.from !== 'function') return new ethers.JsonRpcProvider(endpoints.publicUrls[0]);
  const cacheKey = JSON.stringify(endpoints);
  if (!fetchImpl && readProviders.get(cacheKey)?.ethers === ethers) return readProviders.get(cacheKey).provider;

  const transport = createBaseRpcTransport({ ...endpoints, ...(fetchImpl ? { fetchImpl } : {}) });
  const network = ethers.Network.from(BASE_CHAIN_ID);
  class BaseReadProvider extends ethers.JsonRpcProvider {
    constructor() {
      super('https://base-rpc.invalid', network, { staticNetwork: network, batchMaxCount: READ_BATCH_MAX });
      this.transport = transport;
    }

    async _send(payload) {
      const items = Array.isArray(payload) ? payload : [payload];
      if (items.length === 1 && items[0].method === 'eth_chainId') return [{ id: items[0].id, result: BASE_CHAIN_HEX }];
      try {
        const results = await transport.send(items);
        const byId = new Map(results.map(result => [String(result?.id), result]));
        return items.map(item => byId.get(String(item.id)) || { id: item.id, error: { code: -32603, message: 'Missing RPC response' } });
      } catch (error) {
        return items.map(item => ({ id: item.id, error: { code: -32603, message: error.message } }));
      }
    }
  }
  const provider = new BaseReadProvider();
  if (!fetchImpl) {
    // Shared across modules: callers may still call destroy(), which must not break everyone else.
    provider.destroy = () => {};
    readProviders.set(cacheKey, { ethers, provider });
  }
  return provider;
}

import { pinCommunityManifest } from './pinner-rewards.mjs';

export function initCommunityPinning({ fetchImpl = fetch } = {}) {
  const dialog = document.getElementById('community-pin-dialog');
  if (!dialog) return;
  const summary = document.getElementById('community-pin-summary');
  const progress = document.getElementById('community-pin-progress');
  const start = document.getElementById('community-pin-start');
  const key = document.getElementById('community-pin-key');
  const keyLabel = document.getElementById('community-pin-key-label');
  const rewardStatus = document.getElementById('community-pin-rewards-status');
  let manifest = null;
  let busy = false;
  const provider = () => document.querySelector('[name="community-pin-provider"]:checked')?.value || 'local';

  async function loadManifest() {
    manifest = null;
    start.disabled = true;
    summary.textContent = 'Loading the shared content manifest…';
    const service = (window.DecentConfig?.ipfsUploadServiceUrl || '').replace(/\/$/, '');
    if (!service) { summary.textContent = 'Community pin manifest is not configured.'; return; }
    try {
      const response = await fetchImpl(`${service}/api/pinners/manifest`, { cache: 'no-store', signal: AbortSignal.timeout(15000) });
      const value = await response.json();
      if (!response.ok) throw new Error(value.error || `HTTP ${response.status}`);
      if (value.schemaVersion !== 1 || !Array.isArray(value.entries)) throw new Error('Invalid pin manifest');
      manifest = value;
      summary.textContent = `${value.entryCount} unique CIDs · shared playlist, songs and albums`;
      rewardStatus.textContent = value.rewardStatus === 'not-active'
        ? 'Shared Pinata stays primary. Rewards are not active yet.' : value.rewardStatus;

    start.disabled = !value.entryCount;
  } catch (error) { summary.textContent = `Manifest unavailable: ${error.message}`; }
}

function updateProvider() {
  const pinata = provider() === 'pinata';
  key.hidden = !pinata;
  keyLabel.hidden = !pinata;
  start.textContent = pinata ? 'Pin to my Pinata' : 'Pin to IPFS Desktop';
  if (!busy) start.disabled = !manifest?.entryCount || (pinata && !key.value.trim());
}

document.querySelectorAll('[name="community-pin-provider"]').forEach(input => input.addEventListener('change', updateProvider));
key.addEventListener('input', updateProvider);
window.addEventListener('open-community-pinning', async () => {
  if (!dialog.open) dialog.showModal();
  await loadManifest();
  updateProvider();
});
document.getElementById('community-pin-cancel').addEventListener('click', () => { key.value = ''; dialog.close(); updateProvider(); });
start.addEventListener('click', async () => {
  if (!manifest || busy) return;
  busy = true;
  updateProvider();
  const selectedProvider = provider();
  const pinataJwt = selectedProvider === 'pinata' ? key.value.trim() : '';
  try {
    const result = await pinCommunityManifest({ manifest, provider: selectedProvider, pinataJwt,
      ipfsApiUrl: window.DecentConfig?.ipfsApiUrl || 'http://127.0.0.1:5001', fetchImpl,
      onProgress: ({ completed, total }) => { progress.textContent = `Pinned ${completed} of ${total} CIDs…`; } });
    progress.textContent = `Pinned ${result.successes.length} of ${manifest.entryCount}. ${result.failures.length ? `${result.failures.length} could not be pinned; try again later.` : 'All selected CIDs are pinned.'}`;

      rewardStatus.textContent = 'Your pins add a community copy. Availability rewards are not active yet.';
    } catch (error) { progress.textContent = error.message; }
    finally { key.value = ''; busy = false; updateProvider(); }
  });
  dialog.addEventListener('close', () => { key.value = ''; });
  updateProvider();
}

if (typeof document !== 'undefined') document.addEventListener('DOMContentLoaded', () => initCommunityPinning(), { once: true });

