`;

let _badgePollTimer = 0;
let _badgeRoot = null;
let _badge = null;
let _currentCount = 0;

function patchAppTitle() {
  const cls = customElements.get('app-title');
  if (!cls) return;

  const originalRender = cls.prototype.render;
  cls.prototype.render = function () {

    originalRender.call(this);
    _injectAdminLink(this.shadowRoot);
    _ensureMintBadge(this.shadowRoot);
  };

  _findAllAppTitles().forEach(el => {
    _injectAdminLink(el.shadowRoot);
    _ensureMintBadge(el.shadowRoot);
  });
}

function _injectAdminLink(shadowRoot) {
  if (!shadowRoot) return;
  const leftMenu = shadowRoot.querySelector('.ankh-left .dropdown-menu');
  if (!leftMenu) return;
  if (leftMenu.querySelector('[data-admin-item]')) return;

  _injectStyle(shadowRoot);

  const li = document.createElement('li');
  li.className = 'admin-nav-item';
  li.dataset.adminItem = '1';
  li.textContent = '🔑 Admin';

  li.addEventListener('click', e => {
    e.stopPropagation();
    leftMenu.style.display = 'none';
    document.dispatchEvent(new CustomEvent('open-admin'));
  });

  leftMenu.appendChild(li);
}

function _injectStyle(shadowRoot) {
  if (!shadowRoot || shadowRoot.querySelector('#admin-nav-style')) return;
  const style = document.createElement('style');
  style.id = 'admin-nav-style';
  style.textContent = ADMIN_LINK_STYLE;
  shadowRoot.appendChild(style);
}

function _ensureMintBadge(shadowRoot) {
  if (!shadowRoot) return;
  _badgeRoot = shadowRoot;
  _injectStyle(shadowRoot);
  const leftAnkh = shadowRoot.querySelector('.ankh-left');
  if (!leftAnkh) return;
  if (!_badge) {
    _badge = document.createElement('span');
    _badge.className = 'admin-mint-count-badge';
    _badge.hidden = true;
    _badge.setAttribute('aria-hidden', 'true');
    leftAnkh.appendChild(_badge);
  } else if (_badge.parentElement !== leftAnkh) {
    leftAnkh.appendChild(_badge);
  }

  _applyCount(_currentCount);
}

function _applyCount(count) {
  _currentCount = Number.isSafeInteger(count) && count > 0 ? count : 0;
  if (!_badge) return;
  _badge.textContent = _currentCount > 0 ? String(_currentCount) : '';
  _badge.hidden = _currentCount <= 0;
  _badge.classList.toggle('is-pending', _currentCount > 0);
}

async function _refreshPendingCount() {
  const config = window.DecentConfig || {};
  const owner = (config.adminWalletAddress || config.mintOwnerWallet || '').toLowerCase();
  const connected = (window._wallet?.address || '').toLowerCase();
  if (!owner || connected !== owner || !config.ipfsUploadServiceUrl) {
    _applyCount(0);
    document.dispatchEvent(new CustomEvent('mint-queue-count-updated', { detail: { count: 0 } }));
    return;
  }
  try {
    const response = await fetch(`${config.ipfsUploadServiceUrl.replace(/\/$/, '')}/api/mint-queue/pending-count`, { cache: 'no-store' });
    const payload = await response.json().catch(() => ({}));
    if (!response.ok || !Number.isSafeInteger(payload.count)) throw new Error(payload.error || 'Pending mint count unavailable');
    _applyCount(payload.count);
    document.dispatchEvent(new CustomEvent('mint-queue-count-updated', { detail: { count: payload.count } }));
  } catch (error) {
    console.warn('[mint-queue-badge]', error.message);
  }
}

function _syncPolling() {
  clearInterval(_badgePollTimer);
  _badgePollTimer = 0;
  if (!window._wallet?.address) {
    _applyCount(0);
    return;
  }
  void _refreshPendingCount();
  const owner = (window.DecentConfig?.adminWalletAddress || window.DecentConfig?.mintOwnerWallet || '').toLowerCase();
  if ((window._wallet.address || '').toLowerCase() === owner && window.DecentConfig?.ipfsUploadServiceUrl) {

    _badgePollTimer = window.setInterval(() => { void _refreshPendingCount(); }, 5 * 60 * 1000);
  } else {
    _applyCount(0);
  }
}

function _findAllAppTitles() {
  const found = [];
  function walk(root) {
    root.querySelectorAll('app-title').forEach(el => found.push(el));
    root.querySelectorAll('*').forEach(el => {
      if (el.shadowRoot) walk(el.shadowRoot);
    });
  }
  walk(document);
  return found;
}

if (customElements.get('app-title')) {
  patchAppTitle();
} else {
  customElements.whenDefined('app-title').then(patchAppTitle);
}

document.addEventListener('wallet-connected', _syncPolling);
document.addEventListener('wallet-disconnected', _syncPolling);
document.addEventListener('mint-queue-count-updated', event => {
  if (_badgeRoot) _ensureMintBadge(_badgeRoot);
  _applyCount(event.detail?.count);
});

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => _syncPolling(), { once: true });
} else {
  _syncPolling();
}

// js/components/header-payroll-inject.js — DecentBusking
//
// Injects a "💸 Payroll" link into AppTitle's left ankh dropdown
// (the ☥ icon on the left side of the shared header component).
//
// Uses the same prototype-patching pattern as about-override.js so the
// injection survives any future re-renders of the AppTitle component.
// The button dispatches a custom "open-payroll" DOM event that payroll.js
// listens for — keeping the shadow-DOM boundary fully decoupled.

// Styles injected into the AppTitle shadow root. Inline styles are avoided
// in favour of a scoped <style> element so rules stay maintainable and
// consistent with the app's CSS custom properties.
import { isAdminWallet } from '../admin-access.mjs';

const PAYROLL_LINK_STYLE = `
  .payroll-nav-item {
    list-style: none;
    padding: 0.45rem 1rem;
    cursor: pointer;
    white-space: nowrap;
    color: #f0c040;
    font-size: 0.9rem;
    transition: background 0.15s;
  }
  .payroll-nav-item:hover {
    background: rgba(240, 192, 64, 0.12);
  }
  .payroll-nav-item[hidden] { display: none; }
`;

function patchAppTitle() {
  const cls = customElements.get('app-title');
  if (!cls) return;

  // Wrap render() so every future call also injects the Payroll link.
  const originalRender = cls.prototype.render;
  cls.prototype.render = function () {
    originalRender.call(this);
    _injectPayrollLink(this.shadowRoot);
  };

  // Inject into any AppTitle instances already rendered in the DOM.
  _findAllAppTitles().forEach(el => _injectPayrollLink(el.shadowRoot));
}

function _injectPayrollLink(shadowRoot) {
  if (!shadowRoot) return;

  const leftMenu = shadowRoot.querySelector('.ankh-left .dropdown-menu');
  if (!leftMenu) return;

  // Don't inject twice.

  if (leftMenu.querySelector('[data-payroll-item]')) return;

  // Inject scoped styles if not already present.
  if (!shadowRoot.querySelector('#payroll-nav-style')) {
    const style = document.createElement('style');
    style.id = 'payroll-nav-style';
    style.textContent = PAYROLL_LINK_STYLE;
    shadowRoot.appendChild(style);
  }

  // The CDN AppTitle's left dropdown currently contains only placeholder
  // items ("Option1", "Option 2"). We replace those with real navigation
  // links so the dropdown has meaningful content. If the CDN component
  // is later updated to include real items, this section should be revised
  // to append instead of replace.
  leftMenu.innerHTML = '';

  const historyItem = document.createElement('li');
  historyItem.className = 'payroll-nav-item';
  historyItem.dataset.playHistoryTotalsItem = '1';
  historyItem.textContent = 'Playback Tally';
  historyItem.addEventListener('click', (event) => {
    event.stopPropagation();
    leftMenu.style.display = 'none';
    document.dispatchEvent(new CustomEvent('open-radio-history', { detail: { mode: 'totals' } }));
  });
  leftMenu.appendChild(historyItem);
  for (const [label, eventName, datasetKey] of [
    ['Admin Nft Mint', 'open-admin', 'adminItem'], ['Payroll', 'open-payroll', 'payrollItem'],
  ]) {
    const item = document.createElement('li');
    item.className = 'payroll-nav-item';
    item.dataset[datasetKey] = '1';
    item.dataset.adminOnly = '1';
    item.textContent = label;
    item.hidden = !isAdminWallet();
    item.addEventListener('click', event => {
      event.stopPropagation();
      if (!isAdminWallet()) return;
      leftMenu.style.display = 'none';
      document.dispatchEvent(new CustomEvent(eventName));
    });
    leftMenu.appendChild(item);
  }
}

// Shadow-DOM aware traversal — same helper pattern as about-override.js.
function _findAllAppTitles() {
  const found = [];
  function walk(root) {
    root.querySelectorAll('app-title').forEach(el => found.push(el));
    root.querySelectorAll('*').forEach(el => {
      if (el.shadowRoot) walk(el.shadowRoot);
    });
  }
  walk(document);
  return found;
}

// Bootstrap — patch immediately if already defined, otherwise wait.
if (customElements.get('app-title')) {
  patchAppTitle();
} else {
  customElements.whenDefined('app-title').then(patchAppTitle);
}

function updateAdminItems() {
  for (const title of _findAllAppTitles()) {
    title.shadowRoot?.querySelectorAll('[data-admin-only]').forEach(item => { item.hidden = !isAdminWallet(); });
  }
}
document.addEventListener('wallet-connected', updateAdminItems);
document.addEventListener('wallet-disconnected', updateAdminItems);

