export const DEVERT_MINIMUM_BID_INCREMENT = 10_000n;
export const DEVERT_CAMPAIGN_WEEK_MS = 7 * 24 * 60 * 60 * 1000;
export const DEVERT_SONGS_PER_MAIN_AD = 10;
