      art.append(image);
    } else {
      art.append(node('span', String(ad.title || 'AD').slice(0, 2).toUpperCase(), 'devert-library-fallback'));
    }
    const body = node('span', undefined, 'devert-library-copy');
    body.append(node('strong', ad.title), node('span',
