    ${hasBudget ? '' : `<span class="fund-prize-caption">${indexing ? 'History is still indexing &middot; weekly budget unavailable' : 'Weekly budget unavailable'}</span>`}
    <span class="fund-prize-orbit" aria-hidden="true">${dollars}</span>
