  const position = djukeCalloutPosition(anchor.getBoundingClientRect(),
    { width: windowRef.innerWidth, height: windowRef.innerHeight }, shell.getBoundingClientRect().height || 230);
  root.style.setProperty('--djuke-callout-width', `${position.width}px`);
  root.style.setProperty('--djuke-callout-left', `${position.left}px`);
  root.style.setProperty('--djuke-callout-top', `${position.top}px`);
};

const hide = () => {
  clearTimeout(state.timer);
  state.timer = null;
  root.hidden = true;
  root.dataset.effect = '';
  root.dataset.phase = '';
  stage.hidden = false;
  stage.replaceChildren();
};

const showNext = () => {
  if (state.timer || !queue.length) return;
  const detail = queue.shift();
  const modal = detail.source === 'djuke' ? documentRef.querySelector?.('dialog[open]') : null;
  (modal || documentRef.body).appendChild(root);
  root.dataset.effect = detail.effectId;
  root.dataset.source = detail.source;
  root.dataset.phase = reducedMotion ? 'reduced' : 'celebrating';
  root.hidden = false;
  stage.dataset.paused = documentRef.hidden ? 'true' : 'false';
  stage.hidden = false;
  title.textContent = detail.source === 'djuke' ? 'DJuke · payment confirmed' : detail.title;
  summary.textContent = paymentLine(detail);

  subtitle.textContent = detail.txLabel || detail.source || `Tx ${detail.txHash.slice(0, 10)}…`;
  link.href = detail.explorerUrl;
  link.textContent = `Open ${detail.txHash.slice(0, 10)}…`;
  try {
    if (detail.source === 'djuke') stage.replaceChildren();
    else stage.innerHTML = RENDERERS[detail.effectId](detail, reducedMotion);
  } catch (error) {
    stage.replaceChildren();
    console.error('[payment-celebration] Animation failed; payment remains confirmed:', error);
  }
  positionDjuke();
  if (reducedMotion) {
    state.timer = windowRef.setTimeout(() => {
      hide();
      state.timer = null;
      showNext();
    }, REDUCED_MOTION_DURATION_MS);
    return;
  }
  state.timer = windowRef.setTimeout(() => {
    root.dataset.phase = 'compact';
    stage.hidden = true;
    stage.replaceChildren();
    state.timer = windowRef.setTimeout(() => {
      hide();
      state.timer = null;
      showNext();
    }, COMPACT_DURATION_MS);
  }, ACTIVE_DURATION_MS);
};

const show = detail => {
  queue.push(detail);
  showNext();
};

const pause = () => {
  stage.dataset.paused = documentRef.hidden ? 'true' : 'false';
};

dismiss.addEventListener('click', () => {
  hide();
  windowRef.setTimeout(() => showNext(), DEFAULT_PAUSE_MS);
});
documentRef.addEventListener('visibilitychange', pause);
windowRef.addEventListener?.('resize', positionDjuke);
documentRef.addEventListener('left-drawer-open', positionDjuke);

const destroy = () => {
  hide();
  documentRef.removeEventListener?.('visibilitychange', pause);
  windowRef.removeEventListener?.('resize', positionDjuke);
  documentRef.removeEventListener?.('left-drawer-open', positionDjuke);
  root.remove?.();

    controller = null;
    booted = false;
    queue = [];
  };

  controller = { show, hide, destroy };
  if (queue.length) showNext();
  return controller;
}

export function resetPaymentCelebrationState() {
  queue = [];
  seen.clear();
  effectIndex = 0;
}

export function nextPaymentCelebrationEffect() {
  return nextEffect();
}

export function announcePaymentCelebration(detail = {}) {
  const normalized = normalize(detail);
  if (!normalized) return { accepted: false, reason: 'invalid' };
  loadSeen();
  if (seen.has(normalized.key)) return { accepted: false, reason: 'duplicate', key: normalized.key };
  const effect = nextEffect();
  normalized.effectId = effect.id;
  normalized.effectLabel = effect.label;
  seen.set(normalized.key, Date.now());
  saveSeen();
  if (controller) controller.show(normalized);
  else queue.push(normalized);
  return { accepted: true, key: normalized.key, effectId: effect.id, effectLabel: effect.label };
}

export function initPaymentCelebrations(options = {}) {
  const { document: documentRef = globalThis.document, window: windowRef = globalThis.window, storage = globalThis.localStorage } = options;
  if (!documentRef || !windowRef) return null;
  const existing = ensureController(documentRef, windowRef, storage);
  if (booted) return existing;
  booted = true;
  loadSeen(storage);
  if (queue.length) existing.show(queue.shift());
  return existing;
}

if (typeof document !== 'undefined' && typeof window !== 'undefined') {
  const boot = () => initPaymentCelebrations({ document, window, storage: globalThis.localStorage });
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot, { once: true });
  else queueMicrotask(boot);
}

import { formatUsdcUnits } from './usdc-format.mjs?v=20261017-mercury-release';

const operations = new Map();

function formatEther(wei) {
  const value = BigInt(wei);
  return `${value / 10n ** 18n}.${(value % 10n ** 18n).toString().padStart(18, '0')}`.replace(/\.?0+$/, '') || '0';
}

export async function payrollTransactionFee(receipt, provider, txHash) {
  try {
    const execution = receipt.fee ?? (receipt.gasUsed != null && receipt.gasPrice != null
      ? BigInt(receipt.gasUsed) * BigInt(receipt.gasPrice) : null);
    const raw = receipt.l1Fee != null ? receipt : await provider.send('eth_getTransactionReceipt', [txHash]);
    if (execution == null || raw?.l1Fee == null) throw new Error('Receipt is missing execution or Base L1 data fees');
    return { wei: BigInt(execution) + BigInt(raw.l1Fee) + BigInt(raw.operatorFee ?? 0), error: null };
  } catch (error) {
    console.warn('[payroll] Confirmed transaction fee unavailable:', txHash, error);
    return { wei: null, error: error.message };
  }
}

function operationFor(week) {
  if (!operations.has(week)) operations.set(week, { transactions: new Map(), statuses: new Map() });
  return operations.get(week);
}

function render(week) {
  if (typeof document === 'undefined') return;
  const operation = operationFor(week);
  if (!operation.transactions.size) return;
  let panel = document.getElementById('payroll-confirmations');
  if (!panel) {
    panel = document.createElement('section');
    panel.id = 'payroll-confirmations';
    panel.setAttribute('aria-label', 'Payroll confirmations');
    const close = document.createElement('button');
    close.type = 'button';
    close.className = 'payroll-btn payroll-btn-secondary';
    close.textContent = 'Close';

  close.setAttribute('aria-label', 'Close payroll confirmations');
  close.addEventListener('click', () => { panel.hidden = true; });
  const title = document.createElement('h3');
  title.textContent = 'Payroll confirmations';
  const content = document.createElement('div');
  content.className = 'payroll-confirmations-content';
  panel.append(close, title, content);
  document.body.append(panel);
}
panel.hidden = false;
const content = panel.querySelector('.payroll-confirmations-content');
content.replaceChildren();
const heading = document.createElement('p');
heading.textContent = `${week} · this browser session`;
const status = document.createElement('p');
status.setAttribute('role', 'status');
status.textContent = [...operation.statuses].map(([category, text]) => `${category === 'playback' ? 'Playback' : 'Top 10'}: ${text}`).join(' · ');
const list = document.createElement('ol');
let playback = 0n;
let top10 = 0n;
let gas = 0n;
let missingFees = 0;
let payments = 0;
for (const transaction of operation.transactions.values()) {
  const { txHash, kind, category, wallet, amountUnits, fee, entries } = transaction;
  if (kind === 'payout') {
    payments++;
    if (category === 'playback') playback += BigInt(amountUnits);
    else top10 += BigInt(amountUnits);
  }
  if (fee.wei == null) missingFees++;
  else gas += fee.wei;
  const row = document.createElement('li');
  const link = document.createElement('a');
  link.href = `https://basescan.org/tx/${txHash}`;
  link.target = '_blank';
  link.rel = 'noopener noreferrer';
  link.textContent = kind === 'failed' ? `Reverted transaction: ${wallet} (no payment)`
    : kind === 'approval' ? `Wallet enabled: ${wallet}`

      : `${category === 'playback' ? 'Playback' : 'Top 10'}: ${formatUsdcUnits(amountUnits)} USDC to ${wallet}${entries > 1 ? ` (${entries} prizes)` : ''}`;
    const cost = document.createElement('small');
    cost.textContent = fee.wei == null ? `Gas unavailable: ${fee.error}. See transaction for fees.`
      : `Gas: ${formatEther(fee.wei)} ETH`;
    row.append(link, cost);
    list.append(row);
  }
  const totals = document.createElement('p');
  totals.className = 'payroll-confirmations-totals';
  totals.textContent = `${payments} payments · Playback ${formatUsdcUnits(playback)} USDC · Top 10 ${formatUsdcUnits(top10)} USDC · Total paid ${formatUsdcUnits(playback + top10)} USDC`;
  const fees = document.createElement('p');
  fees.textContent = `Gas spent${missingFees ? ' (known subtotal)' : ''}: ${formatEther(gas)} ETH · includes wallet approvals and Base L1 data fees${missingFees ? ` · ${missingFees} transaction fee(s) unavailable; total incomplete` : ''}`;
  content.append(heading, status, list, totals, fees);
}

export async function recordPayrollConfirmation({ week, receipt, provider, ...transaction }) {
  const operation = operationFor(week);
  const key = transaction.txHash.toLowerCase();
  if (operation.transactions.has(key)) return;
  // Show the confirmed transfer immediately; fee lookup must not delay its proof.
  operation.transactions.set(key, { ...transaction, fee: { wei: null, error: 'Loading receipt fees' } });
  render(week);
  const fee = await payrollTransactionFee(receipt, provider, transaction.txHash);
  operation.transactions.set(key, { ...transaction, fee });
  render(week);
}

export function setPayrollConfirmationStatus(week, category, status) {
  operationFor(week).statuses.set(category, status);
  render(week);
}

export const PAYROLL_TIME_ZONE = 'America/New_York';
const formatter = new Intl.DateTimeFormat('en-CA', { timeZone: PAYROLL_TIME_ZONE, year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23' });

function parts(epoch) {
  return Object.fromEntries(formatter.formatToParts(new Date(epoch)).filter(part => part.type !== 'literal').map(part => [part.type, Number(part.value)]));
}

function midnight(civil) {
  const target = civil.getTime();
  let epoch = target;
  for (let attempt = 0; attempt < 4; attempt++) {
    const local = parts(epoch);
    const displayed = Date.UTC(local.year, local.month - 1, local.day, local.hour, local.minute, local.second);
    const next = epoch + target - displayed;
    if (next === epoch) return epoch;
    epoch = next;
  }
  throw new Error('Could not resolve New York payroll midnight');
}

export function payrollPeriodFromKey(key) {
  if (!/^NY-\d{4}-\d{2}-\d{2}$/.test(key || '')) throw new Error('Invalid New York payroll week');
  const date = new Date(`${key.slice(3)}T00:00:00Z`);
  if (!Number.isFinite(date.getTime()) || date.toISOString().slice(0, 10) !== key.slice(3) || date.getUTCDay() !== 1) throw new Error('Payroll weeks must start on a valid Monday');
  const end = new Date(date); end.setUTCDate(end.getUTCDate() + 7);
  const startAt = midnight(date);
  const endAt = midnight(end);
  return { week: key, timeZone: PAYROLL_TIME_ZONE, startAt: new Date(startAt).toISOString(), endAt: new Date(endAt).toISOString() };
}

export function weekNumberFromKey(key) {
  const zero = Date.parse('2026-10-12T00:00:00Z');
  const weekStart = Date.parse(`${String(key || '').slice(3)}T00:00:00Z`);

  if (!/^NY-\d{4}-\d{2}-\d{2}$/.test(key || '') || !Number.isFinite(weekStart)) throw new Error('Invalid New York payroll week');
  return Math.max(0, Math.round((weekStart - zero) / (7 * 86400000)));
}

export function currentPayrollPeriod(now = Date.now()) {
  const local = parts(Number(now));
  const monday = new Date(Date.UTC(local.year, local.month - 1, local.day));
  monday.setUTCDate(monday.getUTCDate() - (monday.getUTCDay() + 6) % 7);
  return payrollPeriodFromKey(`NY-${monday.toISOString().slice(0, 10)}`);
}

export function payrollPeriods(count = 12, now = Date.now()) {
  count = Math.max(1, Math.min(52, Number(count) || 12));
  const current = currentPayrollPeriod(now);
  const monday = new Date(`${current.week.slice(3)}T00:00:00Z`);
  return Array.from({ length: Math.max(1, Math.min(52, count)) }, (_, index) => {
    const date = new Date(monday); date.setUTCDate(date.getUTCDate() - (count - index - 1) * 7);
    return payrollPeriodFromKey(`NY-${date.toISOString().slice(0, 10)}`);
  });
}

export function overlappingUtcWeeks(period) {
  return [...new Set([Date.parse(period.startAt), Date.parse(period.endAt) - 1].map(epoch => {
    const date = new Date(epoch); date.setUTCHours(0, 0, 0, 0);
    date.setUTCDate(date.getUTCDate() + 4 - (date.getUTCDay() || 7));
    const year = date.getUTCFullYear();
    return `${year}-W${String(Math.ceil((((date - Date.UTC(year, 0, 1)) / 86400000) + 1) / 7)).padStart(2, '0')}`;
  }))];
}

