    if (operation && !operation.txHash && (error.code === 4001 || error.code === 'ACTION_REJECTED')) localStorage.removeItem(key);
    _setStatus(status, `${error.message}. Check any unresolved receipt before depositing again.`, true);
  }
  finally {
    _settling = false;
