const ADDRESS = /^0x[0-9a-f]{40}$/i;
const HASH = /^0x[0-9a-f]{64}$/i;
const PREFIX = 'decentbusking:personal-play:v1:';

function validate(session) {
  if (!session || !ADDRESS.test(session.payer) || !ADDRESS.test(session.contract) || !HASH.test(session.txHash) ||
      !['pending', 'confirmed', 'completed', 'failed'].includes(session.status) ||
      !Array.isArray(session.items) || !session.items.length || session.items.length > 50 ||
      session.items.some(item => !HASH.test(item.songId) || typeof item.audioUrl !== 'string' || !item.audioUrl) ||
      !Number.isInteger(session.index) || session.index < 0 || session.index >= session.items.length ||
      !Number.isFinite(session.position) || session.position < 0) {
    throw new Error('Saved Personal Play session is invalid. Do not purchase again; keep your transaction receipt.');
  }
  return session;
}

export function createPersonalPlayRecovery(storage = globalThis.localStorage) {
  const key = payer => {
    if (!ADDRESS.test(payer)) throw new Error('Connect the wallet that purchased Personal Play.');
    return `${PREFIX}${payer.toLowerCase()}`;
  };
  function list(payer) {
    const raw = storage.getItem(key(payer));
    if (!raw) return [];
    let sessions;
    try { sessions = JSON.parse(raw); }
    catch { throw new Error('Personal Play recovery data could not be read. Do not purchase again; keep your transaction receipt.'); }
    if (!Array.isArray(sessions)) throw new Error('Invalid Personal Play recovery data.');
    return sessions.map(validate).map(session => {
      if (session.payer.toLowerCase() !== payer.toLowerCase()) throw new Error('Personal Play recovery wallet mismatch.');
      return session;
    });
  }
  function write(payer, sessions) {

    try { storage.setItem(key(payer), JSON.stringify(sessions)); }
    catch { throw new Error('Personal Play recovery could not be saved. Enable browser storage before purchasing; if already paid, do not purchase again.'); }
  }
  function check(payer, songIds) {
    const sessions = list(payer);
    if (sessions.some(session => ['pending', 'confirmed'].includes(session.status) &&
        session.items.length === songIds.length &&
        session.items.every((item, index) => item.songId.toLowerCase() === songIds[index].toLowerCase()))) {
      throw new Error('This playlist already has an unfinished Personal Play purchase. Resume it in Profile → Playlists instead of paying again.');
    }
    write(payer, sessions);
  }
  function save({ payer, contract, txHash, items, name = 'Personal playlist' }) {
    const sessions = list(payer);
    if (sessions.some(session => session.txHash.toLowerCase() === txHash.toLowerCase())) return;
    const session = validate({ payer, contract, txHash, name, status: 'pending', index: 0, position: 0,
      items: items.map(item => ({ songId: item.songId, title: item.title || 'Untitled song',
        artist: item.artist || '', audioUrl: item.audioUrl, mediaType: item.mediaType || '' })) });
    write(payer, [...sessions.filter(entry => !['completed', 'failed'].includes(entry.status)), session]);
  }
  function update(payer, txHash, changes) {
    const sessions = list(payer);
    const session = sessions.find(entry => entry.txHash.toLowerCase() === txHash.toLowerCase());
    if (!session) throw new Error('Personal Play recovery session is missing. Do not purchase again.');
    Object.assign(session, changes);
    validate(session);
    write(payer, sessions);
    return session;
  }
  return { list, check, save, update };
}

export async function verifyPersonalPlaySession(session, provider) {
  if (Number((await provider.getNetwork()).chainId) !== 8453) throw new Error('Switch to Base to verify your Personal Play purchase.');
  const receipt = await provider.getTransactionReceipt(session.txHash);
  if (!receipt) throw new Error('Your purchase is still awaiting confirmation. Retry Resume later; do not pay again.');
  if (receipt.from?.toLowerCase() !== session.payer.toLowerCase() ||
      receipt.to?.toLowerCase() !== session.contract.toLowerCase()) throw new Error('Personal Play transaction does not match the saved purchase.');
  if (receipt.status !== 1) {
    const error = new Error('Your Personal Play transaction reverted; playback was not purchased.');
    error.code = 'PERSONAL_PLAY_REVERTED';
    throw error;
  }
  return receipt;
}

export function buildCommunityPinManifest({ checkpointCid = '', tracks = [], albumRoots = [], generatedAt = new Date().toISOString() }) {
  const entries = new Map();
  const add = (cid, kind, title = '') => {
    if (typeof cid !== 'string' || !cid) return;
    const [root, ...pathParts] = cid.replace(/^ipfs:\/\//, '').split('/');
    if (!/^b[a-z2-7]{20,}$/i.test(root) && !/^Qm[1-9A-HJ-NP-Za-km-z]{44}$/.test(root)) throw new Error('Invalid CID in community pin manifest');
    const canonical = root;
    const prior = entries.get(canonical) || { cid: canonical, kinds: [], titles: [] };
    if (!prior.kinds.includes(kind)) prior.kinds.push(kind);
    if (title && !prior.titles.includes(title)) prior.titles.push(title);
    if (pathParts.length) prior.paths = [...new Set([...(prior.paths || []), pathParts.join('/')])];
    entries.set(canonical, prior);
  };
  if (checkpointCid) add(checkpointCid, 'playlist-checkpoint');
  for (const track of tracks) add(track.ipfsCid, 'audio', track.title || '');
  for (const album of albumRoots) add(album.cid, 'album', album.title || '');
  return { schemaVersion: 1, chainId: 8453, generatedAt, entryCount: entries.size,
    entries: [...entries.values()].sort((first, second) => first.cid.localeCompare(second.cid)),
    rewardStatus: 'not-active', rewardPolicy: 'Rewards use verified availability-check counts; adding a pin alone is not currently reward-eligible.' };
}

export async function pinCommunityManifest({ manifest, provider, pinataJwt = '', ipfsApiUrl = 'http://127.0.0.1:5001',
  fetchImpl = fetch, onProgress = () => {} }) {
  if (!manifest || manifest.schemaVersion !== 1 || !Array.isArray(manifest.entries) || manifest.entries.length > 1000) {
    throw new Error('Invalid community pin manifest');
  }

if (!['local', 'pinata'].includes(provider)) throw new Error('Choose IPFS Desktop or your own Pinata account');
if (provider === 'pinata' && !pinataJwt.trim()) throw new Error('Enter your Pinata API key for this session');
const successes = [];
const failures = [];
for (let index = 0; index < manifest.entries.length; index++) {
  const cid = manifest.entries[index].cid;
  if (!/^b[a-z2-7]{20,}$/i.test(cid) && !/^Qm[1-9A-HJ-NP-Za-km-z]{44}$/.test(cid)) {
    failures.push({ cid: String(cid), error: 'Invalid CID' });
    onProgress({ completed: index + 1, total: manifest.entries.length, cid });
    continue;
  }
  try {
    if (provider === 'local') {
      const base = new URL(ipfsApiUrl);
      if (!['127.0.0.1', 'localhost', '[::1]'].includes(base.hostname)) throw new Error('Local IPFS must be loopback');
      const query = new URLSearchParams({ arg: cid, recursive: 'true' });
      const response = await fetchImpl(`${ipfsApiUrl.replace(/\/$/, '')}/api/v0/pin/add?${query}`, {
        method: 'POST', signal: AbortSignal.timeout(30000),
      });
      if (!response.ok) throw new Error(`IPFS Desktop returned ${response.status}`);
      const verify = await fetchImpl(`${ipfsApiUrl.replace(/\/$/, '')}/api/v0/pin/ls?${new URLSearchParams({ arg: cid, type: 'recursive' })}`, {
        method: 'POST', signal: AbortSignal.timeout(15000),
      });
      if (!verify.ok) throw new Error(`IPFS Desktop pin verification returned ${verify.status}`);
      const pins = (await verify.json()).Keys || {};
      if (!Object.keys(pins).some(value => value.toLowerCase() === cid.toLowerCase() && pins[value].Type === 'recursive')) {
        throw new Error('IPFS Desktop did not confirm a recursive pin');
      }
    } else {

        const response = await fetchImpl('https://api.pinata.cloud/pinning/pinByHash', {
          method: 'POST', headers: { authorization: `Bearer ${pinataJwt}`, 'content-type': 'application/json' },
          body: JSON.stringify({ hashToPin: cid, pinataMetadata: { name: `DecentBusking community pin ${cid}` } }),
          redirect: 'error', signal: AbortSignal.timeout(30000),
        });
        if (!response.ok) throw new Error(`Pinata returned ${response.status}`);
      }
      successes.push(cid);
    } catch (error) { failures.push({ cid, error: error.message }); }
    onProgress({ completed: index + 1, total: manifest.entries.length, cid });
  }
  return { provider, successes, failures, rewardStatus: manifest.rewardStatus };
}

export function allocatePinnerRewards({ fundBalanceUnits, pinners, minimumChecks = 20, minimumAvailabilityBps = 9000,
  staleAfterMs = 24 * 60 * 60 * 1000, now = Date.now() }) {
  if (typeof fundBalanceUnits !== 'bigint' || fundBalanceUnits < 0n || !Array.isArray(pinners) ||
    !Number.isSafeInteger(minimumChecks) || minimumChecks < 1 || !Number.isInteger(minimumAvailabilityBps) ||
    minimumAvailabilityBps < 1 || minimumAvailabilityBps > 10000) throw new Error('Invalid pinner reward inputs');
  const eligible = pinners.map(pinner => {
    if (!/^0x[0-9a-fA-F]{40}$/.test(pinner.wallet || '') || !Number.isSafeInteger(pinner.successfulChecks) ||
      !Number.isSafeInteger(pinner.failedChecks) || pinner.successfulChecks < 0 || pinner.failedChecks < 0 ||
      !Number.isFinite(Date.parse(pinner.lastVerifiedAt || ''))) throw new Error('Invalid verified pinner record');
    const total = pinner.successfulChecks + pinner.failedChecks;
    const fresh = now - Date.parse(pinner.lastVerifiedAt) <= staleAfterMs;

    const bps = total ? Math.floor(pinner.successfulChecks * 10000 / total) : 0;
    return { wallet: pinner.wallet.toLowerCase(), score: BigInt(pinner.successfulChecks), totalChecks: total,
      availabilityBps: bps, eligible: fresh && total >= minimumChecks && bps >= minimumAvailabilityBps };
  }).filter(pinner => pinner.eligible && pinner.score > 0n).sort((first, second) => first.wallet.localeCompare(second.wallet));
  const totalScore = eligible.reduce((sum, pinner) => sum + pinner.score, 0n);
  if (totalScore === 0n || fundBalanceUnits === 0n) return { fundBalanceUnits, distributedUnits: 0n, remainingUnits: fundBalanceUnits, eligible: [] };
  let distributed = 0n;
  const rewards = eligible.map((pinner, index) => {
    const amount = index === eligible.length - 1 ? fundBalanceUnits - distributed : fundBalanceUnits * pinner.score / totalScore;
    distributed += amount;
    return { ...pinner, amountUnits: amount };
  });
  return { fundBalanceUnits, distributedUnits: distributed, remainingUnits: fundBalanceUnits - distributed, eligible: rewards };
}

import { radioCalendarOccurrences, RADIO_TIME_ZONE } from './radio-calendar.mjs?v=20261024-programming-calendar';

const ESTIMATED_SONG_MS = 4 * 60_000;
const PROTECTED_TYPES = new Set(['live_performance', 'playlist_show', 'weekly_top10']);

function duration(track) {
  const milliseconds = Number(track?.durationMs) || Number(track?.durationSeconds) * 1000;
  return Number.isFinite(milliseconds) && milliseconds > 0 ? milliseconds : null;
}

export function playlistScheduleConflict({ songIds, calendar, queue, radio, now = Date.now() }) {
  if (calendar?.ready !== true || !Array.isArray(calendar.schedule) || !Array.isArray(calendar.events)) {
    throw new Error('Public calendar is not ready. Retry Play Live before purchasing.');
  }
  if (calendar.events.some(event => !(Date.parse(event.endUtc) > Date.parse(event.startUtc)))) {
    throw new Error('Public calendar contains invalid show times. Retry Play Live before purchasing.');
  }
  if (!Array.isArray(queue?.tracks) || !Array.isArray(queue.requests) ||
      ![queue.mainPending, queue.playlistPending].every(count => Number.isSafeInteger(count) && count >= 0) ||
      !radio || !Object.hasOwn(radio, 'nowPlaying')) {
    throw new Error('Radio queue timing is unavailable. Retry Play Live before purchasing.');
  }
  const catalog = new Map(queue.tracks.map(track => [String(track.songId).toLowerCase(), track]));
  let estimatedSongs = 0;
  const songDuration = track => {
    const measured = duration(track);
    if (measured) return measured;
    estimatedSongs++;
    return ESTIMATED_SONG_MS;
  };
  const playlistMs = songIds.reduce((total, songId) => total + songDuration(catalog.get(songId.toLowerCase())), 0);
  const pending = queue.mainPending + queue.playlistPending;

if (!Number.isSafeInteger(pending)) throw new Error('Invalid radio queue size. Retry Play Live before purchasing.');
let queuedMs = 0;
const playingRequest = radio.nowPlaying?.sponsor?.kind === 'djuke' ? radio.nowPlaying.sponsor.requestId : null;
// The worker exposes only a bounded window into the pending playlist lane.
for (const request of queue.requests.slice(0, pending)) {
  if (playingRequest && request.requestId === playingRequest) continue;
  queuedMs += songDuration(catalog.get(String(request?.songId).toLowerCase()));
}
const unseenPending = Math.max(0, pending - queue.requests.length);
queuedMs += unseenPending * ESTIMATED_SONG_MS;
estimatedSongs += unseenPending;
let currentMs = 0;
if (radio.nowPlaying) {
  const playing = radio.nowPlaying;
  const track = queue.tracks.find(item => item.trackId === playing.trackId);
  const measured = duration(playing) || duration(track);
  currentMs = measured
    ? Math.max(0, measured - Math.max(0, Number(playing.positionMs) || 0))
    : songDuration(null);
}
const waitMs = currentMs + queuedMs;
const finish = now + waitMs + playlistMs;
if (!Number.isFinite(new Date(finish).getTime())) throw new Error('Radio timing estimate is out of range. Retry Play Live before purchasing.');
const events = radioCalendarOccurrences(calendar, {
  now, days: Math.min(90, Math.ceil((finish - now) / 86400_000) + 1), pastDays: 1,
});
const invalid = events.some(event => PROTECTED_TYPES.has(event.type) &&
  !(Date.parse(event.endUtc) > Date.parse(event.startUtc)));
if (invalid) throw new Error('Public calendar contains invalid show times. Retry Play Live before purchasing.');
const event = events.find(item => item.status !== 'cancelled' && PROTECTED_TYPES.has(item.type) &&

    Date.parse(item.startUtc) < finish && Date.parse(item.endUtc) > now);
  return event ? { event, playlistMs, waitMs, estimatedSongs, estimatedFinishUtc: new Date(finish).toISOString() } : null;
}

export async function checkPlaylistSchedule({ songIds, config, fetchImpl = fetch, signal }) {
  const service = String(config.ipfsUploadServiceUrl || '').replace(/\/$/, '');
  const load = async path => {
    const response = await fetchImpl(`${service}${path}`, { cache: 'no-store',
      signal: signal ? AbortSignal.any([signal, AbortSignal.timeout(10000)]) : AbortSignal.timeout(10000) });
    if (!response.ok) throw new Error('Could not check the public radio calendar and queue. Retry Play Live; no approval or purchase was requested.');
    return response.json();
  };
  const [calendar, queue, radio] = await Promise.all([
    load('/api/radio/schedule'), load('/api/djuke'), load('/api/radio'),
  ]);
  signal?.throwIfAborted();
  return playlistScheduleConflict({ songIds, calendar, queue, radio });
}

export function playlistConflictMessage(conflict) {
  const format = value => new Intl.DateTimeFormat('en-US', { timeZone: RADIO_TIME_ZONE,
    weekday: 'short', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit', timeZoneName: 'short',
  }).format(new Date(value));
  const minutes = value => Math.ceil(value / 60_000);
  return `Possible Play Live schedule conflict\n\n"${conflict.event.title}"\n${format(conflict.event.startUtc)} – ${format(conflict.event.endUtc)}\n\n` +
    `Your mix is about ${minutes(conflict.playlistMs)} minutes, plus about ${minutes(conflict.waitMs)} minutes of current/queued audio. ` +
    (conflict.estimatedSongs ? 'Unknown song lengths use a rough 4-minute-per-song allowance. ' : '') +

    'This estimated window overlaps the protected block. Queue timing can change; exact start and finish times are not guaranteed.\n\n' +
    'Your playlist may wait or be set aside for the show. Remaining songs return to the queue afterward without another payment. ' +
    'There is no refund solely for that delay or interruption; separate failed-delivery refunds still apply.\n\n' +
    'Select OK to continue to checkout, or Cancel to keep your playlist without purchasing.';
}

export function appendPlaylistSong(items, item) {
  if (items.some(song => song.songId.toLowerCase() === item.songId.toLowerCase())) return [...items];
  if (items.length >= 24) throw new Error('Named playlists hold up to 24 songs. Remove a song before adding another.');
  return [...items, item];
}

export function openPlaylistSelector({ anchor, playlists = [], choose, status = () => {} }) {
  document.querySelector('.playlist-selector')?.remove();
  const panel = document.createElement('div');
  panel.className = 'playlist-selector';
  panel.setAttribute('role', 'dialog');
  panel.setAttribute('aria-label', 'Add song to playlist');
  const heading = document.createElement('strong');
  heading.textContent = 'Add to playlist';
  panel.append(heading);
  const add = (label, action) => {
    const button = document.createElement('button');
    button.type = 'button'; button.textContent = label;
    button.addEventListener('click', async () => {
      button.disabled = true;
      try { if (await action() !== false) { panel.remove(); anchor?.focus(); } }
      catch (error) { message.textContent = error.message; status(error.message); }
      finally { button.disabled = false; }
    });
    panel.append(button);
    return button;
  };
  const message = document.createElement('p');
  message.setAttribute('role', 'status');
  add('Current draft', () => choose(null));
  for (const playlist of playlists) add(`${playlist.name} · ${playlist.songIds.length}/24`, () => choose(playlist));
  const name = document.createElement('input');
  name.maxLength = 60; name.placeholder = 'New playlist name'; name.hidden = true;
  name.setAttribute('aria-label', 'New playlist name');
  add('➕ New playlist…', () => {
    name.hidden = false; create.hidden = false; name.focus();

    return false;
  });
  panel.append(name);
  const create = add('Create playlist', async () => {
    if (!name.value.trim()) throw new Error('Enter a playlist name.');
    await choose(null, name.value.trim());
  });
  create.hidden = true;
  add('Cancel', () => {});
  panel.append(message);
  panel.addEventListener('click', event => event.stopPropagation());
  panel.addEventListener('keydown', event => { if (event.key === 'Escape') { event.stopPropagation(); panel.remove(); anchor?.focus(); } });
  document.body.append(panel);
  const rect = anchor?.getBoundingClientRect();
  panel.style.left = `${Math.max(8, Math.min(rect?.left ?? 24, window.innerWidth - 290))}px`;
  panel.style.top = `${Math.max(8, Math.min(rect?.bottom ?? 100, window.innerHeight - panel.offsetHeight - 12))}px`;
  panel.querySelector('button')?.focus();
  return panel;
}

