async function _resolveSponsorName(wallet) {
  const key = String(wallet || '').toLowerCase();
  if (!/^0x[0-9a-f]{40}$/.test(key) || _sponsorEnsCache.has(key) || _sponsorEnsPending.has(key)) return null;
