export async function addChartSongToPlaylist(track, {
  wallet = window._wallet,
  resolveNFT = async detail => {
    const { resolveNowPlayingNFT } = await import('./space.js?v=20261025-seamless-handoff');
    return resolveNowPlayingNFT(detail, { requireMediaMatch: true });
  },
  save = async nft => {
    const event = new CustomEvent('dbusk-playlist-add', { cancelable: true, detail: { nft } });
    if (document.dispatchEvent(event)) throw new Error('DJuke playlist controls are unavailable');
  },
} = {}) {
  if (!track.ipfsCid) throw new Error('This song does not have verified media for your playlist yet.');
  if (!wallet?.address || !wallet?.signer) await wallet?.connect?.();
  if (!wallet?.address || !wallet?.signer) throw new Error('Connect your wallet to add songs to your named playlist draft.');
  const nft = await resolveNFT({
    title: track.title,
    artist: track.artist || track.uploader,
    audioUrl: `ipfs://${track.ipfsCid}`,
    ipfsCid: track.ipfsCid,
  });
  if (!nft) throw new Error('No verified NFT was found for this song. It has not been added.');
  await save(nft);
  return nft;
}

export async function saveChartSongToWatchlist(track, {
  wallet = window._wallet,
  resolveNFT = async detail => {
    const { resolveNowPlayingNFT } = await import('./space.js?v=20261025-seamless-handoff');
    return resolveNowPlayingNFT(detail, { requireMediaMatch: true });
  },
  watchlist = async () => import('./watchlist.mjs?v=20261025-seamless-handoff'),
} = {}) {
  if (!track.ipfsCid) throw new Error('This song does not have verified media yet.');
  if (!wallet?.address || !wallet?.signer) await wallet?.connect?.();
  if (!wallet?.address || !wallet?.signer) throw new Error('Connect your wallet to save your watchlist.');

  const nft = await resolveNFT({ title: track.title, artist: track.artist || track.uploader,
    audioUrl: `ipfs://${track.ipfsCid}`, ipfsCid: track.ipfsCid });
  if (!nft) throw new Error('No verified NFT was found for this song.');
  const { saveCreatorWatchlist, isCreatorWatchlisted } = await watchlist();
  if (!isCreatorWatchlisted(nft)) await saveCreatorWatchlist(nft);
  return nft;
}

export const TOP_TEN_MINIMUM_PRIZE_UNITS = 100001n;

function hasPayoutWallet(wallet) {
  return /^0x[0-9a-fA-F]{40}$/.test(wallet || '') && !/^0x0{40}$/i.test(wallet);
}

export function rankTopTenSongs(tracks, nowPlayingId = '') {
  return tracks.filter(track => typeof track.trackId === 'string' && track.trackId && Number.isSafeInteger(track.votes) &&
    (track.plays > 0 || track.votes !== 0))
    .slice().sort((first, second) => second.votes - first.votes || second.plays - first.plays ||
      String(first.title).localeCompare(String(second.title)) || first.trackId.localeCompare(second.trackId))
    .slice(0, 10).map((track, index) => ({ ...track, rank: index + 1, nowPlaying: track.trackId === nowPlayingId }));
}

export function previewTopTenSongPayroll({ tracks, budgetUnits, minimumUnits = TOP_TEN_MINIMUM_PRIZE_UNITS }) {
  if (typeof budgetUnits !== 'bigint' || budgetUnits < 0n || typeof minimumUnits !== 'bigint' || minimumUnits < 0n) {
    throw new Error('Budgets must be nonnegative token-unit amounts');
  }
  const minimum = minimumUnits > TOP_TEN_MINIMUM_PRIZE_UNITS ? minimumUnits : TOP_TEN_MINIMUM_PRIZE_UNITS;
  const songs = rankTopTenSongs(tracks).filter(song => song.votes > 0);
  if (!songs.length || budgetUnits < minimum) return { entries: [], allocatedUnits: 0n, forfeitedUnits: 0n, remainderUnits: budgetUnits };
  const entries = [];
  let remaining = budgetUnits;
  let allocated = 0n;
  let forfeitedUnits = 0n;
  for (const song of songs) {
    const half = remaining / 2n;
    const last = song === songs.at(-1) || half < minimum;
    const amountUnits = last ? remaining : half;
    const linked = hasPayoutWallet(song.wallet);
    entries.push({ ...song, amountUnits, payable: linked });
    if (linked) allocated += amountUnits;

    else forfeitedUnits += amountUnits;
    remaining -= amountUnits;
    if (last) break;
  }
  return { entries, allocatedUnits: allocated, forfeitedUnits, remainderUnits: budgetUnits - allocated };
}

