  if (!_overlay || _overlay.hidden || !window.innerWidth) return;
  const width = window.innerWidth;
  const height = window.innerHeight;
  let bounds = _currentTarget?.getBoundingClientRect();
  if (_splitOnly && _splitHop > 0) {
