function parseIssueForm(body) {
  const fields = {};
  const pattern = /(?:^|\r?\n)### ([^\r\n]+)\r?\n+([\s\S]*?)(?=\r?\n### |$)/g;
  for (const match of String(body || '').matchAll(pattern)) fields[match[1].trim()] = match[2].trim();
  return fields;
}

