    contract: { ...contract, gasWorker: async () => `0x${'34'.repeat(20)}` }, workerAddress }), /does not match/);
  await assert.rejects(verifyDjukePlaylistWorker({ provider,
    contract: { ...contract, hasRole: async () => false }, workerAddress }), /fulfiller role/);
