test('real audio frames advance from an ad back to music without a Discord voice subscriber', async t => {
  const { JukeLoopSession, createJukeLoopSession, getActiveJukeLoopSession, monitorAudioCompletion } = await import('../discord-bot/jukeloop.js');
  const { spawn } = require('node:child_process');
  const voice = require('../discord-bot/node_modules/@discordjs/voice');
  const session = createJukeLoopSession('headless-audio-test', {
    websitePlayback: true, client: { isReady: () => false },
  });
  assert.ok(session instanceof JukeLoopSession);
  const completed = [];
  session.djuke = { complete: async (record, play) => { completed.push({ record, play }); } };
  session._primeNext = () => {};
  session._prepareNextPlayback = async () => null;
  session._voiceConnection = { getState: () => ({ voiceConnected: false }), stop() {} };
  const child = spawn('ffmpeg', ['-f', 'lavfi', '-i', 'sine=frequency=440:duration=0.5',
    '-f', 's16le', '-ar', '48000', '-ac', '2', 'pipe:1'], { stdio: ['ignore', 'pipe', 'ignore'] });

t.after(() => { session.destroy(); child.kill(); });
const completion = monitorAudioCompletion(child.stdout, child);
const resource = voice.createAudioResource(completion.stream, { inputType: voice.StreamType.Raw });
const idle = new Promise((resolve, reject) => {
  session.player.once(voice.AudioPlayerStatus.Idle, resolve);
  session.player.once('error', reject);
  child.once('error', reject);
});
const paid = { kind: 'devert', tier: 1, requestId: 'test', payer: '0x405Bb3Cdf23833bb27BAD6629b7cd4f01688235f', amountUnits: '2000000' };
const track = { trackId: 'devert:99', title: 'Real decoded advert', campaignId: '99', ipfsCid: 'test' };
session._startPrepared({ track, resource, completion, ffmpegProcess: child, queueIndex: null,
  paid: { record: paid }, devertAd: { campaignId: '99', track, paidRequest: true } });
await voice.entersState(session.player, voice.AudioPlayerStatus.Playing, 5000);
assert.equal(session.getPlaybackStatus().ready, true, 'voice disconnection must not mark the website offline');
assert.equal(completed.length, 0, 'starting or announcing an ad never settles payment');
const musicStream = new PassThrough();
musicStream.end(Buffer.alloc(48000 * 2 * 2));
session._preparedNext = {
  track: { trackId: 'music-after-ad', title: 'Music returns', ipfsCid: 'music' },
  resource: voice.createAudioResource(musicStream, { inputType: voice.StreamType.Raw }),
  ffmpegProcess: { exitCode: 0, kill() { musicStream.destroy(); } }, queueIndex: null,
};
await Promise.race([idle, new Promise((_, reject) => {
  const timer = setTimeout(() => reject(new Error('Audio did not naturally finish')), 5000);
  timer.unref();
})]);
assert.equal(completed.length, 1);
assert.equal(completed[0].record, paid);

  assert.equal(completed[0].play.finished, true);
  assert.ok(completed[0].play.audibleMs >= 400, 'PCM must be consumed in real time, not drained immediately');
  assert.equal(session._nowPlaying, null);
  await voice.entersState(session.player, voice.AudioPlayerStatus.Playing, 5000);
  assert.equal(session._nowPlaying.trackId, 'music-after-ad');
  assert.equal(session.getPlaybackStatus().ready, true);
  session.destroy();
  assert.notEqual(getActiveJukeLoopSession(), session, 'headless sessions unregister without a voice guild');
});

test('playlist counters schedule routine writes while pin/mint changes and persistence barriers remain durable', async t => {
  const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'decent-playlist-checkpoint-'));
  process.env.JUKELOOP_PLAYLIST_PATH = path.join(tempDir, 'playlist.json');
  t.after(() => { delete process.env.JUKELOOP_PLAYLIST_PATH; fs.rmSync(tempDir, { recursive: true, force: true }); });
  const storeUrl = pathToFileURL(path.join(__dirname, '../discord-bot/playlist-store.js'));
  storeUrl.searchParams.set('test', 'routine-checkpoint');
  const store = await import(storeUrl.href);
  store.loadPlaylist([]);
  const saved = [];
  const history = [];
  let pending;
  store.configureRemotePersistence(async (state, { events }) => { saved.push(state); history.push(...events); pending = null; }, {
    schedule: (state, { events }) => { pending = state; history.push(...events); },
    flush: async () => { if (pending) { saved.push(pending); pending = null; } },
  });
  store.addTrack({ messageId: 'message', attachmentId: 'song', filename: 'song.mp3' });
  await store.waitForRemotePersistence();
  assert.equal(saved.length, 1);
  assert.equal(history[0].type, 'submission');

  for (let count = 0; count < 100; count++) store.applySiteVote('song', 1);
  await new Promise(resolve => setImmediate(resolve));
  assert.equal(saved.length, 1);
  assert.equal(pending[0].likes, 100);
  assert.equal(history.filter(event => event.type === 'vote').length, 100);
  assert.equal(new Set(history.map(event => event.id)).size, 101);
  assert.ok(history.every(event => Number.isFinite(Date.parse(event.observedAt))));
  await store.waitForRemotePersistence();
  assert.equal(saved.length, 2);
  assert.equal(saved[1][0].likes, 100);
  store.updateTrackPin('song', { status: 'pinned', ipfsCid: 'bafyaudio' });
  await store.waitForRemotePersistence();
  assert.equal(saved.length, 3);
  assert.equal(saved[2][0].ipfsCid, 'bafyaudio');
  const now = Date.now();
  const play = { playId: 'audible-play', startedAt: now - 60000, endedAt: now, audibleMs: 60000 };
  assert.equal(store.recordAudiblePlay('song', play).counted, true);
  assert.equal(store.recordAudiblePlay('song', play).reason, 'duplicate');
  store.applyRating('song', 2, 0, 'announcement');
  store.applyRating('song', 2, 0, 'announcement');
  await store.waitForRemotePersistence();
  assert.equal(history.filter(event => event.type === 'play').length, 1);
  assert.equal(history.filter(event => event.source === 'discord' && event.type === 'vote').length, 1);
  const playEvent = history.find(event => event.type === 'play');
  assert.equal(playEvent.occurredAt, new Date(now).toISOString());
  assert.equal(playEvent.audibleMs, 60000);
  store.configureRemotePersistence(async () => { throw new Error('IPFS offline'); });
  store.requestTrackMint('song', undefined, `0x${'1'.repeat(40)}`, 'bafyart');
  await assert.rejects(store.waitForRemotePersistence(), /IPFS offline/);
});

