test('metadata retries transient gateway failures and falls back for HTTP IPFS URLs', async () => {
  const { fetchMintMetadata } = await import(moduleUrl);
  let requests = 0;
  const delays = [];
  const metadata = await fetchMintMetadata('ipfs://retry-metadata', async () => {
    requests++;
