const { pathToFileURL } = require('node:url');
const path = require('node:path');
const url = pathToFileURL(path.join(__dirname, '../js/payroll-week.mjs')).href;

test('payroll rolls Monday at midnight New York time rather than UTC midnight', async () => {
  const { currentPayrollPeriod, payrollPeriodFromKey } = await import(url);
  assert.equal(currentPayrollPeriod(Date.parse('2026-10-12T03:59:59Z')).week, 'NY-2026-10-05');
  assert.equal(currentPayrollPeriod(Date.parse('2026-10-12T04:00:00Z')).week, 'NY-2026-10-12');
  assert.equal(payrollPeriodFromKey('NY-2026-10-05').endAt, '2026-10-12T04:00:00.000Z');
  assert.throws(() => payrollPeriodFromKey('NY-2026-10-06'), /Monday/);
  assert.throws(() => payrollPeriodFromKey('NY-2026-02-30'));
});

test('New York payroll accounts for short and long DST weeks and year rollover', async () => {
  const { payrollPeriodFromKey, currentPayrollPeriod, payrollPeriods } = await import(url);
  const spring = payrollPeriodFromKey('NY-2026-03-02');
  const fall = payrollPeriodFromKey('NY-2026-10-26');
  assert.equal((Date.parse(spring.endAt) - Date.parse(spring.startAt)) / 3600000, 167);
  assert.equal((Date.parse(fall.endAt) - Date.parse(fall.startAt)) / 3600000, 169);
  assert.equal(currentPayrollPeriod(Date.parse('2027-01-01T12:00:00Z')).week, 'NY-2026-12-28');
  assert.equal(payrollPeriods(2, Date.parse('2026-10-08T12:00:00Z'))[0].week, 'NY-2026-09-28');
});

test('a paid overlapping UTC receipt blocks New York payments instead of paying twice', async () => {
  const { finalizeRadioAllocation, radioWorkReferenceText, settleRadioAllocation } = await import(pathToFileURL(path.join(__dirname, '../js/radio-payroll.mjs')).href);

  const wallet = `0x${'1'.repeat(40)}`;
  const owner = `0x${'2'.repeat(40)}`;
  const allocation = finalizeRadioAllocation({ report: { week: 'NY-2026-09-28', current: false, tracks: [{ wallet, plays: 1 }] }, category: 'playback',
    budgetUnits: 1000000n, minimumUnits: 1n, fundSlug: 'dbusk-playback', routerAddress: owner,
    assetAddress: '0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913', now: Date.parse('2026-10-06T00:00:00Z') });
  const legacy = radioWorkReferenceText({ week: '2026-W40', category: 'playback', wallet });
  const router = { target: owner, paused: async () => false, PAYROLL_ROLE: async () => 'role', hasRole: async () => true,
    approvedAssets: async () => true, funds: async () => ({ exists: true, active: true }), completedWorkReferences: async reference => reference === legacy };
  await assert.rejects(settleRadioAllocation({ allocation, router, owner, hashReference: value => value,
    signer: { getAddress: async () => owner, provider: { getNetwork: async () => ({ chainId: 8453 }) } },
    metadataUri: 'ipfs://receipt', metadataHash: `0x${'3'.repeat(64)}` }), /paid legacy UTC receipt overlaps/);
});

test('New York receipts freeze the correct period and keep legacy references separate', async () => {
  const { finalizeRadioAllocation, radioWorkReferenceText, validateRadioReceipt } = await import(pathToFileURL(path.join(__dirname, '../js/radio-payroll.mjs')).href);
  const wallet = `0x${'1'.repeat(40)}`;
  const config = { routerAddress: `0x${'2'.repeat(40)}`, assetAddress: '0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913', funds: { playback: 'dbusk-playback' } };
  const input = { report: { week: 'NY-2026-09-28', current: false, partial: true, tracks: [{ wallet, plays: 1 }] }, category: 'playback',

    budgetUnits: 1000000n, minimumUnits: 1n, fundSlug: 'dbusk-playback', ...config, now: Date.parse('2026-10-05T04:00:00Z') };
  const receipt = finalizeRadioAllocation(input);
  assert.equal(receipt.schemaVersion, 3);
  assert.equal(receipt.partial, true);
  assert.equal(receipt.endAt, '2026-10-05T04:00:00.000Z');
  assert.equal(validateRadioReceipt(receipt, config), receipt);
  assert.notEqual(receipt.entries[0].workReferenceText, radioWorkReferenceText({ week: '2026-W40', category: 'playback', wallet }));
  assert.throws(() => finalizeRadioAllocation({ ...input, now: Date.parse('2026-10-05T03:59:59Z') }), /not completed/);
  assert.throws(() => validateRadioReceipt({ ...receipt, endAt: '2026-10-05T00:00:00Z' }, config), /boundaries/);
});

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const vm = require('node:vm');
const source = fs.readFileSync('js/payroll.js', 'utf8');
const html = fs.readFileSync('index.html', 'utf8');

test('Pay proceeds to the wallet without an extra browser confirmation', () => {
  const start = source.indexOf('async function _settleRadioPayroll(');
  const handler = source.slice(start, source.indexOf('async function _importRadioReceipt(', start));
  assert.doesNotMatch(handler, /\bconfirm\(/);
  assert.match(handler, /validateRadioReceipt\(/);
  assert.match(handler, /radioAllocationMatchesReport\(/);
  assert.match(handler, /await settleRadioAllocation\(/);
});

function fixture() {
  const entry = (number, amount = '1000000') => ({ workReferenceText: `reference-${number}`, amountUnits: amount });
  const allocation = { entries: [entry(1), entry(2, '2000000')], allocatedUnits: '3000000' };
  const context = vm.createContext({
    _radioReviews: { playback: { allocation } },
    _radioRecipientStates: new Map(allocation.entries.map(entry => [entry.workReferenceText, { paid: false, approved: true }])),
    _weeklyPayflow: { ready: true, lastError: '', backupPending: false },
    _radioBalances: { approved: true, playback: { active: true, available: 5000000n } },
    _settling: false,
    radioAllocationMatchesReport: () => true,
  });
  const start = source.indexOf('function _radioBatchState(');
  vm.runInContext(source.slice(start, source.indexOf('function _renderRadioOverview(', start)), context);
  return { context, report: { week: 'NY-2026-10-12', current: false },
    state() { context.report = this.report; return vm.runInContext('_radioBatchState("playback", report)', context); } };
}

test('ready batches require checked wallets, with missing approvals handled during Pay', () => {
  const value = fixture();
  assert.equal(value.state().tone, 'ready');
  assert.equal(value.state().ready, true);
  assert.equal(value.state().remainingUnits, 3000000n);
  value.context._radioRecipientStates.delete('reference-1');
  assert.equal(value.state().label, 'Checking Base');
  assert.equal(value.state().checking, true);
  assert.equal(value.state().ready, false);
  value.context._radioRecipientStates.set('reference-1', { paid: false, approved: false });
  assert.equal(value.state().label, 'Ready to pay');
  assert.equal(value.state().ready, true);
  assert.match(value.state().reason, /one-time approval/);
});

test('partial payment only offers remaining entries and a completed batch cannot pay again', () => {
  const value = fixture();
  value.context._radioRecipientStates.set('reference-1', { paid: true, approved: true });
  assert.equal(value.state().paid, 1);
  assert.equal(value.state().unpaid.length, 1);
  assert.equal(value.state().remainingUnits, 2000000n);
  value.context._radioRecipientStates.set('reference-2', { paid: true, approved: false });
  assert.equal(value.state().tone, 'paid');
  assert.equal(value.state().remainingUnits, 0n);
  assert.equal(value.state().ready, false);
});

test('Top 10 Pay counts distinct unpaid wallets rather than song prizes', () => {
  const value = fixture();
  const entries = value.context._radioReviews.playback.allocation.entries;
  entries[0].wallet = '0xAbC';
  entries[1].wallet = '0xabc';
  assert.equal(value.state().walletPayments, 1);
  entries[1].wallet = '0xdef';
  assert.equal(value.state().walletPayments, 2);
  value.context._radioRecipientStates.set('reference-1', { paid: true, approved: true });

  assert.equal(value.state().walletPayments, 1);
  value.context._radioRecipientStates.set('reference-2', { paid: true, approved: true });
  assert.equal(value.state().walletPayments, 0);
  assert.match(source, /batch\.walletPayments \|\| ''/);
  assert.match(source, /wallet payments remaining/);
});

test('missing receipts, open weeks and excluded rollout weeks never appear as payable zero-dollar batches', () => {
  const value = fixture();
  value.context._radioReviews = {};
  assert.equal(value.state().label, 'Waiting for receipt');
  assert.equal(value.state().ready, false);
  value.report.current = true;
  assert.equal(value.state().label, 'Week in progress');
  value.report.current = false;
  value.context._weeklyPayflow.ignoredWeeks = [value.report.week];
  assert.equal(value.state().label, 'Excluded week');
  assert.match(source, /zero is not a confirmed payout amount/);
});

test('mismatched receipts, unhealthy backups, underfunding and active settlement block pay with next-step guidance', () => {
  for (const [modify, label] of [
    [context => { context.radioAllocationMatchesReport = () => false; }, 'Receipt needs review'],
    [context => { context._weeklyPayflow = null; }, 'Preparation unavailable'],
    [context => { context._weeklyPayflow.backupPending = true; }, 'Preparation unavailable'],
    [context => { context._weeklyPayflow.lastError = 'RPC unavailable'; }, 'Preparation unavailable'],
    [context => { context._radioBalances.playback.available = 2999999n; }, 'Check fund balance'],
    [context => { context._radioBalances.approved = false; }, 'Check fund balance'],
  ]) {
    const value = fixture();
    modify(value.context);
    assert.equal(value.state().label, label);
    assert.equal(value.state().ready, false);

    assert.ok(value.state().reason.length > 20);
  }
  const value = fixture();
  value.context._settling = true;
  assert.equal(value.state().ready, false);
});

