  assert.deepEqual([bounty.amount, bounty.currency], ['12.345678', 'USDC']);
  assert.throws(() => normalizeAmount('1.0000001', 'USDC'), /at most 6 decimal places/);

  const accounts = { contributors: [{ ...owner }] };
