  button.listeners.get('click')({ stopPropagation() {} });
  assert.equal(dispatched.detail.mode, 'personal');
  assert.equal(dispatched.detail.wallet, walletA);
  window._wallet.address = null;
  events.get('wallet-disconnected')();
