test('radio sync renders the shared main-radio countdown in the footer and broadcasts state', async () => {
  const source = radioSyncSource();
  const nodes = new Map();
  const listeners = new Map();
  function element(id) {
    if (nodes.has(id)) return nodes.get(id);
    const handlers = new Map();
    const item = {
      id,
      hidden: false,
      paused: true,
      volume: 1,
      value: '100',
      textContent: '',
      style: { setProperty() {} },
      classList: { toggle() {}, add() {}, remove() {} },
      addEventListener(name, callback) { handlers.set(name, callback); },
      setAttribute() {},
      removeAttribute() {},
      querySelector(selector) {
        if (selector === '[data-volume-on]' || selector === '[data-volume-off]') return { hidden: false };
        return null;
      },
      focus() {},
      pause() {},
      play: async () => {},
      load() {},
    };
    nodes.set(id, item);
    return item;
  }

  const document = {
    readyState: 'loading',
    defaultView: { CustomEvent },
    getElementById: element,
    querySelectorAll: () => [],
    addEventListener(name, callback) {
      if (!listeners.has(name)) listeners.set(name, []);
      listeners.get(name).push(callback);
    },
    dispatchEvent(event) {
      for (const callback of listeners.get(event.type) || []) callback(event);
    },
  };
  const states = [];
  const context = vm.createContext({
    performance,
    setTimeout,
    clearTimeout,
    console,
    document,
    CustomEvent,
    states,
    fetch: async () => ({
      ok: true,
      status: 200,
      json: async () => ({
        serverTime: 100,
        nowPlaying: null,
        recent: [],
        mainRadioAdCountdown: { status: 'countdown', remainingSongs: 3, includesCurrentSong: false },
      }),
    }),
