  const nodes = Object.fromEntries(['scene-music-search', 'archive-search', 'archive-artist-filter'].map(id => [id, {
    value: '', handlers: {}, addEventListener(type, handler) { this.handlers[type] = handler; },
  }]));
  let pending;
